const STORE_KEY = 'mock.codx.dashboard'

// MOCK: single clock helper so seeded dates are always relative to "now"
const clock = () => new Date()
const DAY = 86400000

function isoDate(dt) { return new Date(dt).toISOString().slice(0, 10) }
function todayISO() { return isoDate(clock()) }
function dayOffset(offset) {
  const dt = new Date(clock())
  dt.setHours(12, 0, 0, 0)
  dt.setDate(dt.getDate() + offset)
  return isoDate(dt)
}
function stamp(offsetDays, hour) {
  const dt = new Date(clock())
  dt.setDate(dt.getDate() + offsetDays)
  dt.setHours(hour == null ? 11 : hour, 20, 0, 0)
  return dt.toISOString()
}

