// ── Tasks ──────────────────────────────────────────────────────────────────
let _taskSeq = 0
function T(o) {
  _taskSeq += 1
  const id = 't' + String(_taskSeq).padStart(2, '0')
  const progress = o.pg != null ? o.pg : (o.s === 'done' ? 100 : 0)
  return {
    id,
    project_id: o.p,
    board_id: o.b,
    name: o.n,
    status: o.s || 'todo',
