    due_date: o.due != null ? dayOffset(o.due) : null,
    progress,
    created_at: stamp(o.c != null ? o.c : -16),
    updated_at: stamp(o.u != null ? o.u : -2, 9 + (_taskSeq % 8)),
    blocked: !!o.blk,
    block_reason: o.blk || null,
    blocked_since: o.blk ? stamp(o.bs != null ? o.bs : -4) : null,
    estimate_h: o.h != null ? o.h : 8,
    tags: o.tags || []
