// ── AI consumption (deterministic pseudo-random so numbers are stable) ─────
function seeded(seed) {
  let s = seed
  return function () {
    s = (s * 1664525 + 1013904223) % 4294967296
    return s / 4294967296
  }
}

const MODELS = [
  { name: 'gpt-4o-mini', in_rate: 0.15, out_rate: 0.6 },
  { name: 'claude-sonnet-4.5', in_rate: 3.0, out_rate: 15.0 },
  { name: 'qwen2.5-coder-32b', in_rate: 0.2, out_rate: 0.8 }
]

const BUDGET = { weekly: 6000, per_project: { p1: 2600, p2: 1800, p3: 1100, p4: 500 } }

// MOCK: 60 days of usage rows (day × project × model × user)
const USAGE = (function generateUsage() {
  const rnd = seeded(20260517)
  const rows = []
  for (let back = 59; back >= 0; back -= 1) {
    const date = dayOffset(-back)
    PROJECTS.forEach(function (project) {
      MODELS.forEach(function (model) {
        if (rnd() > 0.62) return
        const human = PEOPLE.filter(function (p) { return p.type === 'human' && p.projects.indexOf(project.id) >= 0 })
        const owner = human[Math.floor(rnd() * human.length)] || PEOPLE[0]
        const weight = model.name === 'claude-sonnet-4.5' ? 0.45 : 1
        const input = Math.round((18000 + rnd() * 240000) * weight)
        const output = Math.round((4000 + rnd() * 54000) * weight)
        const calls = Math.max(2, Math.round((8 + rnd() * 90) * weight))
        rows.push({
          iso_date: date,
          project_id: project.id,
          model: model.name,
          username: owner.id,
          input_tokens: input,
          output_tokens: output,
          total_tokens: input + output,
          calls: calls,
          total_duration_seconds: Math.round(calls * (2 + rnd() * 9) * 10) / 10,
          total_cxjcoins: Math.round((input / 1000 * model.in_rate + output / 1000 * model.out_rate) * 100) / 100,
          tokens_from_provider: true
        })
      })
    })
  }
  return rows
})()

/* ═══════════════════════════════════════════════════════════════════════════
   B. MOCK SERVER — route table + mockFetch + aggregation helpers
   ═══════════════════════════════════════════════════════════════════════════ */

const MOCK = { latency: [120, 320], db: { tasks: TASKS.map(function (t) { return Object.assign({}, t) }) } }

const personById = function (id) { return PEOPLE.find(function (p) { return p.id === id }) || null }
const projectById = function (id) { return PROJECTS.find(function (p) { return p.id === id }) || null }
const boardById = function (id) { return BOARDS.find(function (b) { return b.id === id }) || null }

function rangeFromQuery(q) {
  const to = q.to || todayISO()
  if (q.from) return { from: q.from, to: to }
  if (q.start_date) return { from: q.start_date, to: q.end_date || to }
  const dt = new Date(to)
  dt.setDate(dt.getDate() - 7)
  return { from: isoDate(dt), to: to }
}

function inRange(iso, range) {
  if (!iso) return false
  const date = String(iso).slice(0, 10)
  return date >= range.from && date <= range.to
}

/**
 * Tasks "in the window": updated inside it, PLUS every unfinished task.
 * Product decision: a blocker must never disappear because it stopped moving.
 */
function windowTasks(range, projectIds) {
  const projects = projectIds && projectIds.length ? projectIds : null
  return MOCK.db.tasks.filter(function (t) {
    if (projects && projects.indexOf(t.project_id) < 0) return false
    return inRange(t.updated_at, range) || t.status !== 'done'
  })
}

function delay(iso) {
  if (!iso) return null
  return Math.round((new Date(iso) - new Date(todayISO() + 'T00:00:00')) / DAY)
}

function attentionReason(t) {
  if (t.blocked) return 'blocked'
  const dleft = delay(t.due_date)
  if (dleft != null && dleft < 0) return 'overdue'
  if (dleft === 0) return 'due_today'
  if (t.priority === 'high' && !t.assignees.length) return 'unassigned_high'
  const stale = Math.round((Date.now() - new Date(t.updated_at).getTime()) / DAY)
  if (stale >= 7) return 'stalled'
  return null
}

const SEVERITY = { blocked: 4, overdue: 3, due_today: 2, unassigned_high: 1.5, stalled: 1 }

function toPlanningTask(t) {
  const dleft = delay(t.due_date)
  const reason = attentionReason(t)
  const project = projectById(t.project_id)
  const board = boardById(t.board_id)
  return {
    id: t.id,
    name: t.name,
    description: null,
    project_id: t.project_id,
    project_name: project ? project.name : null,
    project_color: project ? project.color : null,
    board_id: t.board_id,
    board: board ? board.name : null,
    column: board ? board.type : null,
    status: t.status,
    priority: t.priority,
    due_date: t.due_date,
    progress: t.progress,
    assignees: t.assignees,
    assignee_names: t.assignees.map(function (id) { const p = personById(id); return p ? p.name : id }),
    users: t.assignees.map(function (id) { const p = personById(id); return p ? p.name : id }),
    estimate_h: t.estimate_h,
    tags: t.tags,
    created_at: t.created_at,
    updated_at: t.updated_at,
    blocked: t.blocked,
    block_reason: t.block_reason,
    blocked_since: t.blocked_since,
    overdue: dleft != null && dleft < 0 && t.status !== 'done',
    due_today: dleft === 0 && t.status !== 'done',
    days_until_due: dleft,
    unassigned: !t.assignees.length,
    attention_reason: reason
  }
}

function computeMetrics(tasks) {
  const done = tasks.filter(function (t) { return t.status === 'done' })
  const byStatus = { todo: 0, doing: 0, onhold: 0, done: 0, rejected: 0 }
  const byPriority = { high: 0, medium: 0, low: 0 }
  let overdue = 0, dueToday = 0, unassigned = 0, blocked = 0
  tasks.forEach(function (t) {
    byStatus[t.status] = (byStatus[t.status] || 0) + 1
    byPriority[t.priority] = (byPriority[t.priority] || 0) + 1
    if (t.status !== 'done') {
      const dleft = delay(t.due_date)
      if (dleft != null && dleft < 0) overdue += 1
      if (dleft === 0) dueToday += 1
    }
    if (!t.assignees.length && t.status !== 'done') unassigned += 1
    if (t.blocked) blocked += 1
  })
  return {
    total: tasks.length,
    done: done.length,
    active: byStatus.doing + byStatus.todo,
    on_hold: byStatus.onhold,
    rejected: byStatus.rejected || 0,
    overdue: overdue,
    due_today: dueToday,
    unassigned: unassigned,
    blocked: blocked,
    completion: tasks.length ? Math.round(done.length / tasks.length * 100) : 0,
    by_priority: byPriority,
    by_status: byStatus
  }
}

function activityFeed(tasks, range) {
  return tasks
    .slice()
    .sort(function (a, b) { return a.updated_at < b.updated_at ? 1 : -1 })
    .slice(0, 26)
    .map(function (t) {
      const owner = t.assignees.length ? personById(t.assignees[0]) : null
      let action = 'updated'
      let tone = 'info'
      if (t.status === 'done') { action = 'completed'; tone = 'success' }
      else if (t.status === 'doing') { action = 'moved to In progress'; tone = 'primary' }
      else if (t.status === 'onhold') { action = 'put on hold'; tone = 'warning' }
      if (t.blocked) { action = 'flagged as blocked'; tone = 'error' }
      return {
        id: t.id + '-' + t.updated_at,
        actor: owner ? owner.name : 'Unassigned',
        actor_type: owner ? owner.type : 'user',
        action: action,
        target_task_id: t.id,
        target_task_name: t.name,
        board: (boardById(t.board_id) || {}).name || null,
        project_id: t.project_id,
        timestamp: t.updated_at,
        tone: tone
      }
    })
}

function boardProgress(tasks) {
  return BOARDS.map(function (board) {
    const rows = tasks.filter(function (t) { return t.board_id === board.id })
    if (!rows.length) return null
    const done = rows.filter(function (t) { return t.status === 'done' }).length
    return {
      board_id: board.id,
      board: board.name,
      project_id: board.project_id,
      project_name: (projectById(board.project_id) || {}).name,
      type: board.type,
      total: rows.length,
      done: done,
      doing: rows.filter(function (t) { return t.status === 'doing' }).length,
      todo: rows.filter(function (t) { return t.status === 'todo' }).length,
      on_hold: rows.filter(function (t) { return t.status === 'onhold' }).length,
      overdue: rows.filter(function (t) { return attentionReason(t) === 'overdue' }).length,
      blocked: rows.filter(function (t) { return t.blocked }).length,
      unassigned: rows.filter(function (t) { return !t.assignees.length && t.status !== 'done' }).length,
      percentage: Math.round(done / rows.length * 100),
      target_date: board.target_date,
      demo_date: board.demo_date
    }
  }).filter(Boolean)
}

// PROPOSED endpoint: delivery forecast per board
function forecast(range) {
  const tasks = windowTasks(range, null)
  return boardProgress(tasks).map(function (b) {
    const doneInWindow = tasks.filter(function (t) {
      return t.board_id === b.board_id && t.status === 'done' && inRange(t.updated_at, range)
    }).length
    const weeks = 1 // the window is the velocity baseline
    const velocity = Math.round((doneInWindow || 0.6) / weeks * 10) / 10
    const remaining = b.total - b.done
    const etaDays = Math.max(0, Math.round(remaining / Math.max(velocity, 0.5) * 7))
    const eta = dayOffset(etaDays)
    const targetLeft = delay(b.target_date)
    let status = 'on_track'
    let confidence = 'high'
    if (b.blocked > 0) { status = 'at_risk'; confidence = 'low' }
    if (targetLeft != null && etaDays > targetLeft) { status = targetLeft < 0 ? 'late' : 'at_risk'; confidence = targetLeft < 0 ? 'low' : 'medium' }
    return {
      board_id: b.board_id,
      board: b.board,
      project_id: b.project_id,
      project_name: b.project_name,
      type: b.type,
      committed: b.total,
      done: b.done,
      remaining: remaining,
      velocity: velocity,
      eta_date: eta,
      eta_days: etaDays,
      target_date: b.target_date,
      demo_date: b.demo_date,
      percentage: b.percentage,
      blocked: b.blocked,
      confidence: confidence,
      status: status
    }
  })
}

// PROPOSED endpoint: burndown
function burndown(boardId) {
  const board = boardById(boardId) || BOARDS[2]
  const rows = MOCK.db.tasks.filter(function (t) { return t.board_id === board.id })
  const days = 14
  const points = []
  const completedByDay = []
  for (let i = 0; i < days; i += 1) {
    const date = dayOffset(-(days - 1 - i))
    const done = rows.filter(function (t) {
      return t.status === 'done' && String(t.updated_at).slice(0, 10) <= date
    }).length
    completedByDay.push(done)
    points.push(date)
  }
  const total = rows.length
  const lastDone = completedByDay[completedByDay.length - 1]
  const synthetic = []
  // The mock backend derives the curve from done-by-day; when the seed has few
  // dated completions it interpolates so the chart stays readable.
  for (let i = 0; i < days; i += 1) {
    const ratio = days === 1 ? 1 : i / (days - 1)
    const actual = Math.round(lastDone * Math.pow(ratio, 0.85))
    synthetic.push(Math.max(0, Math.min(total, total - actual)))
  }
  return {
    board_id: board.id,
    board: board.name,
    total: total,
    points: points.map(function (date, i) {
      return {
        date: date,
        ideal: Math.round(total - (total / (days - 1)) * i),
        actual: synthetic[i],
        remaining: synthetic[i]
      }
    })
  }
}

// PROPOSED endpoint: team load
function teamLoad(range) {
  const tasks = windowTasks(range, null)
  return PEOPLE.map(function (person) {
    const mine = tasks.filter(function (t) { return t.assignees.indexOf(person.id) >= 0 })
    const active = mine.filter(function (t) { return t.status === 'doing' || t.status === 'todo' })
    const hours = active.reduce(function (sum, t) { return sum + t.estimate_h }, 0)
    const usage = USAGE.filter(function (u) { return u.username === person.id && inRange(u.iso_date, range) })
    const cost = usage.reduce(function (sum, u) { return sum + u.total_cxjcoins }, 0)
    const load = person.capacity ? Math.round(hours / person.capacity * 100) : Math.min(100, active.length * 12)
    return {
      id: person.id,
      name: person.name,
      role: person.role,
      type: person.type,
      capacity_h: person.capacity,
      hours: hours,
      load_pct: load,
      active: active.length,
      blocked: mine.filter(function (t) { return t.blocked }).length,
      done: mine.filter(function (t) { return t.status === 'done' }).length,
      overdue: mine.filter(function (t) { return attentionReason(t) === 'overdue' }).length,
      cost: Math.round(cost * 10) / 10,
      project_ids: person.projects,
      last_active: mine.length ? mine.slice().sort(function (a, b) { return a.updated_at < b.updated_at ? 1 : -1 })[0].updated_at : null
    }
  })
}

// ── analytics aggregations ────────────────────────────────────────────────
function usageRows(q) {
  const range = rangeFromQuery(q)
  const projectId = q.project_id || null
  return USAGE.filter(function (u) {
    if (!inRange(u.iso_date, range)) return false
    if (projectId && u.project_id !== projectId) return false
    if (q.model && u.model !== q.model) return false
    return true
  })
}

function metricsOf(rows) {
  const acc = { input_tokens: 0, output_tokens: 0, total_tokens: 0, calls: 0, total_duration_seconds: 0, total_cxjcoins: 0, tokens_from_provider: true }
  rows.forEach(function (r) {
    acc.input_tokens += r.input_tokens
    acc.output_tokens += r.output_tokens
    acc.total_tokens += r.total_tokens
    acc.calls += r.calls
    acc.total_duration_seconds += r.total_duration_seconds
    acc.total_cxjcoins += r.total_cxjcoins
  })
  acc.total_duration_seconds = Math.round(acc.total_duration_seconds * 10) / 10
  acc.total_cxjcoins = Math.round(acc.total_cxjcoins * 100) / 100
  return acc
}

function analyticsTotal(q) {
  const range = rangeFromQuery(q)
  const total = metricsOf(usageRows(q))
  const delivered = windowTasks(range, q.project_id ? [q.project_id] : null)
    .filter(function (t) { return t.status === 'done' && inRange(t.updated_at, range) }).length
  total.delivered_tasks = delivered
  total.cost_per_delivered_task = delivered ? Math.round(total.total_cxjcoins / delivered * 100) / 100 : null
  return total
}

function analyticsDaily(q) {
  const buckets = {}
  usageRows(q).forEach(function (u) {
    const key = u.iso_date
    if (!buckets[key]) buckets[key] = { period: key, input_tokens: 0, output_tokens: 0, total_tokens: 0, calls: 0, total_duration_seconds: 0, total_cxjcoins: 0, tokens_from_provider: true }
    const b = buckets[key]
    b.input_tokens += u.input_tokens
    b.output_tokens += u.output_tokens
    b.total_tokens += u.total_tokens
    b.calls += u.calls
    b.total_duration_seconds += u.total_duration_seconds
    b.total_cxjcoins += u.total_cxjcoins
  })
  return Object.keys(buckets).sort().map(function (key) {
    const b = buckets[key]
    b.total_cxjcoins = Math.round(b.total_cxjcoins * 100) / 100
    return b
  })
}

function analyticsBy(q, key) {
  const groups = {}
  usageRows(q).forEach(function (u) {
    const k = key === 'project' ? (projectById(u.project_id) || {}).name : key === 'user' ? u.username : u.model
    if (!groups[k]) groups[k] = []
    groups[k].push(u)
  })
  const out = {}
  Object.keys(groups).forEach(function (k) { out[k] = metricsOf(groups[k]) })
  return out
}

// PROPOSED endpoint: budget
function budgetPayload(q) {
  const range = rangeFromQuery(q)
  const spent = metricsOf(usageRows(q)).total_cxjcoins
  const days = Math.max(1, Math.round((new Date(range.to) - new Date(range.from)) / DAY) + 1)
  const perDay = spent / days
  const projected = Math.round(perDay * 7)
  const perProject = PROJECTS.map(function (p) {
    const s = metricsOf(usageRows(Object.assign({}, q, { project_id: p.id }))).total_cxjcoins
    return {
      project_id: p.id,
      project_name: p.name,
      color: p.color,
      budget: BUDGET.per_project[p.id],
      spent: Math.round(s * 100) / 100,
      pct: Math.round(s / BUDGET.per_project[p.id] * 100)
    }
  })
  return {
    weekly_budget: BUDGET.weekly,
    spent: Math.round(spent * 100) / 100,
    remaining: Math.round((BUDGET.weekly - projected) * 100) / 100,
    projected: projected,
    pct: Math.round(projected / BUDGET.weekly * 100),
    per_project: perProject
  }
}

// ── assistant ─────────────────────────────────────────────────────────────
function assistantAnswer(question, range) {
  const q = String(question || '').toLowerCase()
  const tasks = windowTasks(range, null).map(toPlanningTask)
  const attention = tasks.filter(function (t) { return t.attention_reason }).sort(function (a, b) {
    return (SEVERITY[b.attention_reason] || 0) - (SEVERITY[a.attention_reason] || 0)
  })
  const total = metricsOf(usageRows({ start_date: range.from, end_date: range.to }))

  function label(t) {
    return '**' + t.name + '** — ' + t.project_name + ' · ' + (t.assignee_names[0] || 'unassigned')
  }

  if (/block|stuck|stopp|stall|risk/.test(q)) {
    const blocked = attention.filter(function (t) { return t.attention_reason === 'blocked' })
    if (!blocked.length) return { answer: 'Nothing is blocked right now in this window. ' + attention.length + ' tasks still need attention (overdue, due today or unassigned).', sources: [{ route: 'blockers', label: 'Blockers' }] }
    const lines = blocked.slice(0, 5).map(function (t) {
      return '- ' + label(t) + ' · blocked ' + Math.abs(Math.round((Date.now() - new Date(t.blocked_since).getTime()) / DAY)) + 'd: ' + t.block_reason
    })
    return {
      answer: blocked.length + ' tasks are blocked:\n' + lines.join('\n') + '\n\nThe oldest blocker is ' + Math.abs(Math.round((Date.now() - new Date(blocked[0].blocked_since).getTime()) / DAY)) + ' days old — it is the one to escalate today.',
      sources: [{ route: 'blockers', label: 'Blockers' }, { route: 'work', label: 'Work' }]
    }
  }

  if (/cost|spend|budget|token|ai|model|consum/.test(q)) {
    const budget = budgetPayload({ start_date: range.from, end_date: range.to })
    const byProject = analyticsBy({ start_date: range.from, end_date: range.to }, 'project')
    const top = Object.keys(byProject).sort(function (a, b) { return byProject[b].total_cxjcoins - byProject[a].total_cxjcoins })
    return {
      answer: 'In this window the platform burned **' + fmtCoins(total.total_cxjcoins) + '** over ' + fmtNum(total.calls) + ' calls (' + fmtTokens(total.total_tokens) + ' tokens).\n- Biggest project: **' + top[0] + '** with ' + fmtCoins(byProject[top[0]].total_cxjcoins) + '\n- Projected week: **' + fmtCoins(budget.projected) + '** against a ' + fmtCoins(budget.weekly_budget) + ' budget (' + budget.pct + '%)\n- Cost per delivered task: ' + (analyticsTotal({ start_date: range.from, end_date: range.to }).cost_per_delivered_task != null ? fmtCoins(analyticsTotal({ start_date: range.from, end_date: range.to }).cost_per_delivered_task) : 'n/a'),
      sources: [{ route: 'cost', label: 'Cost & AI' }]
    }
  }

  if (/who|team|load|capacity|overload|busy/.test(q)) {
    const load = teamLoad(range).filter(function (p) { return p.type === 'human' }).sort(function (a, b) { return b.load_pct - a.load_pct })
    const hot = load.filter(function (p) { return p.load_pct >= 85 })
    const lines = load.slice(0, 4).map(function (p) { return '- **' + p.name + '** (' + p.role + ') — ' + p.load_pct + '% load · ' + p.active + ' active · ' + p.blocked + ' blocked' })
    return {
      answer: (hot.length ? hot.length + ' people are above 85% load.' : 'Nobody is above 85% load.') + '\n' + lines.join('\n'),
      sources: [{ route: 'team', label: 'Team' }]
    }
  }

  if (/ship|deliver|forecast|when|eta|demo|next week/.test(q)) {
    const fc = forecast(range)
    const risk = fc.filter(function (b) { return b.status !== 'on_track' })
    const demos = fc.filter(function (b) { return b.demo_date })
    const lines = demos.sort(function (a, b) { return a.demo_date < b.demo_date ? -1 : 1 }).map(function (b) {
      return '- **' + b.board + '** · demo ' + fmtDate(b.demo_date) + ' · ' + b.done + '/' + b.committed + ' done · ' + b.status.replace('_', ' ')
    })
    return {
      answer: 'Next demos:\n' + (lines.join('\n') || '- none scheduled') + '\n' + (risk.length ? risk.length + ' boards are at risk: ' + risk.map(function (b) { return b.board }).join(', ') + '.' : 'All boards are on track.'),
      sources: [{ route: 'delivery', label: 'Delivery' }]
    }
  }

  if (/overdue|late|behind/.test(q)) {
    const late = attention.filter(function (t) { return t.overdue })
    if (!late.length) return { answer: 'Nothing is overdue in this window.', sources: [{ route: 'blockers', label: 'Blockers' }] }
    return {
      answer: late.length + ' overdue tasks:\n' + late.slice(0, 6).map(function (t) {
        return '- ' + label(t) + ' · ' + Math.abs(t.days_until_due) + 'd late'
      }).join('\n'),
      sources: [{ route: 'blockers', label: 'Blockers' }]
    }
  }

  if (/done|finish|completed|delivered|this week/.test(q)) {
    const done = tasks.filter(function (t) { return t.status === 'done' })
    return {
      answer: done.length + ' tasks were completed in this window:\n' + done.slice(0, 6).map(function (t) {
        return '- ' + label(t)
      }).join('\n'),
      sources: [{ route: 'work', label: 'Work' }]
    }
  }

  const m = computeMetrics(windowTasks(range, null))
  return {
    answer: 'Here is the state of play for this window:\n- **' + m.active + '** active tasks, **' + m.blocked + '** blocked, **' + m.overdue + '** overdue\n- **' + m.done + '** completed (' + m.completion + '% of everything in scope)\n- AI spend ' + fmtCoins(total.total_cxjcoins) + '\n\nAsk me about blockers, costs, team load, what ships next, or what we finished.',
    sources: [{ route: 'pulse', label: 'Pulse' }]
  }
}

