      const metrics = computeMetrics(tasks)
      const attention = tasks.map(toPlanningTask)
        .filter(function (t) { return t.attention_reason })
        .sort(function (a, b) { return (SEVERITY[b.attention_reason] || 0) - (SEVERITY[a.attention_reason] || 0) })
        .map(function (t) { return { task: t, reason: t.attention_reason, severity: SEVERITY[t.attention_reason] || 0 } })
      return {
        metrics: DEV.empty ? computeMetrics([]) : metrics,
        board_progress: DEV.empty ? [] : boardProgress(tasks),
        attention: DEV.empty ? [] : attention,
        activity: DEV.empty ? [] : activityFeed(tasks, range),
        priority_counts: metrics.by_priority,
        generated_at: new Date().toISOString()
      }
    }
  },
  {
    method: 'POST', path: /^\/api\/planning\/tasks\/query$/,
    handler: function (ctx) {
      const body = ctx.body || {}
      const range = body.range ? { from: body.range.from, to: body.range.to } : rangeFromQuery({})
      let rows = DEV.empty ? [] : windowTasks(range, body.project_ids || null)

      if (body.boards && body.boards.length) rows = rows.filter(function (t) { return body.boards.indexOf(t.board_id) >= 0 })
      if (body.statuses && body.statuses.length) rows = rows.filter(function (t) { return body.statuses.indexOf(t.status) >= 0 })
      if (body.priorities && body.priorities.length) rows = rows.filter(function (t) { return body.priorities.indexOf(t.priority) >= 0 })
      if (body.assignees && body.assignees.length) rows = rows.filter(function (t) { return t.assignees.some(function (a) { return body.assignees.indexOf(a) >= 0 }) })
      if (body.only_blocked) rows = rows.filter(function (t) { return t.blocked })
      if (body.search) {
        const q = String(body.search).toLowerCase()
        rows = rows.filter(function (t) { return (t.name + ' ' + t.tags.join(' ')).toLowerCase().indexOf(q) >= 0 })
      }

      const groupCounts = ['todo', 'doing', 'onhold', 'done'].map(function (s) {
        return { key: s, label: s, total: rows.filter(function (t) { return t.status === s }).length }
      })

      const sort = body.sort || { field: 'priority', dir: 'asc' }
      const weight = { high: 0, medium: 1, low: 2 }
      rows = rows.slice().sort(function (a, b) {
        let cmp = 0
        if (sort.field === 'priority') cmp = (weight[a.priority] || 2) - (weight[b.priority] || 2)
        else if (sort.field === 'due_date') cmp = String(a.due_date || '9999').localeCompare(String(b.due_date || '9999'))
        else if (sort.field === 'status') cmp = String(a.status).localeCompare(String(b.status))
        else if (sort.field === 'name') cmp = a.name.localeCompare(b.name)
        else cmp = String(a.updated_at).localeCompare(String(b.updated_at))
        return sort.dir === 'desc' ? -cmp : cmp
      })

      const pageSize = body.page_size || 12
      const page = body.page || 1
      const total = rows.length
      const totalPages = Math.max(1, Math.ceil(total / pageSize))
      const pageRows = rows.slice((page - 1) * pageSize, page * pageSize).map(toPlanningTask)

      return {
        tasks: pageRows,
        total: total,
        page: page,
        page_size: pageSize,
        total_pages: totalPages,
        has_next: page < totalPages,
        has_prev: page > 1,
        group_counts: groupCounts,
        applied_filters: body,
        generated_at: new Date().toISOString()
      }
    }
  },
  {
    method: 'PATCH', path: /^\/api\/planning\/tasks\/([^/]+)$/,
    handler: function (ctx) {
      const id = ctx.params[0]
      const task = MOCK.db.tasks.find(function (t) { return t.id === id })
      if (!task) return { notFound: true }
      const body = ctx.body || {}
      if ('status' in body) task.status = body.status
      if ('priority' in body) task.priority = body.priority
      if ('due_date' in body) task.due_date = body.due_date
      if ('progress' in body) task.progress = Math.max(0, Math.min(100, Number(body.progress) || 0))
      if ('assignees' in body) task.assignees = body.assignees || []
      if ('blocked' in body) {
        task.blocked = !!body.blocked
        task.block_reason = body.blocked ? (body.block_reason || task.block_reason || 'Blocked') : null
        task.blocked_since = body.blocked ? new Date().toISOString() : null
      }
      task.updated_at = new Date().toISOString()
