// MOCK: dev toggles that make the non-happy paths reachable
const DEV = { empty: false, error: false }

function jsonResponse(data, status) {
  return { ok: status < 400, status: status || 200, data: data }
}

function mockFetch(input, init) {
  const options = init || {}
  const method = (options.method || 'GET').toUpperCase()
  const url = new URL(input, location.origin)
  const match = routes.find(function (r) { return r.method === method && r.path.test(url.pathname) })
  const wait = MOCK.latency[0] + Math.random() * (MOCK.latency[1] - MOCK.latency[0])

  return new Promise(function (resolve) {
    setTimeout(function () {
      // MOCK: forced failure for the error-state walkthrough
      if (DEV.error) {
        resolve(jsonResponse({ detail: 'Simulated 500 — the dev menu error toggle is on.' }, 500))
        return
      }
      if (!match) {
        resolve(jsonResponse({ detail: 'not_found: ' + method + ' ' + url.pathname }, 404))
        return
      }
      const params = url.pathname.match(match.path)
      const query = {}
      url.searchParams.forEach(function (value, key) { query[key] = value })
      let body = null
      if (options.body) { try { body = JSON.parse(options.body) } catch (e) { body = null } }
      try {
        const result = match.handler({ params: params ? params.slice(1) : [], query: query, body: body })
        if (result && result.notFound) {
          resolve(jsonResponse({ detail: 'not_found' }, 404))
          return
        }
        resolve(jsonResponse(result, method === 'POST' || method === 'PATCH' ? 200 : 200))
      } catch (error) {
        resolve(jsonResponse({ detail: String(error && error.message || error) }, 500))
      }
    }, wait)
  })
}

