const cache = new Map()

function saveState() {
  const payload = { route: state.route, range: state.range, filters: state.filters, assistant: state.assistant.messages.slice(-12) }
  try { localStorage.setItem(STORE_KEY, JSON.stringify(payload)) } catch (e) { /* storage may be blocked */ }
}

function loadState() {
  try {
    const raw = localStorage.getItem(STORE_KEY)
    if (!raw) return
    const saved = JSON.parse(raw)
    if (saved.route && ROUTES.some(function (r) { return r.id === saved.route })) state.route = saved.route
    if (saved.range && RANGES.some(function (r) { return r.id === saved.range })) state.range = saved.range
    if (saved.filters) {
      Object.keys(state.filters).forEach(function (scope) {
        if (saved.filters[scope]) state.filters[scope] = Object.assign(state.filters[scope], saved.filters[scope])
      })
    }
    if (Array.isArray(saved.assistant)) state.assistant.messages = saved.assistant
  } catch (e) { /* corrupted store: start fresh */ }
}

// MOCK: task edits survive reloads (applied over the seed on boot)
function persistPatch(task) {
  try {
    const key = STORE_KEY + '.patches'
    const patches = JSON.parse(localStorage.getItem(key) || '{}')
    patches[task.id] = {
      status: task.status, priority: task.priority, due_date: task.due_date,
      progress: task.progress, assignees: task.assignees, blocked: task.blocked,
      block_reason: task.block_reason, updated_at: task.updated_at
    }
    localStorage.setItem(key, JSON.stringify(patches))
  } catch (e) { /* ignore */ }
}

function applyPersistedPatches() {
  try {
    const patches = JSON.parse(localStorage.getItem(STORE_KEY + '.patches') || '{}')
    Object.keys(patches).forEach(function (id) {
      const task = MOCK.db.tasks.find(function (t) { return t.id === id })
      if (task) Object.assign(task, patches[id])
    })
  } catch (e) { /* ignore */ }
}

function bounds() {
  const to = todayISO()
  const back = function (days) {
    const dt = new Date(clock())
    dt.setDate(dt.getDate() - days)
    return isoDate(dt)
  }
  if (state.range === 'today') return { from: to, to: to }
  if (state.range === 'month') return { from: back(30), to: to }
  if (state.range === 'quarter') return { from: back(90), to: to }
  return { from: back(7), to: to }
}

function planningQS(extra) {
  const b = bounds()
  const params = new URLSearchParams()
  params.set('from', b.from)
  params.set('to', b.to)
  if (extra && extra.project_id) params.set('project_id', extra.project_id)
  return params.toString()
}

function analyticsQS(extra) {
  const b = bounds()
  const params = new URLSearchParams()
  params.set('start_date', b.from)
  params.set('end_date', b.to)
  if (extra && extra.project_name) params.set('project_name', extra.project_name)
  if (extra && extra.model) params.set('model', extra.model)
  return params.toString()
}

function projectName(projectId) {
  const p = projectById(projectId)
  return p ? p.name : null
}

// ── API wrapper: caching + error mapping ──────────────────────────────────
async function api(path, options) {
  const opts = options || {}
  const method = opts.method || 'GET'
  const key = method === 'GET' ? path : null
  if (key && cache.has(key)) return cache.get(key)
  const res = await mockFetch(path, { method: method, body: opts.body ? JSON.stringify(opts.body) : undefined })
  if (!res.ok) {
    const error = new Error((res.data && res.data.detail) || 'Request failed')
    error.status = res.status
    throw error
  }
  if (key) cache.set(key, res.data)
  return res.data
}

/* ═══════════════════════════════════════════════════════════════════════════
   D. FORMATTERS + tiny SVG charts (no CDN, so the mockup works offline)
   ═══════════════════════════════════════════════════════════════════════════ */

function esc(value) {
  return String(value == null ? '' : value).replace(/[&<>"']/g, function (c) {
    return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]
  })
}

function fmtNum(n) {
  if (n == null) return '—'
  if (Math.abs(n) >= 1000000) return (n / 1000000).toFixed(1) + 'M'
  if (Math.abs(n) >= 1000) return (n / 1000).toFixed(1) + 'K'
  return String(Math.round(n * 10) / 10)
}
function fmtTokens(n) { return n == null ? '—' : fmtNum(n) }
function fmtCoins(n) {
  if (n == null) return '—'
  if (Math.abs(n) >= 1000000) return '🪙 ' + (n / 1000000).toFixed(2) + 'M'
  if (Math.abs(n) >= 1000) return '🪙 ' + (n / 1000).toFixed(1) + 'K'
  return '🪙 ' + (Math.round(n * 10) / 10)
}
function fmtDate(iso) {
  if (!iso) return '—'
  const dt = new Date(String(iso).slice(0, 10) + 'T12:00:00')
  return dt.toLocaleDateString(undefined, { month: 'short', day: 'numeric' })
}
function fmtDateTime(iso) {
  if (!iso) return '—'
  const dt = new Date(iso)
  return dt.toLocaleDateString(undefined, { month: 'short', day: 'numeric' }) + ' ' + dt.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' })
}
function relTime(iso) {
  if (!iso) return '—'
  const diff = Date.now() - new Date(iso).getTime()
  const mins = Math.round(diff / 60000)
  if (mins < 2) return 'just now'
  if (mins < 60) return mins + 'm ago'
  const hours = Math.round(mins / 60)
  if (hours < 24) return hours + 'h ago'
  const days = Math.round(hours / 24)
  if (days < 30) return days + 'd ago'
  return Math.round(days / 30) + 'mo ago'
}
function dueLabel(task) {
  if (!task.due_date) return { text: 'no due date', cls: 'muted' }
  const d = task.days_until_due
  if (d == null) return { text: fmtDate(task.due_date), cls: 'muted' }
  if (d < 0) return { text: Math.abs(d) + 'd late', cls: 'error' }
  if (d === 0) return { text: 'due today', cls: 'warning' }
  if (d === 1) return { text: 'due tomorrow', cls: 'warning' }
  return { text: fmtDate(task.due_date), cls: 'muted' }
}
function initials(name) {
  return String(name || '?').split(/[\s-]+/).map(function (w) { return w.charAt(0) }).slice(0, 2).join('').toUpperCase()
}
function personColor(id) {
  const palette = ['#e2419f', '#38bdf8', '#22c55e', '#f59e0b', '#a855f7', '#14b8a6', '#f05252', '#6366f1']
  let sum = 0
  String(id).split('').forEach(function (c) { sum += c.charCodeAt(0) })
  return palette[sum % palette.length]
}

function pill(text, cls) { return '<span class="pill ' + (cls || '') + '">' + esc(text) + '</span>' }
function statusPill(status) {
  const meta = STATUS_META[status] || STATUS_META.todo
  return pill(meta.label, meta.cls)
}
function priorityPill(priority) {
  const meta = PRIORITY_META[priority] || PRIORITY_META.low
  return '<span class="pill ' + meta.cls + '"><span class="dotp" style="background:' + meta.color + '"></span>' + meta.label + '</span>'
}
function projectChip(projectId) {
  const p = projectById(projectId)
  if (!p) return ''
  return '<span class="proj-chip"><i style="background:' + p.color + '"></i>' + esc(p.name) + '</span>'
}
function avatarHtml(personId, size) {
  const p = personById(personId)
  if (!p) return '<span class="avatar ' + (size || 'sm') + '" style="background:var(--surface-3)">?</span>'
  const bg = p.type === 'agent' ? '' : 'background:' + personColor(p.id)
  return '<span class="avatar ' + (size || 'sm') + (p.type === 'agent' ? ' agent' : '') + '" style="' + bg + '" title="' + esc(p.name) + '">' + esc(initials(p.name)) + '</span>'
}
function assigneeStack(task) {
  if (!task.assignees || !task.assignees.length) return '<span class="pill muted">unassigned</span>'
  return '<span style="display:inline-flex;gap:-4px;align-items:center">' + task.assignees.slice(0, 3).map(function (id) { return avatarHtml(id, 'sm') }).join('') + '</span>'
}
function bar(pct, cls, marker) {
  const width = Math.max(0, Math.min(100, pct || 0))
  const color = cls || 'var(--primary)'
  return '<div class="bar"><span style="width:' + width + '%;background:' + color + '"></span>' +
    (marker != null ? '<i class="mark" style="left:' + Math.max(0, Math.min(100, marker)) + '%"></i>' : '') + '</div>'
}

// ── charts ────────────────────────────────────────────────────────────────
function chartLines(opts) {
  const labels = opts.labels || []
  const series = opts.series || []
  const height = opts.height || 180
  const fmt = opts.fmt || fmtNum
  const W = 720, H = height, padL = 46, padR = 10, padT = 12, padB = 24
  const iw = W - padL - padR
  const ih = H - padT - padB
  const max = Math.max(1, Math.max.apply(null, series.reduce(function (acc, s) { return acc.concat(s.values) }, [1])))
  const x = function (i) { return padL + (labels.length <= 1 ? iw / 2 : (i / (labels.length - 1)) * iw) }
  const y = function (v) { return padT + ih - (v / max) * ih }
  const grid = [0, 0.25, 0.5, 0.75, 1].map(function (r) {
    const gy = padT + ih - r * ih
    return '<line class="grid-line" x1="' + padL + '" y1="' + gy + '" x2="' + (W - padR) + '" y2="' + gy + '"/>' +
      '<text class="axis-text" x="' + (padL - 6) + '" y="' + (gy + 3) + '" text-anchor="end">' + esc(fmt(max * r)) + '</text>'
  }).join('')
  const step = Math.max(1, Math.ceil(labels.length / 6))
  const xLabels = labels.map(function (label, i) {
    if (i % step !== 0 && i !== labels.length - 1) return ''
    return '<text class="axis-text" x="' + x(i) + '" y="' + (H - 6) + '" text-anchor="middle">' + esc(label) + '</text>'
  }).join('')
  const paths = series.map(function (s) {
    const d = s.values.map(function (v, i) { return (i ? 'L' : 'M') + x(i).toFixed(1) + ' ' + y(v).toFixed(1) }).join(' ')
    const area = d + ' L' + x(s.values.length - 1).toFixed(1) + ' ' + (padT + ih) + ' L' + x(0).toFixed(1) + ' ' + (padT + ih) + ' Z'
    return '<path d="' + area + '" fill="' + s.color + '" opacity=".10"/>' +
      '<path d="' + d + '" fill="none" stroke="' + s.color + '" stroke-width="2.2" stroke-linejoin="round" stroke-linecap="round"/>'
  }).join('')
  return '<svg class="chart" viewBox="0 0 ' + W + ' ' + H + '" role="img" aria-label="' + esc(opts.aria || 'chart') + '">' + grid + paths + xLabels + '</svg>'
}

function chartBars(opts) {
  const labels = opts.labels || []
  const values = opts.values || []
  const height = opts.height || 160
  const fmt = opts.fmt || fmtNum
  const color = opts.color || 'var(--primary)'
  const W = 720, H = height, padL = 46, padR = 10, padT = 12, padB = 24
  const iw = W - padL - padR
  const ih = H - padT - padB
  const max = Math.max(1, Math.max.apply(null, values.concat([1])))
  const slot = iw / Math.max(1, labels.length)
  const bw = Math.max(2, Math.min(28, slot * 0.6))
  const grid = [0, 0.5, 1].map(function (r) {
    const gy = padT + ih - r * ih
    return '<line class="grid-line" x1="' + padL + '" y1="' + gy + '" x2="' + (W - padR) + '" y2="' + gy + '"/>' +
      '<text class="axis-text" x="' + (padL - 6) + '" y="' + (gy + 3) + '" text-anchor="end">' + esc(fmt(max * r)) + '</text>'
  }).join('')
  const bars = values.map(function (v, i) {
    const h = (v / max) * ih
    const bx = padL + slot * i + (slot - bw) / 2
    return '<rect x="' + bx.toFixed(1) + '" y="' + (padT + ih - h).toFixed(1) + '" width="' + bw.toFixed(1) + '" height="' + Math.max(1, h).toFixed(1) + '" rx="3" fill="' + color + '" opacity=".85"/>'
  }).join('')
  const step = Math.max(1, Math.ceil(labels.length / 6))
  const xLabels = labels.map(function (label, i) {
    if (i % step !== 0 && i !== labels.length - 1) return ''
    return '<text class="axis-text" x="' + (padL + slot * i + slot / 2) + '" y="' + (H - 6) + '" text-anchor="middle">' + esc(label) + '</text>'
  }).join('')
  return '<svg class="chart" viewBox="0 0 ' + W + ' ' + H + '" role="img" aria-label="' + esc(opts.aria || 'chart') + '">' + grid + bars + xLabels + '</svg>'
}

function chartBurndown(points) {
  const W = 720, H = 170, padL = 40, padR = 10, padT = 12, padB = 22
  const iw = W - padL - padR
  const ih = H - padT - padB
  const max = Math.max(1, Math.max.apply(null, points.map(function (p) { return Math.max(p.ideal, p.actual) }).concat([1])))
  const x = function (i) { return padL + (points.length <= 1 ? 0 : (i / (points.length - 1)) * iw) }
  const y = function (v) { return padT + ih - (v / max) * ih }
  const line = function (key, color, dash) {
    const d = points.map(function (p, i) { return (i ? 'L' : 'M') + x(i).toFixed(1) + ' ' + y(p[key]).toFixed(1) }).join(' ')
    return '<path d="' + d + '" fill="none" stroke="' + color + '" stroke-width="2.2"' + (dash ? ' stroke-dasharray="5 5"' : '') + ' stroke-linejoin="round"/>'
  }
  const grid = [0, 0.5, 1].map(function (r) {
    const gy = padT + ih - r * ih
    return '<line class="grid-line" x1="' + padL + '" y1="' + gy + '" x2="' + (W - padR) + '" y2="' + gy + '"/>' +
      '<text class="axis-text" x="' + (padL - 6) + '" y="' + (gy + 3) + '" text-anchor="end">' + Math.round(max * r) + '</text>'
  }).join('')
  const xl = points.map(function (p, i) {
    if (i % 3 !== 0 && i !== points.length - 1) return ''
    return '<text class="axis-text" x="' + x(i) + '" y="' + (H - 5) + '" text-anchor="middle">' + esc(fmtDate(p.date)) + '</text>'
  }).join('')
  return '<svg class="chart" viewBox="0 0 ' + W + ' ' + H + '" role="img" aria-label="Burndown chart">' +
    grid + line('ideal', 'rgba(255,255,255,.35)', true) + line('actual', 'var(--primary)', false) + xl + '</svg>'
}

function sparkline(values, color) {
  const W = 120, H = 34
  if (!values.length) return ''
  const max = Math.max(1, Math.max.apply(null, values))
  const d = values.map(function (v, i) {
    const x = (i / Math.max(1, values.length - 1)) * W
    const y = H - (v / max) * (H - 4) - 2
    return (i ? 'L' : 'M') + x.toFixed(1) + ' ' + y.toFixed(1)
  }).join(' ')
  return '<svg class="chart" viewBox="0 0 ' + W + ' ' + H + '" aria-hidden="true" style="max-width:120px">' +
    '<path d="' + d + '" fill="none" stroke="' + (color || 'var(--primary)') + '" stroke-width="2" stroke-linecap="round"/></svg>'
}

