function routeMeta(id) {
  return ROUTES.find(function (r) { return r.id === id }) || ROUTES[0]
}

function renderRailNav() {
  const items = ROUTES.map(function (r) {
    const active = state.route === r.id ? ' active' : ''
    const count = r.id === 'blockers' && state.alerts ? '<span class="nav-count">' + state.alerts + '</span>' : ''
    return '<button class="nav-item' + active + '" data-action="go:' + r.id + '">' + icon(r.icon) +
      '<span>' + r.label + '</span>' + count + '</button>'
  }).join('')
  document.getElementById('rail-nav').innerHTML = '<div class="rail-section">Sections</div>' + items
  document.getElementById('rail-foot').innerHTML =
    '<div class="rail-user">' + avatarHtml('u1', '') +
    '<div style="min-width:0"><div style="font-size:12.5px;font-weight:650">Marina Costa</div>' +
    '<div style="font-size:10.5px;color:var(--muted)">Admin · management view</div></div></div>'
}

function renderBottomNav() {
  document.getElementById('bottom-nav').innerHTML = ROUTES.map(function (r) {
    return '<button class="bn-item' + (state.route === r.id ? ' active' : '') + '" data-action="go:' + r.id + '">' +
      icon(r.icon) + '<span>' + (r.label === 'Cost & AI' ? 'Cost' : r.label) + '</span>' +
      (r.id === 'blockers' && state.alerts ? '<i class="bn-dot"></i>' : '') + '</button>'
  }).join('')
}

function renderTopbar() {
  const meta = routeMeta(state.route)
  document.getElementById('page-title').textContent = meta.title
  document.getElementById('page-sub').textContent = meta.sub
  document.getElementById('range-chips').innerHTML = RANGES.map(function (r) {
    return '<button class="chip' + (state.range === r.id ? ' active' : '') + '" data-action="range:' + r.id + '"' +
      (state.range === r.id ? ' aria-pressed="true"' : ' aria-pressed="false"') + '>' + r.label + '</button>'
  }).join('')
  const alertsBtn = document.getElementById('btn-alerts')
  alertsBtn.innerHTML = icon('bell') + (state.alerts ? '<span class="dot">' + state.alerts + '</span>' : '')
  document.getElementById('btn-assistant').innerHTML = icon('sparkles')
  document.getElementById('btn-menu').innerHTML = icon('menu')
  document.getElementById('btn-nav').innerHTML = icon('menu')
  document.getElementById('fab-assistant').innerHTML = icon('sparkles')
  document.getElementById('btn-assistant-close').innerHTML = icon('close')
  document.getElementById('btn-assistant-send').innerHTML = icon('chevron')

  document.getElementById('menu-root').innerHTML = state.ui.menu ? (
