function skeleton() {
  return '<div class="stack">' +
    '<div class="sk" style="height:74px"></div>' +
    '<div class="grid" style="grid-template-columns:repeat(2,minmax(0,1fr))">' +
    Array.from({ length: 6 }).map(function () { return '<div class="sk" style="height:78px"></div>' }).join('') +
    '</div>' +
    '<div class="sk" style="height:220px"></div>' +
    '</div>'
}

function errorCard(message, retryAction) {
  return '<div class="err" role="alert">' + icon('alert') +
    '<div style="flex:1"><div style="font-weight:700;font-size:13.5px;margin-bottom:2px">Could not load this section</div>' +
    '<div style="font-size:12.5px;color:var(--dim)">' + esc(message) + '</div></div>' +
    '<button class="btn sm" data-action="' + (retryAction || 'retry') + '">' + icon('refresh', 'ic-sm') + 'Retry</button></div>'
}

function emptyCard(title, text, actionLabel, action) {
  return '<div class="empty">' + icon('folder') + '<h3>' + esc(title) + '</h3><p>' + esc(text) + '</p>' +
    (actionLabel ? '<button class="btn sm" data-action="' + action + '">' + esc(actionLabel) + '</button>' : '') + '</div>'
}

// ── PULSE ─────────────────────────────────────────────────────────────────
function viewPulse() {
  const d = state.data.pulse
  if (!d) return skeleton()
  const m = d.dashboard.metrics
  const attention = d.dashboard.attention
  const b = bounds()

  const nextDemo = d.forecast.filter(function (f) { return f.demo_date }).sort(function (x, y) { return x.demo_date < y.demo_date ? -1 : 1 })[0]
  const atRisk = d.forecast.filter(function (f) { return f.status !== 'on_track' }).length
  const hot = d.teamLoad.filter(function (p) { return p.type === 'human' && p.load_pct >= 85 })

  const hero = attention.length
    ? '<div class="alert-strip" role="region" aria-label="Urgent items">' +
        '<div class="alert-top">' + icon('alert') + '<h2>' + attention.length + ' thing' + (attention.length === 1 ? '' : 's') + ' need you now</h2>' +
        '<span class="badge-count">' + attention.filter(function (a) { return (a.severity || 0) >= 3 }).length + '</span>' +
        '<div style="flex:1"></div><button class="link-more" data-action="go:blockers">All blockers ' + icon('chevron', 'ic-sm') + '</button></div>' +
        attention.slice(0, 4).map(function (item) {
          const t = item.task
          const meta = REASON_META[item.reason] || REASON_META.stalled
          const due = dueLabel(t)
          return '<button class="alert-row" data-action="open-task:' + t.id + '">' +
            '<span class="sev s' + Math.round(item.severity || 1) + '"></span>' +
            '<span class="txt"><span class="t1">' + esc(t.name) + '</span>' +
            '<span class="t2">' + esc(t.project_name) + ' · ' + meta.label + (t.block_reason ? ' · ' + esc(t.block_reason) : '') + ' · ' + due.text + '</span></span>' +
            pill(meta.label, meta.cls) + icon('chevron', 'ic-sm') + '</button>'
        }).join('') +
      '</div>'
    : '<div class="alert-strip calm" role="region" aria-label="All clear">' +
        '<div class="alert-top">' + icon('check') + '<h2>Nothing urgent. The delivery is running as planned.</h2><span class="badge-count">0</span></div>' +
        '<div style="font-size:12.5px;color:var(--dim)">' + m.active + ' active tasks · ' + m.done + ' completed in this window · next demo ' + (nextDemo ? fmtDate(nextDemo.demo_date) : 'not scheduled') + '</div>' +
      '</div>'

  const kpis = '<div class="kpis">' +
    kpi('Active work', m.active, m.total + ' tasks in window', '', 'go:work', ''),
    kpi('Blocked', m.blocked, m.blocked ? 'oldest ' + oldestBlockedDays(d.dashboard.attention) + 'd' : 'nothing blocked', m.blocked ? 'bad' : 'good', 'go:blockers', ''),
    kpi('Overdue', m.overdue, m.due_today + ' due today', m.overdue ? 'bad' : 'good', 'go:blockers', ''),
    kpi('Completed', m.done, m.completion + '% of scope', 'good', 'go:work', ''),
    kpi('Ships this week', d.forecast.filter(function (f) { return f.demo_date && f.demo_date <= b.to }).length || 0, nextDemo ? 'next demo ' + fmtDate(nextDemo.demo_date) : 'no demo scheduled', atRisk ? 'warn' : 'good', 'go:delivery', ''),
    kpi('AI spend', fmtCoins(d.total.total_cxjcoins), d.budget.pct + '% of weekly budget', d.budget.pct > 100 ? 'bad' : d.budget.pct > 80 ? 'warn' : 'good', 'go:cost', '')
    .join('') + '</div>'

  const forecastList = d.forecast.slice(0, 5).map(function (f) {
    const cfg = { on_track: ['success', 'On track'], at_risk: ['warning', 'At risk'], late: ['error', 'Late'] }[f.status] || ['muted', f.status]
    return '<button class="row-btn row" data-action="open-board:' + f.board_id + '">' +
      '<span class="grow"><span class="t1">' + esc(f.board) + '</span>' +
      '<span class="t2">' + esc(f.project_name) + ' · ' + f.done + '/' + f.committed + ' done · ETA ' + fmtDate(f.eta_date) + '</span>' +
      bar(f.percentage, cfg[0] === 'error' ? 'var(--error)' : cfg[0] === 'warning' ? 'var(--warning)' : 'var(--success)') +
      '</span>' + pill(cfg[1], cfg[0]) + icon('chevron', 'ic-sm') + '</button>'
  }).join('')

  const teamList = d.teamLoad.filter(function (p) { return p.type === 'human' }).sort(function (x, y) { return y.load_pct - x.load_pct }).slice(0, 4).map(function (p) {
    const color = p.load_pct >= 95 ? 'var(--error)' : p.load_pct >= 85 ? 'var(--warning)' : 'var(--success)'
    return '<div class="row">' + avatarHtml(p.id) +
      '<span class="grow"><span class="t1">' + esc(p.name) + '</span><span class="t2">' + esc(p.role) + ' · ' + p.active + ' active' + (p.blocked ? ' · ' + p.blocked + ' blocked' : '') + '</span>' +
      bar(p.load_pct, color) + '</span>' +
      '<span class="mono" style="font-size:11.5px;color:' + color + '">' + p.load_pct + '%</span></div>'
  }).join('')

  const activityList = d.dashboard.activity.slice(0, 7).map(function (e) {
    const color = { success: 'var(--success)', primary: 'var(--primary)', warning: 'var(--warning)', error: 'var(--error)' }[e.tone] || 'var(--info)'
    return '<button class="row row-btn" data-action="open-task:' + e.target_task_id + '">' +
      '<span class="dotp" style="background:' + color + ';margin-top:6px"></span>' +
      '<span class="grow"><span class="t1" style="font-weight:600">' + esc(e.actor) + ' ' + esc(e.action) + '</span>' +
      '<span class="t2">' + esc(e.target_task_name) + ' · ' + esc(e.board || '') + '</span></span>' +
      '<span class="muted" style="font-size:10.5px;white-space:nowrap">' + relTime(e.timestamp) + '</span></button>'
  }).join('')

  const costSeries = d.daily.map(function (x) { return x.total_cxjcoins })
  const costBars = '<div class="vbar" aria-hidden="true">' + costSeries.slice(-14).map(function (v) {
    const max = Math.max.apply(null, costSeries.concat([1]))
    return '<i style="height:' + Math.max(4, Math.round(v / max * 100)) + '%"></i>'
  }).join('') + '</div>'

  return '<div class="stack">' +
    hero + kpis +
    '<div class="two-col">' +
      '<div class="stack">' +
        card('Delivering now', 'Progress against target, per board', forecastList || emptyCard('No boards', 'Nothing scheduled in this window.'), '<button class="link-more" data-action="go:delivery">Forecast ' + icon('chevron', 'ic-sm') + '</button>') +
        card('Needs attention', attention.length + ' item(s) across ' + new Set(attention.map(function (a) { return a.task.project_id })).size + ' projects',
          attention.slice(0, 6).map(attentionRow).join('') || emptyCard('All clear', 'No overdue, blocked or unowned work in this window.'),
          '<button class="link-more" data-action="go:blockers">See all ' + icon('chevron', 'ic-sm') + '</button>') +
      '</div>' +
      '<div class="stack">' +
        card('Team load', hot.length ? hot.length + ' above 85%' : 'Healthy', teamList || emptyCard('No members', 'No team members found.'), '<button class="link-more" data-action="go:team">Team ' + icon('chevron', 'ic-sm') + '</button>') +
        card('Activity', 'Most recent changes across projects', activityList || emptyCard('No activity', 'Nothing changed in this window.')) +
        card('AI spend trend', fmtCoins(d.total.total_cxjcoins) + ' in this window', costBars, '<button class="link-more" data-action="go:cost">Cost & AI ' + icon('chevron', 'ic-sm') + '</button>') +
      '</div>' +
    '</div>' +
  '</div>'
}

function kpi(label, value, sub, tone, action, extra) {
  return '<button class="kpi ' + (tone || '') + '" data-action="' + action + '">' +
    '<span class="k-label">' + esc(label) + '</span>' +
    '<span class="k-val">' + esc(value) + '</span>' +
    '<span class="k-sub">' + esc(sub) + (extra || '') + '</span></button>'
}

function oldestBlockedDays(attention) {
  const blocked = attention.filter(function (a) { return a.reason === 'blocked' })
  if (!blocked.length) return 0
  return Math.max.apply(null, blocked.map(function (a) {
    return Math.abs(Math.round((Date.now() - new Date(a.task.blocked_since || a.task.updated_at).getTime()) / DAY))
  }))
}

function attentionRow(item) {
  const t = item.task
  const meta = REASON_META[item.reason] || REASON_META.stalled
  const due = dueLabel(t)
  return '<button class="row row-btn" data-action="open-task:' + t.id + '">' +
    '<span class="grow"><span class="t1">' + esc(t.name) + '</span>' +
    '<span class="t2">' + projectChip(t.project_id) + ' · ' + esc(t.board || '') + ' · ' +
    (t.assignee_names.length ? esc(t.assignee_names[0]) : 'unassigned') + ' · ' + due.text + '</span></span>' +
    pill(meta.label, meta.cls) + '</button>'
}

function card(title, sub, body, action) {
  return '<section class="card">' +
    '<div class="card-head"><div><h2>' + esc(title) + '</h2>' + (sub ? '<p>' + esc(sub) + '</p>' : '') + '</div>' +
    '<div class="sp"></div>' + (action || '') + '</div>' + body + '</section>'
}

// ── WORK ──────────────────────────────────────────────────────────────────
function viewWork() {
  const d = state.data.work
  if (!d) return skeleton()
  const f = state.filters.work
  const projects = state.data.pulse ? state.data.pulse.projects : PROJECTS

  const projectOptions = [{ id: 'all', label: 'All projects' }].concat(projects.map(function (p) { return { id: p.id, label: p.name } }))
  const boardOptions = [{ id: 'all', label: 'All boards' }].concat(d.boards.map(function (b) { return { id: b.id, label: b.name } }))
  const statusOptions = [{ id: 'all', label: 'All statuses' }, { id: 'todo', label: 'To Do' }, { id: 'doing', label: 'In Progress' }, { id: 'onhold', label: 'On Hold' }, { id: 'done', label: 'Done' }]
  const priorityOptions = [{ id: 'all', label: 'All priorities' }, { id: 'high', label: 'High' }, { id: 'medium', label: 'Medium' }, { id: 'low', label: 'Low' }]
  const assigneeOptions = [{ id: 'all', label: 'Anyone' }].concat(PEOPLE.map(function (p) { return { id: p.id, label: p.name } }))

  function selectHtml(name, options, value) {
    return '<select class="field" data-filter="work.' + name + '" aria-label="' + name + '">' +
      options.map(function (o) {
        return '<option value="' + o.id + '"' + (String(o.id) === String(value) ? ' selected' : '') + '>' + esc(o.label) + '</option>'
      }).join('') + '</select>'
  }

  const toolbar = '<div class="toolbar">' +
    '<div class="search">' + icon('search') + '<input class="field" type="search" placeholder="Search tasks…" value="' + esc(f.q) + '" data-filter="work.q" data-fkey="work-search" aria-label="Search tasks" /></div>' +
    selectHtml('project', projectOptions, f.project) +
    selectHtml('board', boardOptions, f.board) +
    selectHtml('status', statusOptions, f.status) +
    selectHtml('priority', priorityOptions, f.priority) +
    selectHtml('assignee', assigneeOptions, f.assignee) +
    '<button class="btn sm ghost" data-action="clear-work-filters">' + icon('filter', 'ic-sm') + 'Clear</button>' +
    '</div>'

  const sortable = function (field, label) {
    const active = f.sort === field
    const arrow = active ? (f.dir === 'asc' ? '▲' : '▼') : ''
    return '<th class="' + (field === 'name' ? '' : '') + ' sortable" data-action="sort:' + field + '">' + label +
      (arrow ? ' <span style="color:var(--primary)">' + arrow + '</span>' : '') + '</th>'
  }

  const rows = d.tasks.map(function (t) {
    const due = dueLabel(t)
    return '<tr data-action="open-task:' + t.id + '" tabindex="0" role="button">' +
      '<td><div style="font-weight:600;font-size:12.5px">' + esc(t.name) + '</div>' +
      '<div style="font-size:11px;color:var(--muted)">' + (t.blocked ? '⛔ ' + esc(t.block_reason) : esc((t.tags || []).join(' · ') || '—')) + '</div></td>' +
      '<td>' + projectChip(t.project_id) + '</td>' +
      '<td class="dim" style="font-size:11.5px">' + esc(t.board || '—') + '</td>' +
      '<td>' + statusPill(t.status) + '</td>' +
      '<td>' + priorityPill(t.priority) + '</td>' +
      '<td>' + assigneeStack(t) + '</td>' +
      '<td class="' + (due.cls === 'error' ? '' : '') + '" style="font-size:11.5px;color:' + (due.cls === 'error' ? 'var(--error)' : due.cls === 'warning' ? 'var(--warning)' : 'var(--dim)') + '">' + esc(due.text) + '</td>' +
      '<td style="min-width:88px"><div style="display:flex;align-items:center;gap:6px">' + bar(t.progress, t.progress === 100 ? 'var(--success)' : 'var(--primary)') +
      '<span class="mono" style="font-size:10.5px;color:var(--muted)">' + t.progress + '%</span></div></td>' +
      '<td class="dim" style="font-size:11px;white-space:nowrap">' + relTime(t.updated_at) + '</td>' +
      '</tr>'
  }).join('')

  const cards = d.tasks.map(function (t) {
    const due = dueLabel(t)
    return '<button class="task-card" data-action="open-task:' + t.id + '">' +
      '<span class="tc-top"><span class="tc-title">' + esc(t.name) + '</span>' + priorityPill(t.priority) + '</span>' +
      '<span class="tc-meta">' + statusPill(t.status) + projectChip(t.project_id) +
      '<span style="font-size:11px;color:' + (due.cls === 'error' ? 'var(--error)' : 'var(--muted)') + '">' + icon('clock', 'ic-sm') + ' ' + esc(due.text) + '</span>' +
      assigneeStack(t) + '</span>' +
      (t.blocked ? '<span class="tc-meta">' + pill('⛔ ' + t.block_reason, 'error') + '</span>' : '') +
      '</button>'
  }).join('')

  const start = d.total ? (d.page - 1) * d.page_size + 1 : 0
  const end = Math.min(d.total, d.page * d.page_size)
  const pages = []
  for (let p = 1; p <= d.total_pages; p += 1) {
    if (d.total_pages > 7 && p > 2 && p < d.total_pages - 1 && Math.abs(p - d.page) > 1) {
      if (pages[pages.length - 1] !== '…') pages.push('…')
      continue
    }
    pages.push(p)
  }

  const pager = '<div class="pager"><div class="filters-note">' +
    (d.total ? 'Showing <strong style="color:var(--text)">' + start + '–' + end + '</strong> of ' + d.total : 'No results') +
    '</div><div class="pages">' +
    '<button class="page-btn" data-action="page:' + (d.page - 1) + '"' + (d.has_prev ? '' : ' disabled') + ' aria-label="Previous page">‹</button>' +
    pages.map(function (p) {
      if (p === '…') return '<span class="muted" style="padding:0 2px">…</span>'
      return '<button class="page-btn' + (p === d.page ? ' active' : '') + '" data-action="page:' + p + '">' + p + '</button>'
    }).join('') +
    '<button class="page-btn" data-action="page:' + (d.page + 1) + '"' + (d.has_next ? '' : ' disabled') + ' aria-label="Next page">›</button>' +
    '</div></div>'

  const body = d.total === 0
    ? emptyCard('No tasks match these filters', 'Widen the time range, pick another project, or clear the filters.', 'Clear filters', 'clear-work-filters')
    : '<div class="table-wrap"><table><thead><tr>' +
        sortable('name', 'Task') + '<th>Project</th><th>Board</th><th>Status</th><th>Priority</th><th>Owner</th>' +
        sortable('due_date', 'Due') + '<th>Progress</th>' + sortable('updated_at', 'Updated') +
        '</tr></thead><tbody>' + rows + '</tbody></table></div>' +
      '<div class="cards-list">' + cards + '</div>' + pager

  return '<div class="stack">' +
    '<section class="card">' +
      '<div class="card-head"><div><h2>All work in the window</h2><p>' +
      (d.total + ' tasks · ' + Object.keys(d.group_counts).length + ' statuses · across every project') +
      '</p></div><div class="sp"></div>' +
      '<button class="btn sm" data-action="go:blockers">' + icon('alert', 'ic-sm') + 'Blockers</button></div>' +
      toolbar + '</section>' +
    '<section class="card pad0" style="padding:6px 12px 12px">' + body + '</section>' +
  '</div>'
}

// ── BLOCKERS ──────────────────────────────────────────────────────────────
function viewBlockers() {
  const d = state.data.blockers
  if (!d) return skeleton()
  const f = state.filters.blockers
  let items = d.dashboard.attention
  if (f.reason !== 'all') items = items.filter(function (i) { return i.reason === f.reason })
  if (f.project !== 'all') items = items.filter(function (i) { return i.task.project_id === f.project })

  const counts = {}
  d.dashboard.attention.forEach(function (i) { counts[i.reason] = (counts[i.reason] || 0) + 1 })

  const chips = ['all'].concat(Object.keys(REASON_META)).map(function (key) {
    const label = key === 'all' ? 'All (' + d.dashboard.attention.length + ')' : (REASON_META[key].label + ' (' + (counts[key] || 0) + ')')
    return '<button class="chip' + (f.reason === key ? ' active' : '') + '" data-action="block-filter:' + key + '">' + esc(label) + '</button>'
  }).join('')

  const projectSelect = '<select class="field" data-filter="blockers.project" aria-label="Project">' +
    '<option value="all">All projects</option>' +
    PROJECTS.map(function (p) { return '<option value="' + p.id + '"' + (f.project === p.id ? ' selected' : '') + '>' + esc(p.name) + '</option>' }).join('') +
    '</select>'

  const list = items.map(function (item) {
    const t = item.task
    const meta = REASON_META[item.reason] || REASON_META.stalled
    const days = t.blocked_since
      ? Math.abs(Math.round((Date.now() - new Date(t.blocked_since).getTime()) / DAY))
      : Math.abs(t.days_until_due || 0)
    return '<article class="card" style="border-color:' + (item.reason === 'blocked' || item.reason === 'overdue' ? 'rgba(240,82,82,.28)' : 'var(--line)') + '">' +
      '<div style="display:flex;gap:10px;align-items:flex-start">' +
        '<span class="sev s' + Math.round(item.severity || 1) + '" style="margin-top:7px"></span>' +
        '<div style="flex:1;min-width:0">' +
          '<button data-action="open-task:' + t.id + '" style="text-align:left;font-size:14px;font-weight:650;line-height:1.35">' + esc(t.name) + '</button>' +
          '<div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:7px;align-items:center">' +
            pill(meta.label, meta.cls) + statusPill(t.status) + priorityPill(t.priority) + projectChip(t.project_id) +
            '<span style="font-size:11px;color:var(--muted)">' + esc(t.board || '') + '</span>' +
          '</div>' +
          (t.block_reason ? '<div style="margin-top:8px;font-size:12px;color:#ffb4b4;background:rgba(240,82,82,.08);border:1px solid rgba(240,82,82,.22);border-radius:8px;padding:7px 9px">⛔ ' + esc(t.block_reason) + '</div>' : '') +
          '<div style="display:flex;flex-wrap:wrap;gap:10px;margin-top:9px;font-size:11.5px;color:var(--muted)">' +
            '<span>' + (t.assignee_names.length ? esc(t.assignee_names.join(', ')) : '<strong style="color:var(--warning)">unassigned</strong>') + '</span>' +
            '<span>· ' + (item.reason === 'blocked' ? 'blocked ' + days + 'd' : item.reason === 'overdue' ? days + 'd overdue' : item.reason === 'stalled' ? 'no update ' + days + 'd' : 'due ' + fmtDate(t.due_date)) + '</span>' +
            '<span>· updated ' + relTime(t.updated_at) + '</span>' +
          '</div>' +
          '<div class="toolbar" style="margin-top:11px">' +
            '<button class="btn sm" data-action="open-task:' + t.id + '">Open</button>' +
            '<button class="btn sm ghost" data-action="ask-update:' + t.id + '">' + icon('sparkles', 'ic-sm') + 'Ask for update</button>' +
            '<button class="btn sm ghost" data-action="reassign:' + t.id + '">' + icon('user', 'ic-sm') + 'Reassign</button>' +
            (t.blocked ? '<button class="btn sm danger" data-action="unblock:' + t.id + '">Unblock</button>' : '') +
          '</div>' +
        '</div>' +
      '</div></article>'
  }).join('')

  return '<div class="stack">' +
    '<section class="card">' +
      '<div class="card-head"><div><h2>Attention queue</h2><p>Blocked, overdue, due today, stalled or unowned work — most severe first</p></div>' +
      '<div class="sp"></div>' + projectSelect + '</div>' +
      '<div class="toolbar" style="margin-bottom:4px">' + chips + '</div>' +
    '</section>' +
    (items.length ? '<div class="stack">' + list + '</div>'
      : card('Nothing here', 'No blockers match this filter', emptyCard('Clear', 'Try another reason or project.', 'Show all', 'block-filter:all'))) +
  '</div>'
}

// ── DELIVERY ──────────────────────────────────────────────────────────────
function viewDelivery() {
  const d = state.data.delivery
  if (!d) return skeleton()
  const selected = state.filters.delivery.board
  const burndown = d.burndown

  const cards = d.forecast.map(function (f) {
    const cfg = { on_track: ['success', 'On track'], at_risk: ['warning', 'At risk'], late: ['error', 'Late'] }[f.status]
    const conf = { high: 'success', medium: 'warning', low: 'error' }[f.confidence]
    return '<article class="card">' +
      '<div style="display:flex;gap:8px;align-items:flex-start">' +
        '<div style="flex:1;min-width:0">' +
          '<div style="font-size:13.5px;font-weight:700">' + esc(f.board) + '</div>' +
          '<div style="font-size:11.5px;color:var(--muted)">' + projectChip(f.project_id) + ' · ' + esc(f.type) + '</div>' +
        '</div>' + pill(cfg[1], cfg[0]) +
      '</div>' +
      '<div style="margin:12px 0 6px">' + bar(f.percentage, f.status === 'on_track' ? 'var(--success)' : f.status === 'at_risk' ? 'var(--warning)' : 'var(--error)') + '</div>' +
      '<div style="display:flex;justify-content:space-between;font-size:11.5px;color:var(--dim)">' +
        '<span>' + f.done + '/' + f.committed + ' done</span><span class="mono">' + f.percentage + '%</span></div>' +
      '<div class="grid" style="grid-template-columns:1fr 1fr;gap:8px;margin-top:12px">' +
        metaBox('ETA', fmtDate(f.eta_date)) +
        metaBox('Target', fmtDate(f.target_date)) +
        metaBox('Velocity', f.velocity + ' / wk') +
        metaBox('Confidence', f.confidence) +
      '</div>' +
      '<div style="margin-top:10px;font-size:11.5px;color:' + (f.blocked ? 'var(--error)' : 'var(--muted)') + '">' +
        (f.blocked ? '⛔ ' + f.blocked + ' blocked task(s) drag the forecast' : 'Remaining: ' + f.remaining + ' task(s), no blockers') + '</div>' +
      (f.demo_date ? '<div style="margin-top:8px">' + pill('Demo ' + fmtDate(f.demo_date), 'primary') + '</div>' : '') +
      '</article>'
  }).join('')

  const boardSelect = '<select class="field" data-filter="delivery.board" aria-label="Board">' +
    d.forecast.map(function (f) { return '<option value="' + f.board_id + '"' + (selected === f.board_id ? ' selected' : '') + '>' + esc(f.board) + '</option>' }).join('') +
    '</select>'

  const burndownBlock = burndown ? (
    '<div>' + chartBurndown(burndown.points) +
    '<div class="legend" style="margin-top:8px">' +
      '<span class="legend" style="align-items:center;gap:5px"><i style="background:rgba(255,255,255,.35)"></i><span style="font-size:11px;color:var(--dim)">Ideal</span></span>' +
      '<span class="legend" style="align-items:center;gap:5px"><i style="background:var(--primary)"></i><span style="font-size:11px;color:var(--dim)">Actual remaining</span></span>' +
    '</div></div>'
  ) : '<div class="sk" style="height:170px"></div>'

  const milestoneRows = d.forecast.filter(function (f) { return f.demo_date })
    .sort(function (a, b) { return a.demo_date < b.demo_date ? -1 : 1 })
    .map(function (f) {
      const cfg = { on_track: ['success', 'On track'], at_risk: ['warning', 'At risk'], late: ['error', 'Late'] }[f.status]
      return '<tr data-action="open-board:' + f.board_id + '" tabindex="0" role="button">' +
        '<td style="font-weight:600">' + esc(f.board) + '</td>' +
        '<td>' + projectChip(f.project_id) + '</td>' +
        '<td class="dim">' + fmtDate(f.demo_date) + '</td>' +
        '<td>' + f.done + '/' + f.committed + '</td>' +
        '<td style="min-width:90px">' + bar(f.percentage, 'var(--primary)') + '</td>' +
        '<td class="dim">' + fmtDate(f.eta_date) + '</td>' +
        '<td>' + pill(cfg[1], cfg[0]) + '</td></tr>'
    }).join('')

  return '<div class="stack">' +
    '<div class="kpis">' +
      kpi('Boards tracked', d.forecast.length, 'across ' + PROJECTS.length + ' projects', '', 'go:work', '') +
      kpi('At risk', d.forecast.filter(function (f) { return f.status !== 'on_track' }).length, 'behind target or blocked', 'warn', 'go:blockers', '') +
      kpi('Next demo', d.forecast.filter(function (f) { return f.demo_date }).map(function (f) { return f.demo_date }).sort()[0] ? fmtDate(d.forecast.filter(function (f) { return f.demo_date }).map(function (f) { return f.demo_date }).sort()[0]) : '—', 'management walkthrough', '', 'go:delivery', '') +
      '</div>' +
    '<section class="card"><div class="card-head"><div><h2>Forecast per board</h2>' +
      '<p>Velocity is measured inside the selected window — this is what the dates below are based on</p></div></div>' +
      '<div class="three-col">' + (cards || emptyCard('No boards', 'Nothing scheduled in this window.')) + '</div></section>' +
    '<div class="two-col">' +
      '<section class="card"><div class="card-head"><div><h2>Burndown</h2><p>' + esc(burndown ? burndown.board + ' · last 14 days · ' + burndown.total + ' tasks' : '') + '</p></div>' +
      '<div class="sp"></div>' + boardSelect + '</div>' + burndownBlock + '</section>' +
      card('Milestones & demos', 'What management will see, and when',
        '<div class="table-wrap"><table><thead><tr><th>Sprint</th><th>Project</th><th>Demo</th><th>Done</th><th>Progress</th><th>ETA</th><th>Status</th></tr></thead><tbody>' +
        (milestoneRows || '<tr><td colspan="7" style="text-align:center;color:var(--muted);padding:22px">No demos scheduled</td></tr>') +
        '</tbody></table></div>') +
    '</div>' +
  '</div>'
}

function metaBox(label, value) {
  return '<div><div style="font-size:10px;text-transform:uppercase;letter-spacing:.05em;color:var(--muted)">' + esc(label) + '</div>' +
    '<div style="font-size:12.5px;font-weight:650">' + esc(value) + '</div></div>'
}

// ── TEAM ──────────────────────────────────────────────────────────────────
function viewTeam() {
  const d = state.data.team
  if (!d) return skeleton()
  const f = state.filters.team
  let members = d.teamLoad
  if (f.type !== 'all') members = members.filter(function (p) { return p.type === f.type })
  if (f.project !== 'all') members = members.filter(function (p) { return p.project_ids.indexOf(f.project) >= 0 })
  if (f.hot) members = members.filter(function (p) { return p.load_pct >= 85 })
  members = members.slice().sort(function (a, b) { return b.load_pct - a.load_pct })

  const humans = d.teamLoad.filter(function (p) { return p.type === 'human' })
  const totalLoad = humans.length ? Math.round(humans.reduce(function (s, p) { return s + p.load_pct }, 0) / humans.length) : 0
  const overloaded = humans.filter(function (p) { return p.load_pct >= 85 }).length
  const agents = d.teamLoad.filter(function (p) { return p.type === 'agent' })

  const cards = members.map(function (p) {
    const color = p.load_pct >= 95 ? 'var(--error)' : p.load_pct >= 85 ? 'var(--warning)' : 'var(--success)'
    return '<button class="card" style="text-align:left" data-action="open-member:' + p.id + '">' +
      '<div style="display:flex;gap:10px;align-items:center">' + avatarHtml(p.id, '') +
        '<div style="flex:1;min-width:0"><div style="font-size:13.5px;font-weight:700">' + esc(p.name) + '</div>' +
        '<div style="font-size:11.5px;color:var(--muted)">' + esc(p.role) + (p.type === 'agent' ? ' · AI' : '') + '</div></div>' +
        '<span class="mono" style="font-size:12px;font-weight:700;color:' + color + '">' + p.load_pct + '%</span></div>' +
      '<div style="margin:11px 0 9px">' + bar(p.load_pct, color) + '</div>' +
      '<div class="grid" style="grid-template-columns:repeat(3,1fr);gap:6px;font-size:11px;text-align:center">' +
        statTile(p.active, 'active') + statTile(p.blocked, 'blocked', p.blocked ? 'var(--error)' : null) + statTile(p.done, 'done', 'var(--success)') +
      '</div>' +
      '<div style="margin-top:9px;font-size:11px;color:var(--muted)">' +
        (p.type === 'human' ? esc(p.hours + 'h / ' + p.capacity_h + 'h allocated') : 'agent · ' + p.active + ' tasks') +
        ' · ' + fmtCoins(p.cost) + '</div>' +
      '</button>'
  }).join('')

  const typeSelect = '<select class="field" data-filter="team.type" aria-label="Member type">' +
    ['all', 'human', 'agent'].map(function (t) {
      return '<option value="' + t + '"' + (f.type === t ? ' selected' : '') + '>' + (t === 'all' ? 'Everyone' : t === 'human' ? 'Humans' : 'AI agents') + '</option>'
    }).join('') + '</select>'
  const projectSelect = '<select class="field" data-filter="team.project" aria-label="Project">' +
    '<option value="all">All projects</option>' +
    PROJECTS.map(function (p) { return '<option value="' + p.id + '"' + (f.project === p.id ? ' selected' : '') + '>' + esc(p.name) + '</option>' }).join('') + '</select>'

  return '<div class="stack">' +
    '<section class="card"><div class="card-head"><div><h2>Capacity</h2>' +
      '<p>Average human load ' + totalLoad + '% · ' + overloaded + ' member(s) above 85% · ' + agents.length + ' AI agents in the roster</p></div>' +
      '<div class="sp"></div></div>' +
      '<div class="toolbar">' + typeSelect + projectSelect +
      '<button class="btn sm' + (f.hot ? ' primary' : ' ghost') + '" data-action="team-hot">' + icon('warn', 'ic-sm') + 'Overloaded only</button>' +
      '<button class="btn sm ghost" data-action="team-clear">Clear</button></div></section>' +
    (members.length
      ? '<div class="grid" style="grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:12px">' + cards + '</div>'
      : card('No members match', 'Widen the filters', emptyCard('Nothing to show', 'No team member matches these filters.', 'Clear filters', 'team-clear'))) +
  '</div>'
}

function statTile(value, label, color) {
  return '<div style="background:var(--surface-2);border-radius:8px;padding:6px 2px">' +
