  const modelSelect = '<select class="field" data-filter="cost.model" aria-label="Model">' +
    '<option value="all">All models</option>' +
    MODELS.map(function (m) { return '<option value="' + m.name + '"' + (f.model === m.name ? ' selected' : '') + '>' + esc(m.name) + '</option>' }).join('') + '</select>'

  const labels = d.daily.map(function (x) { return fmtDate(x.period) })
  const costValues = d.daily.map(function (x) { return x.total_cxjcoins })
  const tokenValues = d.daily.map(function (x) { return x.total_tokens })
  const callValues = d.daily.map(function (x) { return x.calls })

  const series = []
  if (f.series.cost) series.push({ name: 'cost', color: 'var(--primary)', values: costValues })
  if (f.series.tokens) series.push({ name: 'tokens', color: 'var(--info)', values: tokenValues })
  if (f.series.calls) series.push({ name: 'calls', color: 'var(--success)', values: callValues })

  const legend = [
    ['cost', 'Spend (🪙)', 'var(--primary)'],
    ['tokens', 'Tokens', 'var(--info)'],
    ['calls', 'Calls', 'var(--success)']
  ].map(function (row) {
