    return '<button data-action="toggle-series:' + row[0] + '" class="' + (on ? '' : 'off') + '"><i style="background:' + row[2] + '"></i>' + row[1] + '</button>'
  }).join('')

  const chart = series.length
    ? chartLines({ labels: labels, series: series, height: 200, aria: 'AI consumption over the window' })
    : '<div class="empty">' + icon('coins') + '<h3>No series selected</h3><p>Turn one back on with the legend above.</p></div>'

  const byProject = Object.keys(d.byProject).map(function (name) {
