.meta-item .l{font-size:10.5px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);margin-bottom:3px}
.meta-item .v{font-size:12.5px;font-weight:600}
.field-label{font-size:10.5px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);margin-bottom:6px}
.modal-wrap{position:fixed;inset:0;z-index:90;display:grid;place-items:center;padding:16px}
.modal{position:relative;width:min(420px,100%);background:var(--surface);border:1px solid var(--line-strong);
  border-radius:var(--r-l);box-shadow:var(--shadow);padding:16px;animation:fade 180ms}
.modal h3{margin:0 0 4px;font-size:15px}
.modal p{margin:0 0 12px;font-size:12.5px;color:var(--muted)}
.pick{display:flex;align-items:center;gap:10px;width:100%;text-align:left;padding:8px;border-radius:9px;border:1px solid transparent}
.pick:hover{background:var(--surface-2);border-color:var(--line)}

/* empty / error / skeleton */
.empty{display:flex;flex-direction:column;align-items:center;gap:8px;padding:34px 14px;text-align:center;color:var(--muted)}
.empty .ic{width:30px;height:30px;color:var(--muted);opacity:.7}
.empty h3{margin:4px 0 0;font-size:14px;color:var(--text)}
.empty p{margin:0;font-size:12.5px;max-width:340px}
.err{border:1px solid rgba(240,82,82,.4);background:rgba(240,82,82,.08);border-radius:var(--r);padding:14px;
  display:flex;gap:10px;align-items:flex-start}
.err .ic{color:var(--error)}
.sk{background:linear-gradient(90deg,rgba(255,255,255,.05),rgba(255,255,255,.11),rgba(255,255,255,.05));
  background-size:200% 100%;animation:shimmer 1.3s infinite;border-radius:8px}
@keyframes shimmer{0%{background-position:200% 0}100%{background-position:-200% 0}}

/* charts */
.chart{width:100%;height:auto;display:block}
.chart .grid-line{stroke:rgba(255,255,255,.07);stroke-width:1}
.chart .axis-text{fill:var(--muted);font-size:10px;font-family:var(--ui)}
.legend{display:flex;flex-wrap:wrap;gap:6px}
.legend button{display:inline-flex;align-items:center;gap:5px;font-size:11px;color:var(--dim);padding:3px 7px;border-radius:6px;border:1px solid transparent}
.legend button:hover{background:var(--surface-2)}
.legend button.off{opacity:.4;text-decoration:line-through}
.legend i{width:8px;height:8px;border-radius:2px;display:block}

/* assistant */
.assistant-fab{position:fixed;right:14px;bottom:76px;z-index:65;width:52px;height:52px;border-radius:50%;
  background:linear-gradient(135deg,var(--primary),var(--secondary));color:#fff;display:grid;place-items:center;
  box-shadow:0 10px 26px rgba(226,65,159,.4)}
.assistant{position:fixed;inset:auto 0 0 0;z-index:75;height:min(78vh,620px);background:var(--surface);
  border-top:1px solid var(--line-strong);border-radius:var(--r-l) var(--r-l) 0 0;box-shadow:var(--shadow);
  display:none;flex-direction:column}
.assistant.open{display:flex}
.assistant-head{display:flex;align-items:center;gap:9px;padding:12px 14px;border-bottom:1px solid var(--line)}
.assistant-msgs{flex:1;overflow-y:auto;padding:14px;display:flex;flex-direction:column;gap:10px}
.msg{max-width:92%;font-size:13px;line-height:1.55;padding:9px 12px;border-radius:12px;white-space:pre-wrap}
.msg.user{align-self:flex-end;background:var(--primary);color:#fff;border-bottom-right-radius:4px}
.msg.bot{align-self:flex-start;background:var(--surface-2);border:1px solid var(--line);border-bottom-left-radius:4px}
.msg .src{display:flex;flex-wrap:wrap;gap:5px;margin-top:8px}
.typing{display:inline-flex;gap:3px;align-items:center}
.typing i{width:5px;height:5px;border-radius:50%;background:var(--dim);animation:blink 1s infinite}
.typing i:nth-child(2){animation-delay:.15s}
.typing i:nth-child(3){animation-delay:.3s}
@keyframes blink{0%,100%{opacity:.25}50%{opacity:1}}
.assistant-suggest{display:flex;flex-wrap:wrap;gap:6px;padding:0 14px 10px}
.suggest{font-size:11.5px;padding:5px 9px;border-radius:999px;border:1px solid var(--line);color:var(--dim);background:var(--surface-2)}
.suggest:hover{color:var(--text);border-color:var(--line-strong)}
.assistant-input{display:flex;gap:8px;padding:10px 14px;border-top:1px solid var(--line);
  padding-bottom:max(10px,env(safe-area-inset-bottom))}
.assistant-input input{flex:1}

/* toasts */
.toasts{position:fixed;left:50%;transform:translateX(-50%);bottom:84px;z-index:95;display:flex;
  flex-direction:column;gap:8px;width:min(420px,calc(100% - 24px))}
.toast{display:flex;align-items:center;gap:9px;padding:10px 12px;border-radius:10px;background:var(--surface-3);
  border:1px solid var(--line-strong);box-shadow:var(--shadow);font-size:12.5px;animation:fade 200ms}
.toast .ic{flex:0 0 auto}
.toast.success .ic{color:var(--success)}
.toast.error .ic{color:var(--error)}
.toast.info .ic{color:var(--info)}

/* bottom nav */
.bottom-nav{position:fixed;left:0;right:0;bottom:0;z-index:50;display:grid;grid-auto-flow:column;
  grid-auto-columns:1fr;background:rgba(20,18,25,.96);backdrop-filter:blur(12px);border-top:1px solid var(--line);
  padding:6px 2px max(6px,env(safe-area-inset-bottom))}
.bn-item{display:flex;flex-direction:column;align-items:center;gap:2px;padding:5px 2px;border-radius:9px;
  color:var(--muted);font-size:9.5px;font-weight:600;position:relative}
.bn-item.active{color:var(--primary)}
.bn-item .ic{width:19px;height:19px}
.bn-item .bn-dot{position:absolute;top:2px;right:calc(50% - 14px);width:6px;height:6px;border-radius:50%;background:var(--error)}

/* responsive */
@media (min-width:640px){
  .kpis{grid-template-columns:repeat(3,minmax(0,1fr))}
  .meta-grid{grid-template-columns:1fr 1fr 1fr}
  .view{padding:18px 18px 96px}
}
@media (min-width:900px){
  .app{display:grid;grid-template-columns:var(--rail) minmax(0,1fr)}
  .rail{position:sticky;top:0;height:100vh;transform:none;box-shadow:none}
  .rail-backdrop{display:none}
  .bottom-nav{display:none}
  .only-mobile{display:none}
  .view{padding:20px 24px 40px}
  .topbar{padding:12px 24px}
  .two-col{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(0,1fr);gap:14px;align-items:start}
  .three-col{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
  .table-wrap{display:block}
  .cards-list{display:none}
  .assistant{inset:auto 20px 20px auto;width:400px;height:min(70vh,600px);border:1px solid var(--line-strong);border-radius:var(--r-l)}
  .assistant-fab{bottom:20px;right:20px}
  .toasts{bottom:20px;left:auto;right:20px;transform:none}
  .drawer{width:520px}
}
@media (max-width:899px){
  .table-wrap{display:none}
  .cards-list{display:block}
  .topbar{gap:8px;flex-wrap:wrap}
  .range-chips{order:3;width:100%;overflow-x:auto}
  .three-col{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:12px}
}
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{transition:none!important;animation:none!important}
}
