  <div id="overlay-root"></div>

  <button class="assistant-fab" data-action="open-assistant" aria-label="Ask the AI assistant" id="fab-assistant"></button>

  <section class="assistant" id="assistant" aria-label="AI assistant" role="dialog" aria-modal="false">
