    </div>
    <div class="assistant-msgs" id="assistant-msgs" aria-live="polite"></div>
    <div class="assistant-suggest" id="assistant-suggest"></div>
    <form class="assistant-input" id="assistant-form">
      <input class="field" id="assistant-input" type="text" placeholder="e.g. what is blocking payments?" aria-label="Ask a question" autocomplete="off" />
      <button class="btn primary" type="submit" aria-label="Send question" id="btn-assistant-send"></button>
