function fatal(message) {
  var el = document.getElementById('view');
  if (!el) return;
  el.innerHTML = '<div class="stack"><div class="err" role="alert">' +
    '<svg class="ic" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M12 3l9 16H3z"/><path d="M12 9v5"/></svg>' +
