    '<div style="font-size:11.5px;color:var(--muted);margin-top:6px">Open the browser console for the full stack trace.</div>' +
    '</div></div></div>';
}

window.addEventListener('error', function (ev) { fatal(ev && ev.message); });
window.addEventListener('unhandledrejection', function (ev) {
