  T({ p: 'p3', b: 'b7', n: 'Mobile-first dashboard navigation', s: 'doing', pr: 'high', a: ['u2'], d: 2, pg: 60, u: -1, h: 12 }),
  T({ p: 'p3', b: 'b7', n: 'Accessibility audit pass', s: 'todo', pr: 'high', a: [], d: 4, u: -9, h: 12 }),
  T({ p: 'p3', b: 'b7', n: 'Crashlytics alerts wiring', s: 'done', pr: 'medium', a: ['u8'], d: -2, u: -2, c: -14, h: 6 }),

  T({ p: 'p4', b: 'b8', n: 'Dashboard screenshots refresh', s: 'todo', pr: 'low', a: ['u7'], d: 8, u: -4, h: 3 }),
  T({ p: 'p4', b: 'b8', n: 'Budget & analytics feature page', s: 'doing', pr: 'medium', a: ['u7'], d: 3, pg: 70, u: -1, h: 8 }),
  T({ p: 'p4', b: 'b8', n: 'Team view documentation', s: 'todo', pr: 'medium', a: [], d: 12, u: -11, h: 5 }),
  T({ p: 'p4', b: 'b8', n: 'Changelog for increment 2', s: 'done', pr: 'low', a: ['u7'], d: -3, u: -3, c: -9, h: 3 }),
  T({ p: 'p4', b: 'b8', n: 'Docs search relevance fix', s: 'onhold', pr: 'low', a: ['a3'], d: 9, u: -5, h: 4, blk: 'Waiting on the new index format', bs: -7 })
];

var MODELS = [
  { name: 'gpt-4o-mini', in_rate: 0.15, out_rate: 0.6 },
  { name: 'claude-sonnet-4.5', in_rate: 3.0, out_rate: 15.0 },
  { name: 'qwen2.5-coder-32b', in_rate: 0.2, out_rate: 0.8 }
];

var BUDGET = { weekly: 6000, per_project: { p1: 2600, p2: 1800, p3: 1100, p4: 500 } };

function seeded(seed) {
  var s = seed;
  return function () {
    s = (s * 1664525 + 1013904223) % 4294967296;
    return s / 4294967296;
  };
}

var USAGE = (function () {
  var rnd = seeded(20260517);
  var rows = [];
  for (var back = 59; back >= 0; back -= 1) {
    var date = dayOffset(-back);
    for (var pi = 0; pi < PROJECTS.length; pi += 1) {
      var project = PROJECTS[pi];
      for (var mi = 0; mi < MODELS.length; mi += 1) {
        var model = MODELS[mi];
        if (rnd() > 0.62) continue;
        var humans = PEOPLE.filter(function (p) {
          return p.type === 'human' && p.projects.indexOf(project.id) >= 0;
        });
        var owner = humans[Math.floor(rnd() * humans.length)] || PEOPLE[0];
        var weight = model.name === 'claude-sonnet-4.5' ? 0.45 : 1;
        var input = Math.round((18000 + rnd() * 240000) * weight);
        var output = Math.round((4000 + rnd() * 54000) * weight);
        var calls = Math.max(2, Math.round((8 + rnd() * 90) * weight));
        rows.push({
          iso_date: date,
          project_id: project.id,
          model: model.name,
          username: owner.id,
          input_tokens: input,
          output_tokens: output,
          total_tokens: input + output,
          calls: calls,
          total_duration_seconds: Math.round(calls * (2 + rnd() * 9) * 10) / 10,
          total_cxjcoins: Math.round((input / 1000 * model.in_rate + output / 1000 * model.out_rate) * 100) / 100,
          tokens_from_provider: true
        });
      }
    }
  }
  return rows;
})();

/* ═══════════════════════════════════════════════════════════════════════════
   2. LOOKUPS + AGGREGATIONS
   ═══════════════════════════════════════════════════════════════════════════ */

function personById(id) { for (var i = 0; i < PEOPLE.length; i += 1) if (PEOPLE[i].id === id) return PEOPLE[i]; return null; }
function projectById(id) { for (var i = 0; i < PROJECTS.length; i += 1) if (PROJECTS[i].id === id) return PROJECTS[i]; return null; }
function boardById(id) { for (var i = 0; i < BOARDS.length; i += 1) if (BOARDS[i].id === id) return BOARDS[i]; return null; }

var DB = { tasks: TASKS.map(function (t) { return Object.assign({}, t); }) };
var DEV = { empty: false, error: false };

function rangeFromQuery(q) {
  var to = q.to || todayISO();
  if (q.from) return { from: q.from, to: to };
  if (q.start_date) return { from: q.start_date, to: q.end_date || to };
  var dt = new Date(to);
  dt.setDate(dt.getDate() - 7);
  return { from: isoDate(dt), to: to };
}

function inRange(iso, range) {
  if (!iso) return false;
  var date = String(iso).slice(0, 10);
  return date >= range.from && date <= range.to;
}

/** Tasks in the window = updated inside it PLUS every unfinished task. */
function windowTasks(range, projectIds) {
  return DB.tasks.filter(function (t) {
    if (projectIds && projectIds.length && projectIds.indexOf(t.project_id) < 0) return false;
    return inRange(t.updated_at, range) || t.status !== 'done';
  });
}

function daysUntil(iso) {
  if (!iso) return null;
  return Math.round((new Date(iso + 'T00:00:00') - new Date(todayISO() + 'T00:00:00')) / DAY);
}

function attentionReason(t) {
  if (t.blocked) return 'blocked';
  var dleft = daysUntil(t.due_date);
  if (dleft != null && dleft < 0 && t.status !== 'done') return 'overdue';
  if (dleft === 0 && t.status !== 'done') return 'due_today';
  if (t.priority === 'high' && !t.assignees.length && t.status !== 'done') return 'unassigned_high';
  var stale = Math.round((Date.now() - new Date(t.updated_at).getTime()) / DAY);
  if (stale >= 7 && t.status !== 'done') return 'stalled';
  return null;
}

var SEVERITY = { blocked: 4, overdue: 3, due_today: 2, unassigned_high: 1.5, stalled: 1 };

function toPlanningTask(t) {
  var project = projectById(t.project_id);
  var board = boardById(t.board_id);
  var dleft = daysUntil(t.due_date);
  return {
    id: t.id,
    name: t.name,
    project_id: t.project_id,
    project_name: project ? project.name : null,
    project_color: project ? project.color : null,
    board_id: t.board_id,
    board: board ? board.name : null,
    status: t.status,
    priority: t.priority,
    due_date: t.due_date,
    progress: t.progress,
    assignees: t.assignees,
    assignee_names: t.assignees.map(function (id) { var p = personById(id); return p ? p.name : id; }),
    estimate_h: t.estimate_h,
    tags: t.tags,
    created_at: t.created_at,
    updated_at: t.updated_at,
    blocked: t.blocked,
    block_reason: t.block_reason,
    blocked_since: t.blocked_since,
    days_until_due: dleft,
    unassigned: !t.assignees.length,
    attention_reason: attentionReason(t)
  };
}

function computeMetrics(tasks) {
  var m = {
    total: tasks.length, done: 0, active: 0, on_hold: 0, overdue: 0, due_today: 0,
    unassigned: 0, blocked: 0, completion: 0,
    by_priority: { high: 0, medium: 0, low: 0 },
    by_status: { todo: 0, doing: 0, onhold: 0, done: 0 }
  };
  tasks.forEach(function (t) {
    m.by_status[t.status] = (m.by_status[t.status] || 0) + 1;
    m.by_priority[t.priority] = (m.by_priority[t.priority] || 0) + 1;
    if (t.status !== 'done') {
      var dleft = daysUntil(t.due_date);
      if (dleft != null && dleft < 0) m.overdue += 1;
      if (dleft === 0) m.due_today += 1;
    }
    if (!t.assignees.length && t.status !== 'done') m.unassigned += 1;
    if (t.blocked) m.blocked += 1;
  });
  m.done = m.by_status.done || 0;
  m.active = (m.by_status.doing || 0) + (m.by_status.todo || 0);
  m.on_hold = m.by_status.onhold || 0;
  m.completion = tasks.length ? Math.round(m.done / tasks.length * 100) : 0;
  return m;
}

function activityFeed(tasks) {
  return tasks.slice().sort(function (a, b) { return a.updated_at < b.updated_at ? 1 : -1; }).slice(0, 26)
    .map(function (t) {
      var owner = t.assignees.length ? personById(t.assignees[0]) : null;
      var action = 'updated';
      var tone = 'info';
      if (t.status === 'done') { action = 'completed'; tone = 'success'; }
      else if (t.status === 'doing') { action = 'moved to In progress'; tone = 'primary'; }
      else if (t.status === 'onhold') { action = 'put on hold'; tone = 'warning'; }
      if (t.blocked) { action = 'flagged as blocked'; tone = 'error'; }
      var board = boardById(t.board_id);
      return {
        id: t.id + '-' + t.updated_at,
        actor: owner ? owner.name : 'Unassigned',
        action: action,
        target_task_id: t.id,
        target_task_name: t.name,
        board: board ? board.name : null,
        project_id: t.project_id,
        timestamp: t.updated_at,
        tone: tone
      };
    });
}

function boardProgress(tasks) {
  return BOARDS.map(function (board) {
    var rows = tasks.filter(function (t) { return t.board_id === board.id; });
    if (!rows.length) return null;
    var done = rows.filter(function (t) { return t.status === 'done'; }).length;
    return {
      board_id: board.id,
      board: board.name,
      project_id: board.project_id,
      project_name: (projectById(board.project_id) || {}).name,
      type: board.type,
      total: rows.length,
      done: done,
      doing: rows.filter(function (t) { return t.status === 'doing'; }).length,
      todo: rows.filter(function (t) { return t.status === 'todo'; }).length,
      on_hold: rows.filter(function (t) { return t.status === 'onhold'; }).length,
      overdue: rows.filter(function (t) { return attentionReason(t) === 'overdue'; }).length,
      blocked: rows.filter(function (t) { return t.blocked; }).length,
      percentage: Math.round(done / rows.length * 100),
      target_date: board.target_date,
      demo_date: board.demo_date
    };
  }).filter(Boolean);
}

/** PROPOSED endpoint — delivery forecast per board. */
function forecast(range) {
  var tasks = windowTasks(range, null);
  return boardProgress(tasks).map(function (b) {
    var doneInWindow = tasks.filter(function (t) {
      return t.board_id === b.board_id && t.status === 'done' && inRange(t.updated_at, range);
    }).length;
    var velocity = Math.round(Math.max(doneInWindow, 0.6) * 10) / 10;
    var remaining = b.total - b.done;
    var etaDays = Math.max(0, Math.round(remaining / Math.max(velocity, 0.5) * 7));
    var targetLeft = daysUntil(b.target_date);
    var status = 'on_track';
    var confidence = 'high';
    if (b.blocked > 0) { status = 'at_risk'; confidence = 'low'; }
    if (targetLeft != null && etaDays > targetLeft) {
      status = targetLeft < 0 ? 'late' : 'at_risk';
      confidence = targetLeft < 0 ? 'low' : 'medium';
    }
    return {
      board_id: b.board_id, board: b.board, project_id: b.project_id, project_name: b.project_name,
      type: b.type, committed: b.total, done: b.done, remaining: remaining, velocity: velocity,
      eta_date: dayOffset(etaDays), eta_days: etaDays, target_date: b.target_date, demo_date: b.demo_date,
      percentage: b.percentage, blocked: b.blocked, confidence: confidence, status: status
    };
  });
}

/** PROPOSED endpoint — burndown for one board. */
function burndown(boardId) {
  var board = boardById(boardId) || BOARDS[2];
  var rows = DB.tasks.filter(function (t) { return t.board_id === board.id; });
  var total = rows.length;
  var days = 14;
  var points = [];
  var completed = 0;
  for (var i = 0; i < days; i += 1) {
    var date = dayOffset(-(days - 1 - i));
    completed = rows.filter(function (t) { return t.status === 'done'; }).length;
    var ratio = i / (days - 1);
    var doneByNow = Math.round(completed * Math.pow(ratio, 0.85));
    points.push({
      date: date,
      ideal: Math.max(0, Math.round(total - (total / (days - 1)) * i)),
      actual: Math.max(0, total - doneByNow),
      remaining: Math.max(0, total - doneByNow)
    });
  }
  return { board_id: board.id, board: board.name, total: total, points: points };
}

/** PROPOSED endpoint — team load. */
function teamLoad(range) {
  var tasks = windowTasks(range, null);
  return PEOPLE.map(function (person) {
    var mine = tasks.filter(function (t) { return t.assignees.indexOf(person.id) >= 0; });
    var active = mine.filter(function (t) { return t.status === 'doing' || t.status === 'todo'; });
    var hours = active.reduce(function (s, t) { return s + t.estimate_h; }, 0);
    var cost = USAGE.filter(function (u) {
      return u.username === person.id && inRange(u.iso_date, range);
    }).reduce(function (s, u) { return s + u.total_cxjcoins; }, 0);
    var load = person.capacity ? Math.round(hours / person.capacity * 100) : Math.min(100, active.length * 12);
    return {
      id: person.id, name: person.name, role: person.role, type: person.type,
      capacity_h: person.capacity, hours: hours, load_pct: load,
      active: active.length,
      blocked: mine.filter(function (t) { return t.blocked; }).length,
      done: mine.filter(function (t) { return t.status === 'done'; }).length,
      overdue: mine.filter(function (t) { return attentionReason(t) === 'overdue'; }).length,
      cost: Math.round(cost * 10) / 10,
      project_ids: person.projects
    };
  });
}

function usageRows(q) {
  var range = rangeFromQuery(q);
  return USAGE.filter(function (u) {
    if (!inRange(u.iso_date, range)) return false;
    if (q.project_id && u.project_id !== q.project_id) return false;
    if (q.model && u.model !== q.model) return false;
    return true;
  });
}

function metricsOf(rows) {
  var acc = { input_tokens: 0, output_tokens: 0, total_tokens: 0, calls: 0, total_duration_seconds: 0, total_cxjcoins: 0, tokens_from_provider: true };
  rows.forEach(function (r) {
    acc.input_tokens += r.input_tokens;
    acc.output_tokens += r.output_tokens;
    acc.total_tokens += r.total_tokens;
    acc.calls += r.calls;
    acc.total_duration_seconds += r.total_duration_seconds;
    acc.total_cxjcoins += r.total_cxjcoins;
  });
  acc.total_duration_seconds = Math.round(acc.total_duration_seconds * 10) / 10;
  acc.total_cxjcoins = Math.round(acc.total_cxjcoins * 100) / 100;
  return acc;
}

function analyticsTotal(q) {
  var range = rangeFromQuery(q);
  var total = metricsOf(usageRows(q));
  var delivered = windowTasks(range, q.project_id ? [q.project_id] : null)
    .filter(function (t) { return t.status === 'done' && inRange(t.updated_at, range); }).length;
  total.delivered_tasks = delivered;
  total.cost_per_delivered_task = delivered ? Math.round(total.total_cxjcoins / delivered * 100) / 100 : null;
  return total;
}

function analyticsDaily(q) {
  var buckets = {};
  usageRows(q).forEach(function (u) {
    if (!buckets[u.iso_date]) {
      buckets[u.iso_date] = { period: u.iso_date, input_tokens: 0, output_tokens: 0, total_tokens: 0, calls: 0, total_duration_seconds: 0, total_cxjcoins: 0 };
    }
    var b = buckets[u.iso_date];
    b.input_tokens += u.input_tokens;
    b.output_tokens += u.output_tokens;
    b.total_tokens += u.total_tokens;
    b.calls += u.calls;
    b.total_duration_seconds += u.total_duration_seconds;
    b.total_cxjcoins += u.total_cxjcoins;
  });
  return Object.keys(buckets).sort().map(function (k) {
    buckets[k].total_cxjcoins = Math.round(buckets[k].total_cxjcoins * 100) / 100;
    return buckets[k];
  });
}

function analyticsBy(q, key) {
  var groups = {};
  usageRows(q).forEach(function (u) {
    var k = key === 'project' ? (projectById(u.project_id) || {}).name : key === 'user' ? u.username : u.model;
    if (!groups[k]) groups[k] = [];
    groups[k].push(u);
  });
  var out = {};
  Object.keys(groups).forEach(function (k) { out[k] = metricsOf(groups[k]); });
  return out;
}

/** PROPOSED endpoint — budget. */
function budgetPayload(q) {
  var range = rangeFromQuery(q);
  var spent = metricsOf(usageRows(q)).total_cxjcoins;
  var days = Math.max(1, Math.round((new Date(range.to) - new Date(range.from)) / DAY) + 1);
  var projected = Math.round(spent / days * 7);
  var perProject = PROJECTS.map(function (p) {
    var s = metricsOf(usageRows(Object.assign({}, q, { project_id: p.id }))).total_cxjcoins;
    return {
      project_id: p.id, project_name: p.name, color: p.color,
      budget: BUDGET.per_project[p.id],
      spent: Math.round(s * 100) / 100,
      pct: BUDGET.per_project[p.id] ? Math.round(s / BUDGET.per_project[p.id] * 100) : 0
    };
  });
  return {
    weekly_budget: BUDGET.weekly,
    spent: Math.round(spent * 100) / 100,
    remaining: Math.round((BUDGET.weekly - projected) * 100) / 100,
    projected: projected,
    pct: Math.round(projected / BUDGET.weekly * 100),
    per_project: perProject
  };
}

/* ═══════════════════════════════════════════════════════════════════════════
   3. MOCK SERVER — no URL, no fetch, no origin dependency
   ═══════════════════════════════════════════════════════════════════════════ */

function parseRequest(input) {
  var raw = String(input || '');
  var qi = raw.indexOf('?');
  var pathname = qi >= 0 ? raw.slice(0, qi) : raw;
  var search = qi >= 0 ? raw.slice(qi + 1) : '';
  var query = {};
  if (search) {
    search.split('&').forEach(function (pair) {
      if (!pair) return;
      var ei = pair.indexOf('=');
      var k = ei >= 0 ? pair.slice(0, ei) : pair;
      var v = ei >= 0 ? pair.slice(ei + 1) : '';
      try { query[decodeURIComponent(k)] = decodeURIComponent(v); } catch (e) { query[k] = v; }
    });
  }
  return { pathname: pathname, query: query };
}

var routes = [
  { method: 'GET', path: /^\/api\/projects$/, handler: function () { return DEV.empty ? [] : PROJECTS; } },
  { method: 'GET', path: /^\/api\/boards$/, handler: function () {
    if (DEV.empty) return [];
    return BOARDS.map(function (b) {
      var rows = DB.tasks.filter(function (t) { return t.board_id === b.id; });
      var project = projectById(b.project_id) || {};
      return Object.assign({}, b, {
        total: rows.length,
        done: rows.filter(function (t) { return t.status === 'done'; }).length,
        project_name: project.name,
        project_color: project.color
      });
    });
  } },
  { method: 'GET', path: /^\/api\/teams$/, handler: function () {
    return [
      { id: 'team-1', name: 'Platform', members: PEOPLE.filter(function (p) { return p.projects.indexOf('p1') >= 0; }).map(function (p) { return p.id; }) },
      { id: 'team-2', name: 'Payments', members: PEOPLE.filter(function (p) { return p.projects.indexOf('p2') >= 0; }).map(function (p) { return p.id; }) }
    ];
  } },
  { method: 'GET', path: /^\/api\/planning\/dashboard$/, handler: function (ctx) {
    var range = rangeFromQuery(ctx.query);
    var tasks = windowTasks(range, ctx.query.project_id ? [ctx.query.project_id] : null);
    var metrics = computeMetrics(tasks);
    var attention = tasks.map(toPlanningTask)
      .filter(function (t) { return t.attention_reason; })
      .sort(function (a, b) { return (SEVERITY[b.attention_reason] || 0) - (SEVERITY[a.attention_reason] || 0); })
      .map(function (t) { return { task: t, reason: t.attention_reason, severity: SEVERITY[t.attention_reason] || 0 }; });
    return {
      metrics: DEV.empty ? computeMetrics([]) : metrics,
      board_progress: DEV.empty ? [] : boardProgress(tasks),
      attention: DEV.empty ? [] : attention,
      activity: DEV.empty ? [] : activityFeed(tasks),
      priority_counts: metrics.by_priority,
      generated_at: new Date().toISOString()
    };
  } },
  { method: 'POST', path: /^\/api\/planning\/tasks\/query$/, handler: function (ctx) {
    var body = ctx.body || {};
    var range = body.range ? { from: body.range.from, to: body.range.to } : rangeFromQuery({});
    var rows = DEV.empty ? [] : windowTasks(range, body.project_ids || null);

    if (body.boards && body.boards.length) rows = rows.filter(function (t) { return body.boards.indexOf(t.board_id) >= 0; });
    if (body.statuses && body.statuses.length) rows = rows.filter(function (t) { return body.statuses.indexOf(t.status) >= 0; });
    if (body.priorities && body.priorities.length) rows = rows.filter(function (t) { return body.priorities.indexOf(t.priority) >= 0; });
    if (body.assignees && body.assignees.length) {
      rows = rows.filter(function (t) {
        return t.assignees.some(function (a) { return body.assignees.indexOf(a) >= 0; });
      });
    }
    if (body.only_blocked) rows = rows.filter(function (t) { return t.blocked; });
    if (body.search) {
      var q = String(body.search).toLowerCase();
      rows = rows.filter(function (t) { return (t.name + ' ' + t.tags.join(' ')).toLowerCase().indexOf(q) >= 0; });
    }

    var groupCounts = ['todo', 'doing', 'onhold', 'done'].map(function (s) {
      return { key: s, total: rows.filter(function (t) { return t.status === s; }).length };
    });

    var sort = body.sort || { field: 'priority', dir: 'asc' };
    var weight = { high: 0, medium: 1, low: 2 };
    rows = rows.slice().sort(function (a, b) {
      var cmp = 0;
      if (sort.field === 'priority') cmp = (weight[a.priority] || 2) - (weight[b.priority] || 2);
      else if (sort.field === 'due_date') cmp = String(a.due_date || '9999').localeCompare(String(b.due_date || '9999'));
      else if (sort.field === 'status') cmp = String(a.status).localeCompare(String(b.status));
      else if (sort.field === 'name') cmp = a.name.localeCompare(b.name);
      else cmp = String(a.updated_at).localeCompare(String(b.updated_at));
      return sort.dir === 'desc' ? -cmp : cmp;
    });

    var pageSize = body.page_size || 12;
    var page = body.page || 1;
    var total = rows.length;
    var totalPages = Math.max(1, Math.ceil(total / pageSize));
    return {
      tasks: rows.slice((page - 1) * pageSize, page * pageSize).map(toPlanningTask),
      total: total, page: page, page_size: pageSize,
      total_pages: totalPages, has_next: page < totalPages, has_prev: page > 1,
      group_counts: groupCounts,
      generated_at: new Date().toISOString()
    };
  } },
  { method: 'PATCH', path: /^\/api\/planning\/tasks\/([^/]+)$/, handler: function (ctx) {
    var id = ctx.params[0];
    var task = null;
    for (var i = 0; i < DB.tasks.length; i += 1) if (DB.tasks[i].id === id) task = DB.tasks[i];
    if (!task) return { notFound: true };
    var body = ctx.body || {};
    if ('status' in body) task.status = body.status;
    if ('priority' in body) task.priority = body.priority;
    if ('due_date' in body) task.due_date = body.due_date || null;
    if ('progress' in body) task.progress = Math.max(0, Math.min(100, Number(body.progress) || 0));
    if ('assignees' in body) task.assignees = body.assignees || [];
    if ('blocked' in body) {
      task.blocked = !!body.blocked;
      task.block_reason = body.blocked ? (body.block_reason || task.block_reason || 'Blocked') : null;
      task.blocked_since = body.blocked ? new Date().toISOString() : null;
    }
    task.updated_at = new Date().toISOString();
    if (task.status === 'done') task.progress = 100;
    persistPatch(task);
    return { task: toPlanningTask(task) };
  } },
  { method: 'GET', path: /^\/api\/planning\/forecast$/, handler: function (ctx) { return DEV.empty ? [] : forecast(rangeFromQuery(ctx.query)); } },
  { method: 'GET', path: /^\/api\/planning\/burndown$/, handler: function (ctx) { return burndown(ctx.query.board_id); } },
  { method: 'GET', path: /^\/api\/planning\/team-load$/, handler: function (ctx) { return DEV.empty ? [] : teamLoad(rangeFromQuery(ctx.query)); } },
  { method: 'GET', path: /^\/api\/analytics\/admin\/total$/, handler: function (ctx) { return analyticsTotal(ctx.query); } },
  { method: 'GET', path: /^\/api\/analytics\/admin\/daily$/, handler: function (ctx) { return analyticsDaily(ctx.query); } },
  { method: 'GET', path: /^\/api\/analytics\/admin\/by-project$/, handler: function (ctx) { return analyticsBy(ctx.query, 'project'); } },
  { method: 'GET', path: /^\/api\/analytics\/admin\/by-model$/, handler: function (ctx) { return analyticsBy(ctx.query, 'model'); } },
  { method: 'GET', path: /^\/api\/analytics\/admin\/by-user$/, handler: function (ctx) { return analyticsBy(ctx.query, 'user'); } },
  { method: 'GET', path: /^\/api\/analytics\/admin\/budget$/, handler: function (ctx) { return budgetPayload(ctx.query); } },
  { method: 'POST', path: /^\/api\/assistant\/ask$/, handler: function (ctx) {
    var body = ctx.body || {};
    return assistantAnswer(body.question, { from: body.from, to: body.to });
  } }
];

function mockFetch(input, init) {
  var options = init || {};
  var method = (options.method || 'GET').toUpperCase();
  var req = parseRequest(input);
  var match = null;
  for (var i = 0; i < routes.length; i += 1) {
    if (routes[i].method === method && routes[i].path.test(req.pathname)) { match = routes[i]; break; }
  }
  return new Promise(function (resolve) {
    setTimeout(function () {
      if (DEV.error) { resolve({ ok: false, status: 500, data: { detail: 'Simulated 500 — the dev menu error toggle is on.' } }); return; }
      if (!match) { resolve({ ok: false, status: 404, data: { detail: 'not_found: ' + method + ' ' + req.pathname } }); return; }
      var params = req.pathname.match(match.path);
      var body = null;
      if (options.body) { try { body = JSON.parse(options.body); } catch (e) { body = null; } }
      try {
        var result = match.handler({ params: params ? params.slice(1) : [], query: req.query, body: body });
        if (result && result.notFound) { resolve({ ok: false, status: 404, data: { detail: 'not_found' } }); return; }
        resolve({ ok: true, status: 200, data: result });
      } catch (error) {
        resolve({ ok: false, status: 500, data: { detail: String((error && error.message) || error) } });
      }
    }, 90 + Math.random() * 140);
  });
}

var cache = {};

function invalidateCache() { cache = {}; }

function api(path, options) {
  var opts = options || {};
  var method = opts.method || 'GET';
  var key = method === 'GET' ? path : null;
  if (key && Object.prototype.hasOwnProperty.call(cache, key)) return Promise.resolve(cache[key]);
  return mockFetch(path, { method: method, body: opts.body ? JSON.stringify(opts.body) : undefined })
    .then(function (res) {
      if (!res.ok) {
        var error = new Error((res.data && res.data.detail) || 'Request failed');
        error.status = res.status;
        throw error;
      }
      if (key) cache[key] = res.data;
      return res.data;
    });
}

/* ═══════════════════════════════════════════════════════════════════════════
   4. ASSISTANT (answers computed from the same mock data)
   ═══════════════════════════════════════════════════════════════════════════ */

function assistantAnswer(question, range) {
  var q = String(question || '').toLowerCase();
  var tasks = windowTasks(range, null).map(toPlanningTask);
  var attention = tasks.filter(function (t) { return t.attention_reason; }).sort(function (a, b) {
    return (SEVERITY[b.attention_reason] || 0) - (SEVERITY[a.attention_reason] || 0);
  });
  var usage = metricsOf(usageRows({ start_date: range.from, end_date: range.to }));

  function label(t) { return t.name + ' — ' + t.project_name + ' · ' + (t.assignee_names[0] || 'unassigned'); }
  function age(iso) { return Math.abs(Math.round((Date.now() - new Date(iso).getTime()) / DAY)); }

  if (/block|stuck|stopp|stall|risk/.test(q)) {
    var blocked = attention.filter(function (t) { return t.attention_reason === 'blocked'; });
    if (!blocked.length) {
      return {
        answer: 'Nothing is blocked in this window. ' + attention.length + ' task(s) still need attention (overdue, due today or unassigned).',
        sources: [{ route: 'blockers', label: 'Blockers' }]
      };
    }
    var lines = blocked.slice(0, 5).map(function (t) {
      return '• ' + label(t) + ' — blocked ' + age(t.blocked_since) + 'd: ' + t.block_reason;
    });
    return {
      answer: blocked.length + ' task(s) are blocked:\n' + lines.join('\n') +
        '\n\nThe oldest blocker is ' + age(blocked[0].blocked_since) + ' days old — that is the one to escalate today.',
      sources: [{ route: 'blockers', label: 'Blockers' }, { route: 'work', label: 'Work' }]
    };
  }

  if (/cost|spend|budget|token|model|consum|money/.test(q)) {
    var budget = budgetPayload({ start_date: range.from, end_date: range.to });
    var byProject = analyticsBy({ start_date: range.from, end_date: range.to }, 'project');
    var top = Object.keys(byProject).sort(function (a, b) { return byProject[b].total_cxjcoins - byProject[a].total_cxjcoins; });
    var perTask = analyticsTotal({ start_date: range.from, end_date: range.to }).cost_per_delivered_task;
    return {
      answer: 'In this window the platform burned ' + fmtCoins(usage.total_cxjcoins) + ' over ' + fmtNum(usage.calls) +
        ' calls (' + fmtTokens(usage.total_tokens) + ' tokens).\n' +
        '• Biggest project: ' + (top[0] || 'n/a') + ' with ' + (top[0] ? fmtCoins(byProject[top[0]].total_cxjcoins) : '—') + '\n' +
        '• Projected week: ' + fmtCoins(budget.projected) + ' against a ' + fmtCoins(budget.weekly_budget) + ' budget (' + budget.pct + '%)\n' +
        '• Cost per delivered task: ' + (perTask != null ? fmtCoins(perTask) : 'n/a'),
      sources: [{ route: 'cost', label: 'Cost & AI' }]
    };
  }

  if (/who|team|load|capacity|overload|busy/.test(q)) {
    var load = teamLoad(range).filter(function (p) { return p.type === 'human'; })
      .sort(function (a, b) { return b.load_pct - a.load_pct; });
    var hot = load.filter(function (p) { return p.load_pct >= 85; });
    return {
      answer: (hot.length ? hot.length + ' people are above 85% load.' : 'Nobody is above 85% load.') + '\n' +
        load.slice(0, 4).map(function (p) {
          return '• ' + p.name + ' (' + p.role + ') — ' + p.load_pct + '% load · ' + p.active + ' active · ' + p.blocked + ' blocked';
        }).join('\n'),
      sources: [{ route: 'team', label: 'Team' }]
    };
  }

  if (/ship|deliver|forecast|when|eta|demo|next week/.test(q)) {
    var fc = forecast(range);
    var risk = fc.filter(function (b) { return b.status !== 'on_track'; });
    var demos = fc.filter(function (b) { return b.demo_date; })
      .sort(function (a, b) { return a.demo_date < b.demo_date ? -1 : 1; });
    return {
      answer: 'Next demos:\n' + (demos.map(function (b) {
        return '• ' + b.board + ' — demo ' + fmtDate(b.demo_date) + ' · ' + b.done + '/' + b.committed + ' done · ' + b.status.replace('_', ' ');
      }).join('\n') || '• none scheduled') + '\n' +
        (risk.length ? risk.length + ' board(s) at risk: ' + risk.map(function (b) { return b.board; }).join(', ') + '.' : 'All boards are on track.'),
      sources: [{ route: 'delivery', label: 'Delivery' }]
    };
  }

  if (/overdue|late|behind/.test(q)) {
    var late = attention.filter(function (t) { return t.attention_reason === 'overdue'; });
    if (!late.length) return { answer: 'Nothing is overdue in this window.', sources: [{ route: 'blockers', label: 'Blockers' }] };
    return {
      answer: late.length + ' overdue task(s):\n' + late.slice(0, 6).map(function (t) {
        return '• ' + label(t) + ' — ' + Math.abs(t.days_until_due) + 'd late';
      }).join('\n'),
      sources: [{ route: 'blockers', label: 'Blockers' }]
    };
  }

  if (/done|finish|completed|delivered|this week/.test(q)) {
    var done = tasks.filter(function (t) { return t.status === 'done'; });
    return {
      answer: done.length + ' task(s) completed in this window:\n' +
        (done.slice(0, 6).map(function (t) { return '• ' + label(t); }).join('\n') || '• nothing yet'),
      sources: [{ route: 'work', label: 'Work' }]
    };
  }

  var m = computeMetrics(windowTasks(range, null));
  return {
    answer: 'State of play for this window:\n' +
      '• ' + m.active + ' active, ' + m.blocked + ' blocked, ' + m.overdue + ' overdue\n' +
      '• ' + m.done + ' completed (' + m.completion + '% of everything in scope)\n' +
      '• AI spend ' + fmtCoins(usage.total_cxjcoins) + '\n\n' +
      'Ask me about blockers, costs, team load, what ships next, or what we finished.',
    sources: [{ route: 'pulse', label: 'Pulse' }]
  };
}

