function safeGet(key) {
  try { return window.localStorage.getItem(key); } catch (e) { return null; }
}
function safeSet(key, value) {
  try { window.localStorage.setItem(key, value); } catch (e) { /* sandboxed or blocked — memory only */ }
}

function saveState() {
  safeSet(STORE_KEY, JSON.stringify({
    route: state.route,
    range: state.range,
    filters: state.filters,
    assistant: state.assistant.messages.slice(-12)
  }));
}

function loadState() {
  var raw = safeGet(STORE_KEY);
  if (!raw) return;
  try {
    var saved = JSON.parse(raw);
    if (saved.route && ROUTES.some(function (r) { return r.id === saved.route; })) state.route = saved.route;
    if (saved.range && RANGES.some(function (r) { return r.id === saved.range; })) state.range = saved.range;
    if (saved.filters) {
      Object.keys(state.filters).forEach(function (scope) {
        if (saved.filters[scope]) state.filters[scope] = Object.assign(state.filters[scope], saved.filters[scope]);
      });
    }
    if (Array.isArray(saved.assistant)) state.assistant.messages = saved.assistant;
  } catch (e) { /* corrupted store — start fresh */ }
}

function persistPatch(task) {
  var key = STORE_KEY + '.patches';
  var patches = {};
  try { patches = JSON.parse(safeGet(key) || '{}'); } catch (e) { patches = {}; }
  patches[task.id] = {
    status: task.status, priority: task.priority, due_date: task.due_date,
    progress: task.progress, assignees: task.assignees, blocked: task.blocked,
    block_reason: task.block_reason, updated_at: task.updated_at
  };
  safeSet(key, JSON.stringify(patches));
}

function applyPersistedPatches() {
  var patches = {};
  try { patches = JSON.parse(safeGet(STORE_KEY + '.patches') || '{}'); } catch (e) { return; }
  Object.keys(patches).forEach(function (id) {
    for (var i = 0; i < DB.tasks.length; i += 1) {
      if (DB.tasks[i].id === id) Object.assign(DB.tasks[i], patches[id]);
    }
  });
}

function bounds() {
  var to = todayISO();
  function back(days) { var dt = new Date(); dt.setDate(dt.getDate() - days); return isoDate(dt); }
  if (state.range === 'today') return { from: to, to: to };
  if (state.range === 'month') return { from: back(30), to: to };
  if (state.range === 'quarter') return { from: back(90), to: to };
  return { from: back(7), to: to };
}

function planningQS() {
  var b = bounds();
  return 'from=' + b.from + '&to=' + b.to;
}

function analyticsQS(extra) {
  var b = bounds();
  var qs = 'start_date=' + b.from + '&end_date=' + b.to;
  if (extra && extra.project_name) qs += '&project_name=' + encodeURIComponent(extra.project_name);
  if (extra && extra.model) qs += '&model=' + encodeURIComponent(extra.model);
  return qs;
}

/* ═══════════════════════════════════════════════════════════════════════════
   6. FORMATTERS + CHARTS + ICONS
   ═══════════════════════════════════════════════════════════════════════════ */

function esc(value) {
  return String(value == null ? '' : value).replace(/[&<>"']/g, function (c) {
    return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
  });
}
function fmtNum(n) {
  if (n == null) return '—';
  if (Math.abs(n) >= 1000000) return (n / 1000000).toFixed(1) + 'M';
  if (Math.abs(n) >= 1000) return (n / 1000).toFixed(1) + 'K';
  return String(Math.round(n * 10) / 10);
}
function fmtTokens(n) { return fmtNum(n); }
function fmtCoins(n) {
  if (n == null) return '—';
  if (Math.abs(n) >= 1000000) return (n / 1000000).toFixed(2) + 'M cx';
  if (Math.abs(n) >= 1000) return (n / 1000).toFixed(1) + 'K cx';
  return Math.round(n * 10) / 10 + ' cx';
}
function fmtDate(iso) {
  if (!iso) return '—';
  var dt = new Date(String(iso).slice(0, 10) + 'T12:00:00');
  return dt.toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
}
function relTime(iso) {
  if (!iso) return '—';
  var mins = Math.round((Date.now() - new Date(iso).getTime()) / 60000);
  if (mins < 2) return 'just now';
  if (mins < 60) return mins + 'm ago';
  var hours = Math.round(mins / 60);
  if (hours < 24) return hours + 'h ago';
  var days = Math.round(hours / 24);
  if (days < 30) return days + 'd ago';
  return Math.round(days / 30) + 'mo ago';
}
function dueLabel(task) {
  if (!task.due_date) return { text: 'no due date', cls: 'muted' };
  var d = task.days_until_due;
  if (d == null) return { text: fmtDate(task.due_date), cls: 'muted' };
  if (d < 0) return { text: Math.abs(d) + 'd late', cls: 'error' };
  if (d === 0) return { text: 'due today', cls: 'warning' };
  if (d === 1) return { text: 'due tomorrow', cls: 'warning' };
  return { text: fmtDate(task.due_date), cls: 'muted' };
}
function initials(name) {
  return String(name || '?').split(/[\s-]+/).map(function (w) { return w.charAt(0); }).slice(0, 2).join('').toUpperCase();
}
function personColor(id) {
  var palette = ['#e2419f', '#38bdf8', '#22c55e', '#f59e0b', '#a855f7', '#14b8a6', '#f05252', '#6366f1'];
  var sum = 0;
  String(id).split('').forEach(function (c) { sum += c.charCodeAt(0); });
  return palette[sum % palette.length];
}

function pill(text, cls) { return '<span class="pill ' + (cls || '') + '">' + esc(text) + '</span>'; }
function statusPill(status) {
  var meta = STATUS_META[status] || STATUS_META.todo;
  return pill(meta.label, meta.cls);
}
function priorityPill(priority) {
  var meta = PRIORITY_META[priority] || PRIORITY_META.low;
  return '<span class="pill ' + meta.cls + '"><span class="dotp" style="background:' + meta.color + '"></span>' + meta.label + '</span>';
}
function projectChip(projectId) {
  var p = projectById(projectId);
  if (!p) return '';
  return '<span class="proj-chip"><i style="background:' + p.color + '"></i>' + esc(p.name) + '</span>';
}
function avatarHtml(personId, size) {
  var p = personById(personId);
  if (!p) return '<span class="avatar ' + (size || 'sm') + '">?</span>';
  var style = p.type === 'agent' ? '' : 'background:' + personColor(p.id);
  return '<span class="avatar ' + (size || 'sm') + (p.type === 'agent' ? ' agent' : '') + '" style="' + style + '" title="' + esc(p.name) + '">' +
    esc(initials(p.name)) + '</span>';
}
function assigneeStack(task) {
  if (!task.assignees || !task.assignees.length) return '<span class="pill muted">unassigned</span>';
  return task.assignees.slice(0, 3).map(function (id) { return avatarHtml(id, 'sm'); }).join('');
}
function bar(pct, color) {
  var width = Math.max(0, Math.min(100, pct || 0));
  return '<div class="bar"><span style="width:' + width + '%;background:' + (color || 'var(--primary)') + '"></span></div>';
}

function chartLines(opts) {
  var labels = opts.labels || [];
  var series = opts.series || [];
  var H = opts.height || 180;
  var fmt = opts.fmt || fmtNum;
  var W = 720, padL = 52, padR = 10, padT = 12, padB = 24;
  var iw = W - padL - padR;
  var ih = H - padT - padB;
  var all = [];
  series.forEach(function (s) { all = all.concat(s.values); });
  var max = Math.max(1, Math.max.apply(null, all.length ? all : [1]));
  function x(i) { return padL + (labels.length <= 1 ? iw / 2 : (i / (labels.length - 1)) * iw); }
  function y(v) { return padT + ih - (v / max) * ih; }
  var grid = [0, 0.25, 0.5, 0.75, 1].map(function (r) {
    var gy = padT + ih - r * ih;
    return '<line class="grid-line" x1="' + padL + '" y1="' + gy + '" x2="' + (W - padR) + '" y2="' + gy + '"/>' +
      '<text class="axis-text" x="' + (padL - 6) + '" y="' + (gy + 3) + '" text-anchor="end">' + esc(fmt(max * r)) + '</text>';
  }).join('');
  var step = Math.max(1, Math.ceil(labels.length / 6));
  var xLabels = labels.map(function (label, i) {
    if (i % step !== 0 && i !== labels.length - 1) return '';
    return '<text class="axis-text" x="' + x(i) + '" y="' + (H - 6) + '" text-anchor="middle">' + esc(label) + '</text>';
  }).join('');
  var paths = series.map(function (s) {
    var d = s.values.map(function (v, i) { return (i ? 'L' : 'M') + x(i).toFixed(1) + ' ' + y(v).toFixed(1); }).join(' ');
    var area = d + ' L' + x(s.values.length - 1).toFixed(1) + ' ' + (padT + ih) + ' L' + x(0).toFixed(1) + ' ' + (padT + ih) + ' Z';
    return '<path d="' + area + '" fill="' + s.color + '" opacity=".10"/>' +
      '<path d="' + d + '" fill="none" stroke="' + s.color + '" stroke-width="2.2" stroke-linejoin="round" stroke-linecap="round"/>';
  }).join('');
  return '<svg class="chart" viewBox="0 0 ' + W + ' ' + H + '" role="img" aria-label="' + esc(opts.aria || 'chart') + '">' +
    grid + paths + xLabels + '</svg>';
}

function chartBurndown(points) {
  var W = 720, H = 170, padL = 40, padR = 10, padT = 12, padB = 22;
  var iw = W - padL - padR;
  var ih = H - padT - padB;
  var max = Math.max(1, Math.max.apply(null, points.map(function (p) { return Math.max(p.ideal, p.actual); })));
  function x(i) { return padL + (points.length <= 1 ? 0 : (i / (points.length - 1)) * iw); }
  function y(v) { return padT + ih - (v / max) * ih; }
  function line(key, color, dash) {
    var d = points.map(function (p, i) { return (i ? 'L' : 'M') + x(i).toFixed(1) + ' ' + y(p[key]).toFixed(1); }).join(' ');
    return '<path d="' + d + '" fill="none" stroke="' + color + '" stroke-width="2.2"' + (dash ? ' stroke-dasharray="5 5"' : '') + '/>';
  }
  var grid = [0, 0.5, 1].map(function (r) {
    var gy = padT + ih - r * ih;
    return '<line class="grid-line" x1="' + padL + '" y1="' + gy + '" x2="' + (W - padR) + '" y2="' + gy + '"/>' +
      '<text class="axis-text" x="' + (padL - 6) + '" y="' + (gy + 3) + '" text-anchor="end">' + Math.round(max * r) + '</text>';
  }).join('');
  var xl = points.map(function (p, i) {
    if (i % 3 !== 0 && i !== points.length - 1) return '';
    return '<text class="axis-text" x="' + x(i) + '" y="' + (H - 5) + '" text-anchor="middle">' + esc(fmtDate(p.date)) + '</text>';
  }).join('');
  return '<svg class="chart" viewBox="0 0 ' + W + ' ' + H + '" role="img" aria-label="Burndown chart">' +
    grid + line('ideal', 'rgba(255,255,255,.35)', true) + line('actual', 'var(--primary)', false) + xl + '</svg>';
}

