/* ═══════════════════════════════════════════════════════════════════════════
   7. LOADERS
   ═══════════════════════════════════════════════════════════════════════════ */

function workBody() {
  var f = state.filters.work;
  var b = bounds();
  var body = {
    range: { from: b.from, to: b.to },
    project_ids: f.project === 'all' ? [] : [f.project],
    boards: f.board === 'all' ? [] : [f.board],
    statuses: f.status === 'all' ? [] : [f.status],
    priorities: f.priority === 'all' ? [] : [f.priority],
    assignees: f.assignee === 'all' ? [] : [f.assignee],
    search: f.q,
    sort: { field: f.sort, dir: f.dir },
    page: f.page,
    page_size: f.page_size
  };
  return body;
}

function loadPulse() {
  var qs = planningQS();
  var aqs = analyticsQS();
  return Promise.all([
    api('/api/projects'),
    api('/api/planning/dashboard?' + qs),
    api('/api/planning/forecast?' + qs),
    api('/api/planning/team-load?' + qs),
    api('/api/analytics/admin/daily?' + aqs),
    api('/api/analytics/admin/total?' + aqs),
    api('/api/analytics/admin/budget?' + aqs)
  ]).then(function (r) {
    return { projects: r[0], dashboard: r[1], forecast: r[2], teamLoad: r[3], daily: r[4], total: r[5], budget: r[6] };
  });
}

function loadWork() {
  return Promise.all([
    api('/api/boards'),
    api('/api/planning/tasks/query', { method: 'POST', body: workBody() })
  ]).then(function (r) {
    return Object.assign({ boards: r[0] }, r[1]);
  });
}

function loadBlockers() {
  return api('/api/planning/dashboard?' + planningQS()).then(function (dashboard) {
    return { dashboard: dashboard };
  });
}

function loadDelivery() {
  var qs = planningQS();
  return Promise.all([
    api('/api/planning/forecast?' + qs),
    api('/api/planning/burndown?board_id=' + encodeURIComponent(state.filters.delivery.board))
  ]).then(function (r) {
    return { forecast: r[0], burndown: r[1] };
  });
}

function loadTeam() {
  return api('/api/planning/team-load?' + planningQS()).then(function (teamLoadData) {
    return { teamLoad: teamLoadData };
  });
}

function loadCost() {
  var f = state.filters.cost;
  var extra = { model: f.model === 'all' ? null : f.model };
  var qs = 'start_date=' + bounds().from + '&end_date=' + bounds().to +
    (f.project === 'all' ? '' : '&project_id=' + f.project) +
    (extra.model ? '&model=' + encodeURIComponent(extra.model) : '');
  return Promise.all([
    api('/api/analytics/admin/total?' + qs),
    api('/api/analytics/admin/daily?' + qs),
    api('/api/analytics/admin/by-project?' + qs),
    api('/api/analytics/admin/by-model?' + qs),
    api('/api/analytics/admin/by-user?' + qs),
    api('/api/analytics/admin/budget?' + qs)
  ]).then(function (r) {
    return { total: r[0], daily: r[1], byProject: r[2], byModel: r[3], byUser: r[4], budget: r[5] };
  });
}

var LOADERS = {
  pulse: loadPulse,
  work: loadWork,
  blockers: loadBlockers,
  delivery: loadDelivery,
  team: loadTeam,
  cost: loadCost
};

var loadToken = 0;

function loadRoute(id) {
  if (!LOADERS[id]) return Promise.resolve();
  var token = ++loadToken;
  state.loading[id] = true;
  state.errors[id] = null;
  renderView();
  return LOADERS[id]().then(function (data) {
    if (token !== loadToken) return;
    state.data[id] = data;
    state.loading[id] = false;
    if (data.dashboard && data.dashboard.attention) state.alerts = data.dashboard.attention.length;
    renderShell();
    renderView();
    saveState();
  })['catch'](function (error) {
    if (token !== loadToken) return;
    state.loading[id] = false;
    state.errors[id] = (error && error.message) || 'Unknown error';
    renderShell();
    renderView();
  });
}

/* ═══════════════════════════════════════════════════════════════════════════
   8. VIEWS
   ═══════════════════════════════════════════════════════════════════════════ */

function routeMeta(id) {
  for (var i = 0; i < ROUTES.length; i += 1) if (ROUTES[i].id === id) return ROUTES[i];
  return ROUTES[0];
}

function skeleton() {
  return '<div class="stack"><div class="sk" style="height:74px"></div>' +
    '<div class="grid" style="grid-template-columns:repeat(2,minmax(0,1fr))">' +
    new Array(6).join('.') .split('').map(function () { return '<div class="sk" style="height:78px"></div>'; }).join('') +
    '</div><div class="sk" style="height:220px"></div></div>';
}

function errorCard(message) {
  return '<div class="err" role="alert">' + icon('alert') +
    '<div style="flex:1"><div style="font-weight:700;font-size:13.5px;margin-bottom:2px">Could not load this section</div>' +
    '<div style="font-size:12.5px;color:var(--dim)">' + esc(message) + '</div></div>' +
    '<button class="btn sm" data-action="retry">' + icon('refresh', 'ic-sm') + 'Retry</button></div>';
}

function emptyCard(title, text, actionLabel, action) {
  return '<div class="empty">' + icon('folder') + '<h3>' + esc(title) + '</h3><p>' + esc(text) + '</p>' +
    (actionLabel ? '<button class="btn sm" data-action="' + action + '">' + esc(actionLabel) + '</button>' : '') + '</div>';
}

function card(title, sub, body, action) {
  return '<section class="card"><div class="card-head"><div><h2>' + esc(title) + '</h2>' +
    (sub ? '<p>' + esc(sub) + '</p>' : '') + '</div><div class="sp"></div>' + (action || '') + '</div>' + body + '</section>';
}

function kpi(label, value, sub, tone, action) {
  return '<button class="kpi ' + (tone || '') + '" data-action="' + action + '">' +
    '<span class="k-label">' + esc(label) + '</span>' +
    '<span class="k-val">' + esc(value) + '</span>' +
    '<span class="k-sub">' + esc(sub) + '</span></button>';
}

function attentionRow(item) {
  var t = item.task;
  var meta = REASON_META[item.reason] || REASON_META.stalled;
  var due = dueLabel(t);
  return '<button class="row row-btn" data-action="open-task:' + t.id + '">' +
    '<span class="grow"><span class="t1">' + esc(t.name) + '</span>' +
    '<span class="t2">' + esc(t.project_name) + ' · ' + esc(t.board || '') + ' · ' +
    (t.assignee_names.length ? esc(t.assignee_names[0]) : 'unassigned') + ' · ' + esc(due.text) + '</span></span>' +
    pill(meta.label, meta.cls) + '</button>';
}

function oldestBlockedDays(attention) {
  var ages = attention.filter(function (a) { return a.reason === 'blocked'; }).map(function (a) {
    return Math.abs(Math.round((Date.now() - new Date(a.task.blocked_since || a.task.updated_at).getTime()) / DAY));
  });
  return ages.length ? Math.max.apply(null, ages) : 0;
}

function viewPulse() {
  var d = state.data.pulse;
  if (!d) return skeleton();
  var m = d.dashboard.metrics;
  var attention = d.dashboard.attention || [];
  var b = bounds();
  var demos = (d.forecast || []).filter(function (f) { return f.demo_date; })
    .sort(function (x, y) { return x.demo_date < y.demo_date ? -1 : 1; });
  var nextDemo = demos[0];
  var atRisk = (d.forecast || []).filter(function (f) { return f.status !== 'on_track'; }).length;
  var hot = (d.teamLoad || []).filter(function (p) { return p.type === 'human' && p.load_pct >= 85; });

  var hero = attention.length
    ? '<div class="alert-strip" role="region" aria-label="Urgent items">' +
        '<div class="alert-top">' + icon('alert') + '<h2>' + attention.length + ' thing' + (attention.length === 1 ? '' : 's') + ' need you now</h2>' +
        '<span class="badge-count">' + attention.filter(function (a) { return (a.severity || 0) >= 3; }).length + '</span>' +
        '<div style="flex:1"></div><button class="link-more" data-action="go:blockers">All blockers ' + icon('chevron', 'ic-sm') + '</button></div>' +
        attention.slice(0, 4).map(function (item) {
          var t = item.task;
          var meta = REASON_META[item.reason] || REASON_META.stalled;
          var due = dueLabel(t);
          return '<button class="alert-row" data-action="open-task:' + t.id + '">' +
            '<span class="sev s' + Math.round(item.severity || 1) + '"></span>' +
            '<span class="txt"><span class="t1">' + esc(t.name) + '</span>' +
            '<span class="t2">' + esc(t.project_name) + ' · ' + esc(meta.label) +
            (t.block_reason ? ' · ' + esc(t.block_reason) : '') + ' · ' + esc(due.text) + '</span></span>' +
            pill(meta.label, meta.cls) + icon('chevron', 'ic-sm') + '</button>';
        }).join('') + '</div>'
    : '<div class="alert-strip calm" role="region" aria-label="All clear">' +
        '<div class="alert-top">' + icon('check') + '<h2>Nothing urgent. Delivery is running as planned.</h2>' +
        '<span class="badge-count">0</span></div>' +
        '<div style="font-size:12.5px;color:var(--dim)">' + m.active + ' active tasks · ' + m.done +
        ' completed in this window · next demo ' + (nextDemo ? fmtDate(nextDemo.demo_date) : 'not scheduled') + '</div></div>';

  var kpis = '<div class="kpis">' +
    kpi('Active work', m.active, m.total + ' tasks in window', '', 'go:work') +
    kpi('Blocked', m.blocked, m.blocked ? 'oldest ' + oldestBlockedDays(attention) + 'd' : 'nothing blocked', m.blocked ? 'bad' : 'good', 'go:blockers') +
    kpi('Overdue', m.overdue, m.due_today + ' due today', m.overdue ? 'bad' : 'good', 'go:blockers') +
    kpi('Completed', m.done, m.completion + '% of scope', 'good', 'go:work') +
    kpi('Demos in window', demos.filter(function (x) { return x.demo_date <= b.to; }).length,
      nextDemo ? 'next ' + fmtDate(nextDemo.demo_date) : 'none scheduled', atRisk ? 'warn' : 'good', 'go:delivery') +
    kpi('AI spend', fmtCoins(d.total.total_cxjcoins), d.budget.pct + '% of weekly budget',
      d.budget.pct > 100 ? 'bad' : d.budget.pct > 80 ? 'warn' : 'good', 'go:cost') +
    '</div>';

  var forecastList = (d.forecast || []).slice(0, 5).map(function (f) {
    var cfg = { on_track: ['success', 'On track', 'var(--success)'], at_risk: ['warning', 'At risk', 'var(--warning)'], late: ['error', 'Late', 'var(--error)'] }[f.status] || ['muted', f.status, 'var(--primary)'];
    return '<button class="row row-btn" data-action="open-board:' + f.board_id + '">' +
      '<span class="grow"><span class="t1">' + esc(f.board) + '</span>' +
      '<span class="t2">' + esc(f.project_name) + ' · ' + f.done + '/' + f.committed + ' done · ETA ' + fmtDate(f.eta_date) + '</span>' +
      bar(f.percentage, cfg[2]) + '</span>' + pill(cfg[1], cfg[0]) + icon('chevron', 'ic-sm') + '</button>';
  }).join('');

  var teamList = (d.teamLoad || []).filter(function (p) { return p.type === 'human'; })
    .sort(function (x, y) { return y.load_pct - x.load_pct; }).slice(0, 4)
    .map(function (p) {
      var color = p.load_pct >= 95 ? 'var(--error)' : p.load_pct >= 85 ? 'var(--warning)' : 'var(--success)';
      return '<div class="row">' + avatarHtml(p.id) +
        '<span class="grow"><span class="t1">' + esc(p.name) + '</span>' +
        '<span class="t2">' + esc(p.role) + ' · ' + p.active + ' active' + (p.blocked ? ' · ' + p.blocked + ' blocked' : '') + '</span>' +
        bar(p.load_pct, color) + '</span>' +
        '<span class="mono" style="font-size:11.5px;color:' + color + '">' + p.load_pct + '%</span></div>';
    }).join('');

  var activityList = (d.dashboard.activity || []).slice(0, 7).map(function (e) {
    var color = { success: 'var(--success)', primary: 'var(--primary)', warning: 'var(--warning)', error: 'var(--error)' }[e.tone] || 'var(--info)';
    return '<button class="row row-btn" data-action="open-task:' + e.target_task_id + '">' +
      '<span class="dotp" style="background:' + color + '"></span>' +
      '<span class="grow"><span class="t1">' + esc(e.actor) + ' ' + esc(e.action) + '</span>' +
      '<span class="t2">' + esc(e.target_task_name) + ' · ' + esc(e.board || '') + '</span></span>' +
      '<span class="muted" style="font-size:10.5px;white-space:nowrap">' + relTime(e.timestamp) + '</span></button>';
  }).join('');

  var series = (d.daily || []).map(function (x) { return x.total_cxjcoins; });
  var maxSeries = Math.max.apply(null, series.concat([1]));
  var costBars = '<div class="vbar" aria-hidden="true">' + series.slice(-14).map(function (v) {
    return '<i style="height:' + Math.max(4, Math.round(v / maxSeries * 100)) + '%"></i>';
  }).join('') + '</div>';

  return '<div class="stack">' + hero + kpis +
    '<div class="two-col">' +
      '<div class="stack">' +
        card('Delivering now', 'Progress against target, per board',
          forecastList || emptyCard('No boards', 'Nothing scheduled in this window.'),
          '<button class="link-more" data-action="go:delivery">Forecast ' + icon('chevron', 'ic-sm') + '</button>') +
        card('Needs attention', attention.length + ' item(s)',
          attention.slice(0, 6).map(attentionRow).join('') || emptyCard('All clear', 'No overdue, blocked or unowned work in this window.'),
          '<button class="link-more" data-action="go:blockers">See all ' + icon('chevron', 'ic-sm') + '</button>') +
      '</div>' +
      '<div class="stack">' +
        card('Team load', hot.length ? hot.length + ' above 85%' : 'Healthy',
          teamList || emptyCard('No members', 'No team members found.'),
          '<button class="link-more" data-action="go:team">Team ' + icon('chevron', 'ic-sm') + '</button>') +
        card('Activity', 'Most recent changes across projects',
          activityList || emptyCard('No activity', 'Nothing changed in this window.')) +
        card('AI spend trend', fmtCoins(d.total.total_cxjcoins) + ' in this window', costBars,
          '<button class="link-more" data-action="go:cost">Cost & AI ' + icon('chevron', 'ic-sm') + '</button>') +
      '</div>' +
    '</div></div>';
}

function viewWork() {
  var d = state.data.work;
  if (!d) return skeleton();
  var f = state.filters.work;
  var projects = (state.data.pulse && state.data.pulse.projects) || PROJECTS;

  function selectHtml(name, options, value, label) {
    return '<select class="field" data-filter="work.' + name + '" aria-label="' + esc(label) + '">' +
      options.map(function (o) {
        return '<option value="' + esc(o.id) + '"' + (String(o.id) === String(value) ? ' selected' : '') + '>' + esc(o.label) + '</option>';
      }).join('') + '</select>';
  }

  var projectOptions = [{ id: 'all', label: 'All projects' }].concat(projects.map(function (p) { return { id: p.id, label: p.name }; }));
  var boardOptions = [{ id: 'all', label: 'All boards' }].concat((d.boards || []).map(function (b) { return { id: b.id, label: b.name }; }));
  var statusOptions = [{ id: 'all', label: 'All statuses' }, { id: 'todo', label: 'To Do' }, { id: 'doing', label: 'In Progress' }, { id: 'onhold', label: 'On Hold' }, { id: 'done', label: 'Done' }];
  var priorityOptions = [{ id: 'all', label: 'All priorities' }, { id: 'high', label: 'High' }, { id: 'medium', label: 'Medium' }, { id: 'low', label: 'Low' }];
  var assigneeOptions = [{ id: 'all', label: 'Anyone' }].concat(PEOPLE.map(function (p) { return { id: p.id, label: p.name }; }));

  var toolbar = '<div class="toolbar">' +
    '<div class="search">' + icon('search') +
    '<input class="field" type="search" placeholder="Search tasks…" value="' + esc(f.q) + '" data-filter="work.q" aria-label="Search tasks" /></div>' +
    selectHtml('project', projectOptions, f.project, 'Project') +
    selectHtml('board', boardOptions, f.board, 'Board') +
    selectHtml('status', statusOptions, f.status, 'Status') +
    selectHtml('priority', priorityOptions, f.priority, 'Priority') +
    selectHtml('assignee', assigneeOptions, f.assignee, 'Assignee') +
    '<button class="btn sm ghost" data-action="clear-work-filters">' + icon('filter', 'ic-sm') + 'Clear</button></div>';

  function th(field, label) {
    var active = f.sort === field;
    var arrow = active ? ' <span style="color:var(--primary)">' + (f.dir === 'asc' ? '▲' : '▼') + '</span>' : '';
    return '<th class="sortable" data-action="sort:' + field + '">' + label + arrow + '</th>';
  }

  var rows = (d.tasks || []).map(function (t) {
    var due = dueLabel(t);
    return '<tr data-action="open-task:' + t.id + '" tabindex="0" role="button">' +
      '<td><div style="font-weight:600;font-size:12.5px">' + esc(t.name) + '</div>' +
      '<div style="font-size:11px;color:var(--muted)">' + (t.blocked ? '⛔ ' + esc(t.block_reason) : esc((t.tags || []).join(' · ') || '—')) + '</div></td>' +
      '<td>' + projectChip(t.project_id) + '</td>' +
      '<td class="dim" style="font-size:11.5px">' + esc(t.board || '—') + '</td>' +
      '<td>' + statusPill(t.status) + '</td>' +
      '<td>' + priorityPill(t.priority) + '</td>' +
      '<td>' + assigneeStack(t) + '</td>' +
      '<td style="font-size:11.5px;color:' + (due.cls === 'error' ? 'var(--error)' : due.cls === 'warning' ? 'var(--warning)' : 'var(--dim)') + '">' + esc(due.text) + '</td>' +
      '<td style="min-width:88px"><div style="display:flex;align-items:center;gap:6px">' +
      bar(t.progress, t.progress === 100 ? 'var(--success)' : 'var(--primary)') +
      '<span class="mono" style="font-size:10.5px;color:var(--muted)">' + t.progress + '%</span></div></td>' +
      '<td class="dim" style="font-size:11px;white-space:nowrap">' + relTime(t.updated_at) + '</td></tr>';
  }).join('');

  var cards = (d.tasks || []).map(function (t) {
    var due = dueLabel(t);
    return '<button class="task-card" data-action="open-task:' + t.id + '">' +
      '<span class="tc-top"><span class="tc-title">' + esc(t.name) + '</span>' + priorityPill(t.priority) + '</span>' +
      '<span class="tc-meta">' + statusPill(t.status) + projectChip(t.project_id) +
      '<span style="font-size:11px;color:' + (due.cls === 'error' ? 'var(--error)' : 'var(--muted)') + '">' + icon('clock', 'ic-sm') + ' ' + esc(due.text) + '</span>' +
      assigneeStack(t) + '</span>' +
      (t.blocked ? '<span class="tc-meta">' + pill('⛔ ' + t.block_reason, 'error') + '</span>' : '') + '</button>';
  }).join('');

  var start = d.total ? (d.page - 1) * d.page_size + 1 : 0;
  var end = Math.min(d.total, d.page * d.page_size);
  var pages = [];
  for (var p = 1; p <= d.total_pages; p += 1) {
    if (d.total_pages > 7 && p > 2 && p < d.total_pages - 1 && Math.abs(p - d.page) > 1) {
      if (pages[pages.length - 1] !== '…') pages.push('…');
      continue;
    }
    pages.push(p);
  }

  var pager = '<div class="pager"><div class="filters-note">' +
    (d.total ? 'Showing <strong style="color:var(--text)">' + start + '–' + end + '</strong> of ' + d.total : 'No results') +
    '</div><div class="pages">' +
    '<button class="page-btn" data-action="page:' + (d.page - 1) + '"' + (d.has_prev ? '' : ' disabled') + ' aria-label="Previous page">‹</button>' +
    pages.map(function (n) {
      if (n === '…') return '<span class="muted" style="padding:0 2px">…</span>';
      return '<button class="page-btn' + (n === d.page ? ' active' : '') + '" data-action="page:' + n + '">' + n + '</button>';
    }).join('') +
    '<button class="page-btn" data-action="page:' + (d.page + 1) + '"' + (d.has_next ? '' : ' disabled') + ' aria-label="Next page">›</button>' +
    '</div></div>';

  var body = !d.total
    ? emptyCard('No tasks match these filters', 'Widen the time range, pick another project, or clear the filters.', 'Clear filters', 'clear-work-filters')
    : '<div class="table-wrap"><table><thead><tr>' +
        th('name', 'Task') + '<th>Project</th><th>Board</th><th>Status</th><th>Priority</th><th>Owner</th>' +
        th('due_date', 'Due') + '<th>Progress</th>' + th('updated_at', 'Updated') +
      '</tr></thead><tbody>' + rows + '</tbody></table></div>' +
      '<div class="cards-list">' + cards + '</div>' + pager;

  return '<div class="stack">' +
    '<section class="card"><div class="card-head"><div><h2>All work in the window</h2>' +
      '<p>' + d.total + ' tasks across every project</p></div><div class="sp"></div>' +
      '<button class="btn sm" data-action="go:blockers">' + icon('alert', 'ic-sm') + 'Blockers</button></div>' +
      toolbar + '</section>' +
    '<section class="card pad0" style="padding:6px 12px 12px">' + body + '</section></div>';
}

function viewBlockers() {
  var d = state.data.blockers;
  if (!d) return skeleton();
  var f = state.filters.blockers;
  var all = (d.dashboard && d.dashboard.attention) || [];
  var items = all;
  if (f.reason !== 'all') items = items.filter(function (i) { return i.reason === f.reason; });
  if (f.project !== 'all') items = items.filter(function (i) { return i.task.project_id === f.project; });

  var counts = {};
  all.forEach(function (i) { counts[i.reason] = (counts[i.reason] || 0) + 1; });

  var chips = ['all'].concat(Object.keys(REASON_META)).map(function (key) {
    var label = key === 'all' ? 'All (' + all.length + ')' : REASON_META[key].label + ' (' + (counts[key] || 0) + ')';
    return '<button class="chip' + (f.reason === key ? ' active' : '') + '" data-action="block-filter:' + key + '">' + esc(label) + '</button>';
  }).join('');

  var projectSelect = '<select class="field" data-filter="blockers.project" aria-label="Project">' +
    '<option value="all">All projects</option>' +
    PROJECTS.map(function (p) { return '<option value="' + p.id + '"' + (f.project === p.id ? ' selected' : '') + '>' + esc(p.name) + '</option>'; }).join('') +
    '</select>';

  var list = items.map(function (item) {
    var t = item.task;
    var meta = REASON_META[item.reason] || REASON_META.stalled;
    var days = t.blocked_since
      ? Math.abs(Math.round((Date.now() - new Date(t.blocked_since).getTime()) / DAY))
      : Math.abs(t.days_until_due || 0);
    var severityColor = (item.reason === 'blocked' || item.reason === 'overdue') ? 'rgba(240,82,82,.28)' : 'var(--line)';
    return '<article class="card" style="border-color:' + severityColor + '">' +
      '<div style="display:flex;gap:10px;align-items:flex-start">' +
        '<span class="sev s' + Math.round(item.severity || 1) + '" style="margin-top:7px"></span>' +
        '<div style="flex:1;min-width:0">' +
          '<button data-action="open-task:' + t.id + '" style="text-align:left;font-size:14px;font-weight:650;line-height:1.35">' + esc(t.name) + '</button>' +
          '<div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:7px;align-items:center">' +
            pill(meta.label, meta.cls) + statusPill(t.status) + priorityPill(t.priority) + projectChip(t.project_id) +
            '<span style="font-size:11px;color:var(--muted)">' + esc(t.board || '') + '</span></div>' +
          (t.block_reason ? '<div style="margin-top:8px;font-size:12px;color:#ffb4b4;background:rgba(240,82,82,.08);border:1px solid rgba(240,82,82,.22);border-radius:8px;padding:7px 9px">⛔ ' + esc(t.block_reason) + '</div>' : '') +
          '<div style="display:flex;flex-wrap:wrap;gap:10px;margin-top:9px;font-size:11.5px;color:var(--muted)">' +
            '<span>' + (t.assignee_names.length ? esc(t.assignee_names.join(', ')) : '<strong style="color:var(--warning)">unassigned</strong>') + '</span>' +
            '<span>· ' + (item.reason === 'blocked' ? 'blocked ' + days + 'd'
              : item.reason === 'overdue' ? days + 'd overdue'
              : item.reason === 'stalled' ? 'no update ' + days + 'd'
              : 'due ' + fmtDate(t.due_date)) + '</span>' +
            '<span>· updated ' + relTime(t.updated_at) + '</span></div>' +
          '<div class="toolbar" style="margin-top:11px">' +
            '<button class="btn sm" data-action="open-task:' + t.id + '">Open</button>' +
            '<button class="btn sm ghost" data-action="ask-update:' + t.id + '">' + icon('sparkles', 'ic-sm') + 'Ask for update</button>' +
            '<button class="btn sm ghost" data-action="reassign:' + t.id + '">' + icon('user', 'ic-sm') + 'Reassign</button>' +
            (t.blocked ? '<button class="btn sm danger" data-action="unblock:' + t.id + '">Unblock</button>' : '') +
          '</div></div></div></article>';
  }).join('');

  return '<div class="stack">' +
    '<section class="card"><div class="card-head"><div><h2>Attention queue</h2>' +
      '<p>Blocked, overdue, due today, stalled or unowned work — most severe first</p></div>' +
      '<div class="sp"></div>' + projectSelect + '</div>' +
      '<div class="toolbar">' + chips + '</div></section>' +
    (items.length ? '<div class="stack">' + list + '</div>'
      : '<section class="card">' + emptyCard('Nothing here', 'No items match this filter.', 'Show all', 'block-filter:all') + '</section>') +
    '</div>';
}

function metaBox(label, value) {
  return '<div><div style="font-size:10px;text-transform:uppercase;letter-spacing:.05em;color:var(--muted)">' + esc(label) + '</div>' +
    '<div style="font-size:12.5px;font-weight:650">' + esc(value) + '</div></div>';
}

function viewDelivery() {
  var d = state.data.delivery;
  if (!d) return skeleton();
  var selected = state.filters.delivery.board;
  var bd = d.burndown;

  var cards = (d.forecast || []).map(function (f) {
    var cfg = { on_track: ['success', 'On track', 'var(--success)'], at_risk: ['warning', 'At risk', 'var(--warning)'], late: ['error', 'Late', 'var(--error)'] }[f.status] || ['muted', f.status, 'var(--primary)'];
    return '<article class="card">' +
      '<div style="display:flex;gap:8px;align-items:flex-start"><div style="flex:1;min-width:0">' +
        '<div style="font-size:13.5px;font-weight:700">' + esc(f.board) + '</div>' +
        '<div style="font-size:11.5px;color:var(--muted)">' + projectChip(f.project_id) + ' · ' + esc(f.type) + '</div></div>' +
        pill(cfg[1], cfg[0]) + '</div>' +
      '<div style="margin:12px 0 6px">' + bar(f.percentage, cfg[2]) + '</div>' +
      '<div style="display:flex;justify-content:space-between;font-size:11.5px;color:var(--dim)">' +
        '<span>' + f.done + '/' + f.committed + ' done</span><span class="mono">' + f.percentage + '%</span></div>' +
      '<div class="grid" style="grid-template-columns:1fr 1fr;gap:8px;margin-top:12px">' +
        metaBox('ETA', fmtDate(f.eta_date)) + metaBox('Target', fmtDate(f.target_date)) +
        metaBox('Velocity', f.velocity + ' / wk') + metaBox('Confidence', f.confidence) + '</div>' +
      '<div style="margin-top:10px;font-size:11.5px;color:' + (f.blocked ? 'var(--error)' : 'var(--muted)') + '">' +
        (f.blocked ? '⛔ ' + f.blocked + ' blocked task(s) drag the forecast' : 'Remaining: ' + f.remaining + ' task(s), no blockers') + '</div>' +
      (f.demo_date ? '<div style="margin-top:8px">' + pill('Demo ' + fmtDate(f.demo_date), 'primary') + '</div>' : '') +
      '</article>';
  }).join('');

  var boardSelect = '<select class="field" data-filter="delivery.board" aria-label="Board">' +
    (d.forecast || []).map(function (f) {
      return '<option value="' + f.board_id + '"' + (selected === f.board_id ? ' selected' : '') + '>' + esc(f.board) + '</option>';
    }).join('') + '</select>';

  var burndownBlock = bd
    ? chartBurndown(bd.points) +
      '<div class="legend" style="margin-top:8px">' +
      '<span class="legend"><i style="background:rgba(255,255,255,.35)"></i><span style="font-size:11px;color:var(--dim)">Ideal</span></span>' +
      '<span class="legend"><i style="background:var(--primary)"></i><span style="font-size:11px;color:var(--dim)">Actual remaining</span></span>' +
      '</div>'
    : '<div class="sk" style="height:170px"></div>';

  var milestoneRows = (d.forecast || []).filter(function (f) { return f.demo_date; })
    .sort(function (a, b) { return a.demo_date < b.demo_date ? -1 : 1; })
    .map(function (f) {
      var cfg = { on_track: ['success', 'On track'], at_risk: ['warning', 'At risk'], late: ['error', 'Late'] }[f.status] || ['muted', f.status];
      return '<tr data-action="open-board:' + f.board_id + '" tabindex="0" role="button">' +
        '<td style="font-weight:600">' + esc(f.board) + '</td>' +
        '<td>' + projectChip(f.project_id) + '</td>' +
        '<td class="dim">' + fmtDate(f.demo_date) + '</td>' +
        '<td>' + f.done + '/' + f.committed + '</td>' +
        '<td style="min-width:90px">' + bar(f.percentage, 'var(--primary)') + '</td>' +
        '<td class="dim">' + fmtDate(f.eta_date) + '</td>' +
        '<td>' + pill(cfg[1], cfg[0]) + '</td></tr>';
    }).join('');

  var demoDates = (d.forecast || []).filter(function (f) { return f.demo_date; })
    .map(function (f) { return f.demo_date; }).sort();

  return '<div class="stack">' +
    '<div class="kpis">' +
      kpi('Boards tracked', (d.forecast || []).length, 'across ' + PROJECTS.length + ' projects', '', 'go:work') +
      kpi('At risk', (d.forecast || []).filter(function (f) { return f.status !== 'on_track'; }).length, 'behind target or blocked', 'warn', 'go:blockers') +
      kpi('Next demo', demoDates.length ? fmtDate(demoDates[0]) : '—', 'management walkthrough', '', 'go:delivery') +
    '</div>' +
    '<section class="card"><div class="card-head"><div><h2>Forecast per board</h2>' +
      '<p>Velocity is measured inside the selected window — the dates below are based on it</p></div></div>' +
      '<div class="three-col">' + (cards || emptyCard('No boards', 'Nothing scheduled in this window.')) + '</div></section>' +
    '<div class="two-col">' +
      '<section class="card"><div class="card-head"><div><h2>Burndown</h2>' +
        '<p>' + esc(bd ? bd.board + ' · last 14 days · ' + bd.total + ' tasks' : '') + '</p></div>' +
        '<div class="sp"></div>' + boardSelect + '</div>' + burndownBlock + '</section>' +
      card('Milestones & demos', 'What management will see, and when',
        '<div class="table-wrap"><table><thead><tr><th>Sprint</th><th>Project</th><th>Demo</th><th>Done</th><th>Progress</th><th>ETA</th><th>Status</th></tr></thead><tbody>' +
        (milestoneRows || '<tr><td colspan="7" style="text-align:center;color:var(--muted);padding:22px">No demos scheduled</td></tr>') +
        '</tbody></table></div>') +
    '</div></div>';
}

function statTile(value, label, color) {
  return '<div style="background:var(--surface-2);border-radius:8px;padding:6px 2px">' +
    '<div class="mono" style="font-size:14px;font-weight:700;color:' + (color || 'var(--text)') + '">' + value + '</div>' +
    '<div style="font-size:9.5px;color:var(--muted);text-transform:uppercase;letter-spacing:.05em">' + esc(label) + '</div></div>';
}

function viewTeam() {
  var d = state.data.team;
  if (!d) return skeleton();
  var f = state.filters.team;
  var members = d.teamLoad || [];
  if (f.type !== 'all') members = members.filter(function (p) { return p.type === f.type; });
  if (f.project !== 'all') members = members.filter(function (p) { return p.project_ids.indexOf(f.project) >= 0; });
  if (f.hot) members = members.filter(function (p) { return p.load_pct >= 85; });
  members = members.slice().sort(function (a, b) { return b.load_pct - a.load_pct; });

  var humans = (d.teamLoad || []).filter(function (p) { return p.type === 'human'; });
  var totalLoad = humans.length ? Math.round(humans.reduce(function (s, p) { return s + p.load_pct; }, 0) / humans.length) : 0;
  var overloaded = humans.filter(function (p) { return p.load_pct >= 85; }).length;
  var agents = (d.teamLoad || []).filter(function (p) { return p.type === 'agent'; });

  var cards = members.map(function (p) {
    var color = p.load_pct >= 95 ? 'var(--error)' : p.load_pct >= 85 ? 'var(--warning)' : 'var(--success)';
    return '<button class="card" style="text-align:left" data-action="open-member:' + p.id + '">' +
      '<div style="display:flex;gap:10px;align-items:center">' + avatarHtml(p.id) +
      '<div style="flex:1;min-width:0"><div style="font-size:13.5px;font-weight:700">' + esc(p.name) + '</div>' +
      '<div style="font-size:11.5px;color:var(--muted)">' + esc(p.role) + (p.type === 'agent' ? ' · AI' : '') + '</div></div>' +
      '<span class="mono" style="font-size:12px;font-weight:700;color:' + color + '">' + p.load_pct + '%</span></div>' +
      '<div style="margin:11px 0 9px">' + bar(p.load_pct, color) + '</div>' +
      '<div class="grid" style="grid-template-columns:repeat(3,1fr);gap:6px;font-size:11px;text-align:center">' +
      statTile(p.active, 'active') + statTile(p.blocked, 'blocked', p.blocked ? 'var(--error)' : null) +
      statTile(p.done, 'done', 'var(--success)') + '</div>' +
      '<div style="margin-top:9px;font-size:11px;color:var(--muted)">' +
      (p.type === 'human' ? esc(p.hours + 'h / ' + p.capacity_h + 'h allocated') : 'agent · ' + p.active + ' tasks') +
      ' · ' + fmtCoins(p.cost) + '</div></button>';
  }).join('');

  var typeSelect = '<select class="field" data-filter="team.type" aria-label="Member type">' +
    ['all', 'human', 'agent'].map(function (t) {
      return '<option value="' + t + '"' + (f.type === t ? ' selected' : '') + '>' +
        (t === 'all' ? 'Everyone' : t === 'human' ? 'Humans' : 'AI agents') + '</option>';
    }).join('') + '</select>';

  var projectSelect = '<select class="field" data-filter="team.project" aria-label="Project">' +
    '<option value="all">All projects</option>' +
    PROJECTS.map(function (p) { return '<option value="' + p.id + '"' + (f.project === p.id ? ' selected' : '') + '>' + esc(p.name) + '</option>'; }).join('') +
    '</select>';

  return '<div class="stack">' +
    '<section class="card"><div class="card-head"><div><h2>Capacity</h2>' +
      '<p>Average human load ' + totalLoad + '% · ' + overloaded + ' member(s) above 85% · ' + agents.length +
      ' AI agents in the roster</p></div><div class="sp"></div></div>' +
      '<div class="toolbar">' + typeSelect + projectSelect +
      '<button class="btn sm' + (f.hot ? ' primary' : ' ghost') + '" data-action="team-hot">' + icon('warn', 'ic-sm') + 'Overloaded only</button>' +
      '<button class="btn sm ghost" data-action="team-clear">Clear</button></div></section>' +
    (members.length
      ? '<div class="grid" style="grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:12px">' + cards + '</div>'
      : '<section class="card">' + emptyCard('No members match', 'Widen the filters to see the roster.', 'Clear filters', 'team-clear') + '</section>') +
    '</div>';
}

function viewCost() {
  var d = state.data.cost;
  if (!d) return skeleton();
  var f = state.filters.cost;
  var b = bounds();

  var projectSelect = '<select class="field" data-filter="cost.project" aria-label="Project">' +
    '<option value="all">All projects</option>' +
    PROJECTS.map(function (p) { return '<option value="' + p.id + '"' + (f.project === p.id ? ' selected' : '') + '>' + esc(p.name) + '</option>'; }).join('') +
    '</select>';

  var modelSelect = '<select class="field" data-filter="cost.model" aria-label="Model">' +
    '<option value="all">All models</option>' +
    MODELS.map(function (m) { return '<option value="' + esc(m.name) + '"' + (f.model === m.name ? ' selected' : '') + '>' + esc(m.name) + '</option>'; }).join('') +
    '</select>';

  var daily = d.daily || [];
  var labels = daily.map(function (x) { return fmtDate(x.period); });
  var series = [];
  if (f.series.cost) series.push({ color: 'var(--primary)', values: daily.map(function (x) { return x.total_cxjcoins; }) });
  if (f.series.tokens) series.push({ color: 'var(--info)', values: daily.map(function (x) { return x.total_tokens; }) });
  if (f.series.calls) series.push({ color: 'var(--success)', values: daily.map(function (x) { return x.calls; }) });

  var legend = [['cost', 'Spend (cx)', 'var(--primary)'], ['tokens', 'Tokens', 'var(--info)'], ['calls', 'Calls', 'var(--success)']]
    .map(function (row) {
      return '<button data-action="toggle-series:' + row[0] + '" class="' + (f.series[row[0]] ? '' : 'off') + '">' +
        '<i style="background:' + row[2] + '"></i>' + row[1] + '</button>';
    }).join('');

  var chart = series.length
    ? chartLines({ labels: labels, series: series, height: 200, aria: 'AI consumption over the window' })
    : '<div class="empty">' + icon('coins') + '<h3>No series selected</h3><p>Turn one back on from the legend.</p></div>';

  var byProject = Object.keys(d.byProject || {}).map(function (name) {
    var p = null;
    for (var i = 0; i < PROJECTS.length; i += 1) if (PROJECTS[i].name === name) p = PROJECTS[i];
    return { name: name, m: d.byProject[name], color: p ? p.color : 'var(--primary)' };
  }).sort(function (a, c) { return c.m.total_cxjcoins - a.m.total_cxjcoins; });
  var maxProject = Math.max.apply(null, byProject.map(function (p) { return p.m.total_cxjcoins; }).concat([1]));

  var projectRows = byProject.map(function (p) {
    return '<div class="row"><span style="width:8px;height:8px;border-radius:2px;background:' + p.color + '"></span>' +
      '<span class="grow"><span class="t1">' + esc(p.name) + '</span>' +
      bar(p.m.total_cxjcoins / maxProject * 100, p.color) + '</span>' +
      '<span class="mono" style="font-size:11.5px">' + fmtCoins(p.m.total_cxjcoins) + '</span></div>';
  }).join('');

  var modelRows = Object.keys(d.byModel || {}).map(function (name) {
    var m = d.byModel[name];
    return '<tr><td style="font-weight:600">' + esc(name) + '</td>' +
      '<td class="num">' + fmtNum(m.calls) + '</td>' +
      '<td class="num">' + fmtTokens(m.total_tokens) + '</td>' +
      '<td class="num">' + fmtTokens(m.input_tokens) + '</td>' +
      '<td class="num">' + fmtTokens(m.output_tokens) + '</td>' +
      '<td class="num" style="color:var(--primary)">' + fmtCoins(m.total_cxjcoins) + '</td></tr>';
  }).join('');

  var userRows = Object.keys(d.byUser || {}).map(function (id) {
    var person = personById(id);
    return { id: id, name: person ? person.name : id, m: d.byUser[id] };
  }).sort(function (a, c) { return c.m.total_cxjcoins - a.m.total_cxjcoins; });
  var maxUser = Math.max.apply(null, userRows.map(function (u) { return u.m.total_cxjcoins; }).concat([1]));

  var userList = userRows.slice(0, 8).map(function (u) {
    return '<div class="row">' + avatarHtml(u.id) +
      '<span class="grow"><span class="t1">' + esc(u.name) + '</span>' +
      '<span class="t2">' + fmtNum(u.m.calls) + ' calls · ' + fmtTokens(u.m.total_tokens) + ' tokens</span>' +
      bar(u.m.total_cxjcoins / maxUser * 100, 'var(--secondary)') + '</span>' +
      '<span class="mono" style="font-size:11.5px">' + fmtCoins(u.m.total_cxjcoins) + '</span></div>';
  }).join('');

  var budgetRows = (d.budget.per_project || []).map(function (p) {
    var color = p.pct > 100 ? 'var(--error)' : p.pct > 80 ? 'var(--warning)' : 'var(--success)';
    return '<div class="row"><span class="grow"><span class="t1">' + esc(p.project_name) + '</span>' +
      bar(p.pct, color) + '</span>' +
      '<span class="mono" style="font-size:11.5px;color:' + color + '">' + fmtCoins(p.spent) + ' / ' + fmtCoins(p.budget) + '</span></div>';
  }).join('');

  return '<div class="stack">' +
    '<div class="kpis">' +
      kpi('AI spend', fmtCoins(d.total.total_cxjcoins), 'over ' + daily.length + ' days', 'warn', 'go:cost') +
      kpi('Tokens', fmtTokens(d.total.total_tokens), fmtNum(d.total.calls) + ' calls', '', 'go:cost') +
      kpi('Cost / task', d.total.cost_per_delivered_task != null ? fmtCoins(d.total.cost_per_delivered_task) : '—', d.total.delivered_tasks + ' tasks delivered', '', 'go:work') +
      kpi('Weekly budget', fmtCoins(d.budget.weekly_budget), d.budget.pct + '% used (projected)', d.budget.pct > 100 ? 'bad' : d.budget.pct > 80 ? 'warn' : 'good', 'go:cost') +
      kpi('Projected week', fmtCoins(d.budget.projected), d.budget.projected > d.budget.weekly_budget ? 'over budget' : 'within budget', d.budget.projected > d.budget.weekly_budget ? 'bad' : 'good', 'go:cost') +
      kpi('Avg / call', d.total.calls ? fmtCoins(d.total.total_cxjcoins / d.total.calls) : '—', 'per LLM call', '', 'go:cost') +
    '</div>' +
    '<section class="card"><div class="card-head"><div><h2>Consumption over time</h2>' +
