  el.innerHTML = (VIEWS[state.route] || viewPulse)();
}

function findTask(id) {
  var pools = ['pulse', 'work', 'blockers'];
  for (var k = 0; k < pools.length; k += 1) {
    var data = state.data[pools[k]];
    if (!data) continue;
    if (data.tasks) {
      for (var i = 0; i < data.tasks.length; i += 1) if (data.tasks[i].id === id) return data.tasks[i];
    }
    if (data.dashboard && data.dashboard.attention) {
      for (var j = 0; j < data.dashboard.attention.length; j += 1) {
        if (data.dashboard.attention[j].task.id === id) return data.dashboard.attention[j].task;
      }
    }
  }
  for (var n = 0; n < DB.tasks.length; n += 1) if (DB.tasks[n].id === id) return toPlanningTask(DB.tasks[n]);
  return null;
}

