function toast(message, tone) {
  var host = document.getElementById('toasts');
  var el = document.createElement('div');
  el.className = 'toast ' + (tone || 'info');
  el.innerHTML = icon(tone === 'error' ? 'alert' : tone === 'success' ? 'check' : 'sparkles') + '<span>' + esc(message) + '</span>';
  host.appendChild(el);
  setTimeout(function () { if (el.parentNode) el.parentNode.removeChild(el); }, 2600);
}

/* ═══════════════════════════════════════════════════════════════════════════
   10. ACTIONS
   ═══════════════════════════════════════════════════════════════════════════ */

function go(routeId) {
  if (!routeMeta(routeId)) return;
  state.route = routeId;
  state.ui.nav = false;
  state.ui.menu = false;
  renderShell();
  loadRoute(routeId);
}

function setFilter(path, value) {
  var parts = path.split('.');
  var scope = state.filters[parts[0]];
  if (!scope) return;
  scope[parts[1]] = value;
  if (scope.page !== undefined) scope.page = 1;
}

function patchTask(id, body, message) {
  return api('/api/planning/tasks/' + encodeURIComponent(id), { method: 'PATCH', body: body })
    .then(function (res) {
      invalidateCache();
      return res;
    })
    .then(function () {
      if (message) toast(message, 'success');
      return loadRoute(state.route);
    })
    .then(function () {
      renderOverlay();
    })['catch'](function (error) {
      toast((error && error.message) || 'Update failed', 'error');
    });
}

var searchTimer = null;

function handleAction(action, el) {
  if (!action) return;

  if (action.indexOf('go:') === 0) { go(action.slice(3)); return; }

  if (action.indexOf('range:') === 0) {
    state.range = action.slice(6);
    invalidateCache();
    renderShell();
    loadRoute(state.route);
    return;
  }

  if (action === 'open-nav') { state.ui.nav = true; renderShell(); return; }
  if (action === 'close-nav') { state.ui.nav = false; renderShell(); return; }
  if (action === 'toggle-menu') { state.ui.menu = !state.ui.menu; renderShell(); return; }

  if (action === 'dev:error') {
    DEV.error = !DEV.error;
    invalidateCache();
    state.ui.menu = false;
    renderShell();
    loadRoute(state.route);
    return;
  }
  if (action === 'dev:empty') {
    DEV.empty = !DEV.empty;
    invalidateCache();
    state.ui.menu = false;
    renderShell();
    loadRoute(state.route);
    return;
  }
  if (action === 'reset-mock') {
    DB.tasks = TASKS.map(function (t) { return Object.assign({}, t); });
    safeSet(STORE_KEY + '.patches', '{}');
    safeSet(STORE_KEY, '{}');
    state.assistant.messages = [];
    invalidateCache();
    state.ui.menu = false;
    renderShell();
    loadRoute(state.route);
    toast('Mock data reset', 'success');
    return;
  }

  if (action === 'retry') { loadRoute(state.route); return; }

  if (action === 'open-assistant') { state.ui.assistant = true; renderAssistant(); return; }
  if (action === 'close-assistant') { state.ui.assistant = false; renderAssistant(); return; }
  if (action === 'assistant-ask') { askAssistant(el.getAttribute('data-q') || ''); return; }

  if (action.indexOf('open-task:') === 0) {
    state.ui.drawer = { type: 'task', id: action.slice(10) };
    state.ui.modal = null;
    renderOverlay();
    return;
  }
  if (action.indexOf('open-member:') === 0) {
    state.ui.drawer = { type: 'member', id: action.slice(12) };
    state.ui.modal = null;
    renderOverlay();
    return;
  }
  if (action.indexOf('open-board:') === 0) {
    state.filters.delivery.board = action.slice(11);
    go('delivery');
    return;
  }
  if (action === 'close-overlay') { state.ui.drawer = null; state.ui.modal = null; renderOverlay(); return; }

  if (action.indexOf('sort:') === 0) {
    var field = action.slice(5);
    if (state.filters.work.sort === field) {
      state.filters.work.dir = state.filters.work.dir === 'asc' ? 'desc' : 'asc';
    } else {
      state.filters.work.sort = field;
      state.filters.work.dir = 'asc';
    }
    state.filters.work.page = 1;
    loadRoute('work');
    return;
  }
  if (action.indexOf('page:') === 0) {
    state.filters.work.page = Math.max(1, Number(action.slice(5)) || 1);
    loadRoute('work');
    return;
  }
  if (action === 'clear-work-filters') {
    state.filters.work = { project: 'all', board: 'all', status: 'all', priority: 'all', assignee: 'all', q: '', sort: 'priority', dir: 'asc', page: 1, page_size: 12 };
    loadRoute('work');
    return;
  }
  if (action.indexOf('block-filter:') === 0) {
    state.filters.blockers.reason = action.slice(13);
    renderView();
    return;
  }
  if (action === 'team-hot') {
    state.filters.team.hot = !state.filters.team.hot;
    renderView();
    return;
  }
  if (action === 'team-clear') {
    state.filters.team = { type: 'all', project: 'all', hot: false };
    renderView();
    return;
  }
  if (action.indexOf('toggle-series:') === 0) {
    var key = action.slice(14);
    state.filters.cost.series[key] = !state.filters.cost.series[key];
    renderView();
    return;
  }
  if (action.indexOf('reassign:') === 0) {
    state.ui.modal = { type: 'reassign', taskId: action.slice(9) };
    renderOverlay();
    return;
  }
  if (action.indexOf('assign:') === 0) {
    var rest = action.slice(7).split(':');
    state.ui.modal = null;
    patchTask(rest[0], { assignees: [rest[1]] }, 'Task assigned');
    return;
  }
  if (action.indexOf('mark-done:') === 0) {
    patchTask(action.slice(10), { status: 'done', progress: 100 }, 'Marked as done');
    return;
  }
  if (action.indexOf('unblock:') === 0) {
    patchTask(action.slice(8), { blocked: false }, 'Unblocked');
    return;
  }
  if (action.indexOf('ask-update:') === 0) {
    var task = findTask(action.slice(11));
    state.ui.assistant = true;
    renderAssistant();
    askAssistant('What is blocking ' + (task ? task.name : 'this task') + '?');
    return;
  }
}

function askAssistant(question) {
  if (!question) return;
  var b = bounds();
  state.ui.assistant = true;
  state.ui.thinking = true;
  state.assistant.messages.push({ role: 'user', text: question });
  renderAssistant();
  api('/api/assistant/ask', { method: 'POST', body: { question: question, from: b.from, to: b.to } })
    .then(function (answer) {
      state.ui.thinking = false;
      state.assistant.messages.push({ role: 'bot', answer: answer.answer, sources: answer.sources || [] });
      state.assistant.messages = state.assistant.messages.slice(-12);
      renderAssistant();
      saveState();
    })['catch'](function (error) {
      state.ui.thinking = false;
      state.assistant.messages.push({ role: 'bot', answer: 'I could not answer: ' + ((error && error.message) || 'unknown error') });
      renderAssistant();
    });
}

