/**
 * ============================================================================
 * Management dashboard API module — cross-project view for management.
 * ----------------------------------------------------------------------------
 * The screen answers one question: "what is happening, what is stuck and when
 * will it be delivered" across EVERY project, for a time window.
 *
 * WHICH ENDPOINTS ARE REAL
 * ------------------------
 * Only the project list exists today:
 *   GET /api/projects?with_metrics=0            → [{ project_id, project_name }]
 *
 * Everything else is MOCKED HERE, behind the same async contract a backend
 * would expose, so replacing it later is a one-line change per method:
 *   GET   /api/management/overview?from&to      → overview()
 *   POST  /api/management/tasks/query           → tasks()
 *   GET   /api/management/blockers?from&to      → blockers()
 *   GET   /api/management/delivery?from&to&board_id → delivery()
 *   GET   /api/management/team-load?from&to     → team()
 *   GET   /api/management/cost?from&to&project_id&model → cost()
 *   PATCH /api/management/tasks/{id}            → updateTask()
 *   POST  /api/management/assistant             → ask()
 *
 * The mock store is DETERMINISTIC (seeded PRNG + fixed roster), so the numbers
 * are stable between reloads and only move when the time window moves. It is
 * built once per project list and kept in memory; `updateTask` writes into it,
 * which is why the dashboard reacts immediately to a status/due-date change.
 *
 * REAL PROJECT NAMES, MOCK WORK
 * -----------------------------
 * Boards, tasks, people and AI usage are generated for the projects the API
 * actually reports, so the screen always speaks about the real projects of the
 * installation instead of hard-coded demo names.
 * ============================================================================
 */

const DAY = 86400000

/* ── Dates ────────────────────────────────────────────────────────────────── */

function isoDate(value) {
  return new Date(value).toISOString().slice(0, 10)
}

function todayISO() {
  return isoDate(Date.now())
}

/** ISO date `days` from today (negative = past). */
function dayOffset(days) {
  const date = new Date()
  date.setHours(12, 0, 0, 0)
  date.setDate(date.getDate() + days)
  return isoDate(date)
}

/** ISO timestamp `daysAgo` in the past (negative = future). */
function stampAgo(daysAgo, hour = 11) {
  const date = new Date()
  date.setDate(date.getDate() - daysAgo)
  date.setHours(hour, 20, 0, 0)
  return date.toISOString()
}

/** Days between today and an ISO date (negative = late). */
function daysUntil(iso) {
  if (!iso) return null
  return Math.round((new Date(`${iso}T00:00:00`) - new Date(`${todayISO()}T00:00:00`)) / DAY)
}

/* ── Deterministic pseudo-randomness ─────────────────────────────────────── */

function mulberry32(seed) {
  let state = seed >>> 0
  return function random() {
    state = (state + 0x6d2b79f5) >>> 0
    let t = state
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

/* ── Seeds ────────────────────────────────────────────────────────────────── */

const FALLBACK_PROJECTS = [
  { id: 'p1', name: 'codx-junior', color: '#e2419f' },
  { id: 'p2', name: 'Atlas Payments', color: '#38bdf8' },
  { id: 'p3', name: 'Mobile App', color: '#22c55e' },
  { id: 'p4', name: 'Docs Site', color: '#f59e0b' }
]

const PROJECT_PALETTE = ['#e2419f', '#38bdf8', '#22c55e', '#f59e0b', '#a855f7', '#14b8a6', '#f05252', '#6366f1']

/** Fixed roster: the "team" the dashboard reports on (humans + AI agents). */
const ROSTER = [
  { name: 'Marina Costa', role: 'Project Manager', type: 'human', capacity: 40 },
  { name: 'Diego Ferrer', role: 'Frontend', type: 'human', capacity: 40 },
  { name: 'Aya Nakamura', role: 'Backend', type: 'human', capacity: 40 },
  { name: 'Tobias Lang', role: 'Integrations', type: 'human', capacity: 40 },
  { name: 'Priya Raman', role: 'QA', type: 'human', capacity: 32 },
  { name: 'Sam Okafor', role: 'Design', type: 'human', capacity: 32 },
  { name: 'Lena Vogt', role: 'Data', type: 'human', capacity: 40 },
  { name: 'Marc Dubois', role: 'DevOps', type: 'human', capacity: 24 },
  { name: 'agent-coder', role: 'AI Agent', type: 'agent', capacity: null },
  { name: 'agent-reviewer', role: 'AI Agent', type: 'agent', capacity: null }
]

const BLOCK_REASONS = [
  'Waiting for the vendor sandbox credentials (ticket PSP-2291)',
  'Blocked by the compliance review',
  'Needs a reproduction on customer hardware',
  'Waiting on the API contract from the partner team',
  'Depends on the migration window approved by ops',
  'Specification not signed off yet'
]

const WORK_NAMES = [
  'API contract for the delivery view',
  'Aggregate work status across projects',
  'Time filter persistence per section',
  'Webhook retry with backoff',
  'Board progress aggregation',
  'Cost per delivered task metric',
  'Mobile-first navigation rail',
  'Sprint burndown endpoint',
  'Assignment rules for unowned work',
  'Sandbox refund flow',
  'Idempotency on capture',
  '3-D Secure challenge screen',
  'Notification permission flow',
  'Offline cache for task lists',
  'Accessibility pass on the drawer',
  'Analytics series toggles',
  'Demo script for the next increment',
  'Release notes automation',
  'Team capacity calculation',
  'Deploy preview for the walkthrough',
  'Knowledge index thread pool',
  'Chat streaming reconnect',
  'Docs page for the dashboard',
  'Changelog for the increment'
]

const MODEL_CATALOG = [
  { name: 'gpt-4o-mini', inputRate: 0.15, outputRate: 0.6 },
  { name: 'claude-sonnet-4.5', inputRate: 3, outputRate: 15 },
  { name: 'qwen2.5-coder-32b', inputRate: 0.2, outputRate: 0.8 }
]

const WEEKLY_BUDGET = 6000

/** How bad each attention reason is (drives the ordering, higher = worse). */
export const SEVERITY = {
  blocked: 4,
  overdue: 3,
  due_today: 2,
  unassigned_high: 1.5,
  stalled: 1
}

/* ── Mock store ───────────────────────────────────────────────────────────── */

let store = null
let storeSignature = ''

function buildStore(projects) {
  const random = mulberry32(20260517)
  const people = ROSTER.map((person, index) => ({
    ...person,
    id: `${person.type === 'agent' ? 'a' : 'u'}${index + 1}`
  }))

  const boards = []
  const tasks = []
  let sequence = 0

  projects.forEach((project, projectIndex) => {
    const code = (project.name || 'PRJ').replace(/[^a-zA-Z]/g, '').slice(0, 3).toUpperCase() || 'PRJ'
    const projectBoards = [
      {
        id: `${project.id}-delivery`,
        name: `${code} · Delivery`,
        project_id: project.id,
        type: 'kanban',
        target_date: dayOffset(14 + (projectIndex % 3) * 7),
        demo_date: null
      },
      {
        id: `${project.id}-sprint`,
        name: `${code} · Sprint`,
        project_id: project.id,
        type: 'sprint',
        target_date: dayOffset(6 + (projectIndex % 4) * 3),
        demo_date: dayOffset(6 + (projectIndex % 4) * 3)
      }
    ]

    projectBoards.forEach((board, boardIndex) => {
      boards.push(board)
      const count = 5 + ((projectIndex + boardIndex) % 4)

      for (let index = 0; index < count; index += 1) {
        sequence += 1
        const roll = random()
        const status = roll < 0.32 ? 'done' : roll < 0.64 ? 'doing' : roll < 0.84 ? 'todo' : 'onhold'
        const priorityRoll = random()
        const priority = priorityRoll < 0.32 ? 'high' : priorityRoll < 0.78 ? 'medium' : 'low'
        const blocked = status !== 'done' && random() < 0.17
        const stale = status !== 'done' && random() < 0.15
        const unassigned = status !== 'done' && random() < 0.13
        const dueOffset = [-5, -2, -1, 0, 1, 2, 3, 5, 7, 9, 12][(sequence * 3) % 11]
        const humans = people.filter(person => person.type === 'human')
        const assignee = humans[(sequence * 5) % humans.length]
        const agent = people.find(person => person.type === 'agent' && random() < 0.5)

        tasks.push({
          id: `t${String(sequence).padStart(3, '0')}`,
          name: WORK_NAMES[(sequence * 7) % WORK_NAMES.length],
          project_id: project.id,
          board_id: board.id,
          status,
          priority,
          due_date: dayOffset(dueOffset),
          progress: status === 'done' ? 100 : status === 'onhold' ? 35 : status === 'doing' ? 45 + Math.round(random() * 40) : 0,
          assignees: unassigned ? [] : [agent && priority !== 'high' ? agent.id : assignee.id],
          estimate_h: [2, 4, 6, 8, 12, 16][(sequence * 2) % 6],
          tags: board.type === 'sprint' ? ['sprint'] : ['delivery'],
          created_at: stampAgo(18 + (sequence % 6)),
          updated_at: stale ? stampAgo(9 + (sequence % 6)) : stampAgo(sequence % 3, 8 + (sequence % 9)),
          blocked,
          block_reason: blocked ? BLOCK_REASONS[sequence % BLOCK_REASONS.length] : null,
          blocked_since: blocked ? stampAgo(2 + (sequence % 6)) : null
        })
      }
    })
  })

  // AI usage: 90 days × project × model, with a stable shape.
  const usage = []
  for (let back = 89; back >= 0; back -= 1) {
    const date = dayOffset(-back)
    projects.forEach((project) => {
      MODEL_CATALOG.forEach((model) => {
        if (random() > 0.62) return
        const humans = people.filter(person => person.type === 'human')
        const owner = humans[Math.floor(random() * humans.length)]
        const weight = model.name === 'claude-sonnet-4.5' ? 0.45 : 1
        const inputTokens = Math.round((18000 + random() * 240000) * weight)
        const outputTokens = Math.round((4000 + random() * 54000) * weight)
        const calls = Math.max(2, Math.round((8 + random() * 90) * weight))
        usage.push({
          iso_date: date,
          project_id: project.id,
          model: model.name,
          username: owner.id,
          input_tokens: inputTokens,
          output_tokens: outputTokens,
          total_tokens: inputTokens + outputTokens,
          calls,
          total_duration_seconds: Math.round(calls * (2 + random() * 9) * 10) / 10,
          total_cxjcoins: Math.round((inputTokens / 1000 * model.inputRate + outputTokens / 1000 * model.outputRate) * 100) / 100
        })
      })
    })
  }

  return { projects, people, boards, tasks, usage }
}

function ensureStore(projects) {
  const signature = projects.map(project => `${project.id}:${project.name}`).join('|')
  if (!store || signature !== storeSignature) {
    store = buildStore(projects)
    storeSignature = signature
  }
  return store
}

/** Drops the in-memory mock (used by the "reset mock" action of the view). */
export function resetManagementMock() {
  store = null
  storeSignature = ''
  projectsCache = null
}

/* ── Projects ─────────────────────────────────────────────────────────────── */

let projectsCache = null

async function resolveProjects(API) {
  if (projectsCache) return projectsCache

  try {
    const response = await API.get('/api/projects?with_metrics=0', { key: 'management:projects', ttl: 60000 })
    const list = Array.isArray(response) ? response : (response?.projects || [])
    const projects = list
      .map((project, index) => ({
        id: project.project_id || project.id,
        name: project.project_name || project.name,
        color: project.project_color || project.color || PROJECT_PALETTE[index % PROJECT_PALETTE.length]
      }))
      .filter(project => project.id && project.name)

    projectsCache = projects.length ? projects : FALLBACK_PROJECTS
  } catch (error) {
    // No backend (or a forbidden call): the dashboard still renders with the
    // demo project list instead of an empty screen.
    projectsCache = FALLBACK_PROJECTS
  }

  return projectsCache
}

/* ── Helpers over the store ───────────────────────────────────────────────── */

function projectById(id) {
  return store.projects.find(project => project.id === id) || null
}

function boardById(id) {
  return store.boards.find(board => board.id === id) || null
}

function personById(id) {
  return store.people.find(person => person.id === id) || null
}

function normalizeRange(query = {}) {
  const to = String(query.to || todayISO()).slice(0, 10)
  const from = String(query.from || dayOffset(-7)).slice(0, 10)
  return { from, to }
}

function inRange(iso, range) {
  if (!iso) return false
  const date = String(iso).slice(0, 10)
  return date >= range.from && date <= range.to
}

/**
 * Tasks "in the window": updated inside it PLUS every unfinished task.
 * A blocker must never disappear because it stopped moving.
 */
function windowTasks(range, projectIds) {
  const projects = Array.isArray(projectIds) && projectIds.length ? projectIds : null
  return store.tasks.filter((task) => {
    if (projects && !projects.includes(task.project_id)) return false
    return inRange(task.updated_at, range) || task.status !== 'done'
  })
}

function attentionReason(task) {
  if (task.blocked) return 'blocked'
  const left = daysUntil(task.due_date)
  if (task.status !== 'done') {
    if (left !== null && left < 0) return 'overdue'
    if (left === 0) return 'due_today'
    if (task.priority === 'high' && !task.assignees.length) return 'unassigned_high'
  }
  const stale = Math.round((Date.now() - new Date(task.updated_at).getTime()) / DAY)
  if (stale >= 7 && task.status !== 'done') return 'stalled'
  return null
}

/** Raw store task → shape consumed by the view. */
function decorate(task) {
