    board_type: board ? board.type : null,
    assignee_names: task.assignees.map(id => personById(id)?.name || id),
    assignees_info: task.assignees.map((id) => {
      const person = personById(id)
      return person
        ? { id, name: person.name, role: person.role, type: person.type }
        : { id, name: id, role: '', type: 'human' }
    }),
    days_until_due: left,
    overdue: reason === 'overdue',
    due_today: reason === 'due_today',
    unassigned: !task.assignees.length,
    attention_reason: reason
  }
}

function computeMetrics(tasks) {
  const byStatus = { todo: 0, doing: 0, onhold: 0, done: 0 }
  const byPriority = { high: 0, medium: 0, low: 0 }
  let overdue = 0
  let dueToday = 0
  let unassigned = 0
  let blocked = 0

  tasks.forEach((task) => {
    byStatus[task.status] = (byStatus[task.status] || 0) + 1
    byPriority[task.priority] = (byPriority[task.priority] || 0) + 1
    if (task.status !== 'done') {
      const left = daysUntil(task.due_date)
      if (left !== null && left < 0) overdue += 1
      if (left === 0) dueToday += 1
      if (!task.assignees.length) unassigned += 1
    }
    if (task.blocked) blocked += 1
  })

  const done = byStatus.done || 0
  return {
    total: tasks.length,
    done,
    active: (byStatus.doing || 0) + (byStatus.todo || 0),
    on_hold: byStatus.onhold || 0,
    overdue,
    due_today: dueToday,
    unassigned,
    blocked,
    completion: tasks.length ? Math.round((done / tasks.length) * 100) : 0,
    by_status: byStatus,
    by_priority: byPriority
  }
}

function boardProgress(tasks) {
  return store.boards
    .map((board) => {
      const rows = tasks.filter(task => task.board_id === board.id)
      if (!rows.length) return null
      const done = rows.filter(task => task.status === 'done').length
      const project = projectById(board.project_id)
      return {
        board_id: board.id,
        board: board.name,
        project_id: board.project_id,
        project_name: project ? project.name : null,
        project_color: project ? project.color : null,
        type: board.type,
        total: rows.length,
        done,
        doing: rows.filter(task => task.status === 'doing').length,
        todo: rows.filter(task => task.status === 'todo').length,
        on_hold: rows.filter(task => task.status === 'onhold').length,
        blocked: rows.filter(task => task.blocked).length,
        percentage: Math.round((done / rows.length) * 100),
        target_date: board.target_date,
        demo_date: board.demo_date
      }
    })
    .filter(Boolean)
}

function activityFeed(tasks) {
  return tasks
    .slice()
    .sort((a, b) => (a.updated_at < b.updated_at ? 1 : -1))
    .slice(0, 24)
    .map((task) => {
      const owner = task.assignees.length ? personById(task.assignees[0]) : null
      let action = 'updated'
      let tone = 'info'
      if (task.status === 'done') {
        action = 'completed'
        tone = 'success'
      } else if (task.status === 'doing') {
        action = 'moved to In progress'
        tone = 'primary'
      } else if (task.status === 'onhold') {
        action = 'put on hold'
        tone = 'warning'
      }
      if (task.blocked) {
        action = 'flagged as blocked'
        tone = 'error'
      }
      return {
        id: `${task.id}-${task.updated_at}`,
        actor: owner ? owner.name : 'Unassigned',
        actor_type: owner ? owner.type : 'human',
        action,
        tone,
        task_id: task.id,
        task_name: task.name,
        board: boardById(task.board_id)?.name || null,
        project_id: task.project_id,
        project_name: projectById(task.project_id)?.name || null,
        timestamp: task.updated_at
      }
    })
}

/* ── Payloads ─────────────────────────────────────────────────────────────── */

function dashboardPayload(range, projectIds) {
  const tasks = windowTasks(range, projectIds).map(decorate)
  const attention = tasks
    .filter(task => task.attention_reason)
    .sort((a, b) => (SEVERITY[b.attention_reason] || 0) - (SEVERITY[a.attention_reason] || 0))
    .map(task => ({ task, reason: task.attention_reason, severity: SEVERITY[task.attention_reason] || 0 }))

  return {
    range,
    metrics: computeMetrics(tasks),
    board_progress: boardProgress(tasks),
    attention,
    activity: activityFeed(tasks),
    generated_at: new Date().toISOString()
  }
}

function forecastPayload(range) {
  const tasks = windowTasks(range, null)
  return boardProgress(tasks).map((board) => {
    const doneInWindow = tasks.filter(
      task => task.board_id === board.board_id && task.status === 'done' && inRange(task.updated_at, range)
    ).length
    // The selected window is the velocity baseline (tasks closed per week).
    const velocity = Math.round(Math.max(doneInWindow, 0.6) * 10) / 10
    const remaining = board.total - board.done
    const etaDays = Math.max(0, Math.round((remaining / Math.max(velocity, 0.5)) * 7))
    const targetLeft = daysUntil(board.target_date)

    let status = 'on_track'
    let confidence = 'high'
    if (board.blocked > 0) {
      status = 'at_risk'
      confidence = 'low'
    }
    if (targetLeft !== null && etaDays > targetLeft) {
      status = targetLeft < 0 ? 'late' : 'at_risk'
      confidence = targetLeft < 0 ? 'low' : 'medium'
    }

    return {
      ...board,
      committed: board.total,
      remaining,
      velocity,
      eta_date: dayOffset(etaDays),
      eta_days: etaDays,
      confidence,
      status
    }
  })
}

function burndownPayload(boardId) {
  const board = boardById(boardId) || store.boards[0]
  const rows = store.tasks.filter(task => task.board_id === board.id)
  const total = rows.length
  const days = 14
  const completed = rows.filter(task => task.status === 'done').length
  const points = []

  for (let index = 0; index < days; index += 1) {
    const ratio = index / (days - 1)
    const doneByNow = Math.round(completed * Math.pow(ratio, 0.85))
    points.push({
      date: dayOffset(-(days - 1 - index)),
      ideal: Math.max(0, Math.round(total - (total / (days - 1)) * index)),
      actual: Math.max(0, total - doneByNow)
    })
  }

  return { board_id: board.id, board: board.name, total, points }
}

function teamPayload(range) {
  const tasks = windowTasks(range, null).map(decorate)

  return store.people.map((person) => {
    const mine = tasks.filter(task => task.assignees.includes(person.id))
    const active = mine.filter(task => task.status === 'doing' || task.status === 'todo')
    const hours = active.reduce((sum, task) => sum + task.estimate_h, 0)
    const usage = store.usage.filter(row => row.username === person.id && inRange(row.iso_date, range))
    const cost = usage.reduce((sum, row) => sum + row.total_cxjcoins, 0)

    return {
      id: person.id,
      name: person.name,
      role: person.role,
      type: person.type,
      capacity_h: person.capacity,
      hours,
      load_pct: person.capacity ? Math.round((hours / person.capacity) * 100) : Math.min(100, active.length * 12),
      active: active.length,
      blocked: mine.filter(task => task.blocked).length,
      done: mine.filter(task => task.status === 'done').length,
      overdue: mine.filter(task => task.attention_reason === 'overdue').length,
      cost_cxjcoins: Math.round(cost * 10) / 10,
      project_ids: [...new Set(mine.map(task => task.project_id))],
      last_active: mine.length
        ? mine.slice().sort((a, b) => (a.updated_at < b.updated_at ? 1 : -1))[0].updated_at
        : null
    }
  })
}

function emptyMetrics() {
  return {
    input_tokens: 0,
    output_tokens: 0,
    total_tokens: 0,
    calls: 0,
    total_duration_seconds: 0,
    total_cxjcoins: 0
  }
}

function sumUsage(rows) {
  const total = emptyMetrics()
  rows.forEach((row) => {
    total.input_tokens += row.input_tokens
    total.output_tokens += row.output_tokens
    total.total_tokens += row.total_tokens
    total.calls += row.calls
    total.total_duration_seconds += row.total_duration_seconds
    total.total_cxjcoins += row.total_cxjcoins
  })
  total.total_duration_seconds = Math.round(total.total_duration_seconds * 10) / 10
  total.total_cxjcoins = Math.round(total.total_cxjcoins * 100) / 100
  return total
}

function usageRows(range, projectId, model) {
  return store.usage.filter((row) => {
    if (!inRange(row.iso_date, range)) return false
    if (projectId && row.project_id !== projectId) return false
    if (model && row.model !== model) return false
    return true
  })
}

function costPayload(range, projectId, model) {
  const rows = usageRows(range, projectId, model)
  const total = sumUsage(rows)

  const delivered = windowTasks(range, projectId ? [projectId] : null)
    .filter(task => task.status === 'done' && inRange(task.updated_at, range)).length
  total.delivered_tasks = delivered
  total.cost_per_delivered_task = delivered ? Math.round((total.total_cxjcoins / delivered) * 100) / 100 : null

  // Daily series
  const buckets = new Map()
  rows.forEach((row) => {
    const bucket = buckets.get(row.iso_date) || {
      period: row.iso_date,
      input_tokens: 0,
      output_tokens: 0,
      total_tokens: 0,
      calls: 0,
      total_cxjcoins: 0
    }
    bucket.input_tokens += row.input_tokens
    bucket.output_tokens += row.output_tokens
    bucket.total_tokens += row.total_tokens
    bucket.calls += row.calls
    bucket.total_cxjcoins += row.total_cxjcoins
    buckets.set(row.iso_date, bucket)
  })
  const daily = [...buckets.values()]
    .sort((a, b) => (a.period < b.period ? -1 : 1))
    .map(bucket => ({ ...bucket, total_cxjcoins: Math.round(bucket.total_cxjcoins * 100) / 100 }))

  // Groupings
  function groupBy(keySelector) {
    const groups = new Map()
    rows.forEach((row) => {
      const key = keySelector(row)
      if (!groups.has(key)) groups.set(key, [])
      groups.get(key).push(row)
    })
    return Object.fromEntries([...groups.entries()].map(([key, value]) => [key, sumUsage(value)]))
  }

  const by_project = groupBy(row => projectById(row.project_id)?.name || row.project_id)
  const by_model = groupBy(row => row.model)
  const by_user = groupBy(row => personById(row.username)?.name || row.username)

  // Budget: weekly envelope split evenly across the projects.
  const days = Math.max(1, Math.round((new Date(range.to) - new Date(range.from)) / DAY) + 1)
  const projected = Math.round((total.total_cxjcoins / days) * 7)
  const perProjectShare = Math.round(WEEKLY_BUDGET / Math.max(1, store.projects.length))

  const per_project = store.projects.map((project) => {
    const spent = sumUsage(usageRows(range, project.id, null)).total_cxjcoins
    return {
      project_id: project.id,
      project_name: project.name,
      color: project.color,
      budget: perProjectShare,
      spent: Math.round(spent * 100) / 100,
      pct: perProjectShare ? Math.round((spent / perProjectShare) * 100) : 0
    }
  })

  return {
    total,
    daily,
    by_project,
    by_model,
    by_user,
    budget: {
      weekly_budget: WEEKLY_BUDGET,
      spent: total.total_cxjcoins,
      projected,
      remaining: Math.round((WEEKLY_BUDGET - projected) * 100) / 100,
      pct: Math.round((projected / WEEKLY_BUDGET) * 100),
      per_project
    },
    models: MODEL_CATALOG.map(model => model.name),
    generated_at: new Date().toISOString()
  }
}

/* ── Assistant ────────────────────────────────────────────────────────────── */

function fmtCoins(value) {
  const number = Number(value) || 0
  if (number >= 1000000) return `${(number / 1000000).toFixed(2)}M cx`
  if (number >= 1000) return `${(number / 1000).toFixed(1)}K cx`
  return `${Math.round(number * 10) / 10} cx`
}

function fmtNum(value) {
  const number = Number(value) || 0
  if (number >= 1000000) return `${(number / 1000000).toFixed(1)}M`
  if (number >= 1000) return `${(number / 1000).toFixed(1)}K`
  return String(number)
}

function fmtDate(iso) {
  if (!iso) return '—'
  return new Date(`${String(iso).slice(0, 10)}T12:00:00`).toLocaleDateString(undefined, {
    month: 'short',
    day: 'numeric'
  })
}

function answerFor(question, range) {
  const text = String(question || '').toLowerCase()
  const tasks = windowTasks(range, null).map(decorate)
  const attention = tasks
    .filter(task => task.attention_reason)
    .sort((a, b) => (SEVERITY[b.attention_reason] || 0) - (SEVERITY[a.attention_reason] || 0))
  const usage = sumUsage(usageRows(range, null, null))

  const label = task => `${task.name} — ${task.project_name} · ${task.assignee_names[0] || 'unassigned'}`
  const age = iso => Math.abs(Math.round((Date.now() - new Date(iso).getTime()) / DAY))

  if (/block|stuck|stopp|stall|risk/.test(text)) {
    const blocked = attention.filter(task => task.attention_reason === 'blocked')
    if (!blocked.length) {
      return {
        answer: `Nothing is blocked in this window. ${attention.length} task(s) still need attention (overdue, due today or unowned).`,
        sources: [{ section: 'blockers', label: 'Blockers' }]
      }
    }
    return {
      answer: `${blocked.length} task(s) are blocked:\n${blocked
        .slice(0, 5)
        .map(task => `• ${label(task)} — blocked ${age(task.blocked_since)}d: ${task.block_reason}`)
        .join('\n')}\n\nThe oldest blocker is ${age(blocked[0].blocked_since)} days old: that is the one to escalate today.`,
      sources: [{ section: 'blockers', label: 'Blockers' }]
    }
  }

  if (/cost|spend|budget|token|model|consum|money/.test(text)) {
    const cost = costPayload(range, null, null)
    const top = Object.entries(cost.by_project).sort((a, b) => b[1].total_cxjcoins - a[1].total_cxjcoins)[0]
    return {
      answer:
        `In this window the platform burned ${fmtCoins(cost.total.total_cxjcoins)} over ${fmtNum(cost.total.calls)} calls ` +
        `(${fmtNum(cost.total.total_tokens)} tokens).\n` +
        `• Biggest project: ${top ? `${top[0]} with ${fmtCoins(top[1].total_cxjcoins)}` : 'n/a'}\n` +
        `• Projected week: ${fmtCoins(cost.budget.projected)} against a ${fmtCoins(cost.budget.weekly_budget)} budget (${cost.budget.pct}%)\n` +
        `• Cost per delivered task: ${cost.total.cost_per_delivered_task !== null ? fmtCoins(cost.total.cost_per_delivered_task) : 'n/a'}`,
      sources: [{ section: 'cost', label: 'Cost & AI' }]
    }
  }

  if (/who|team|load|capacity|overload|busy/.test(text)) {
    const humans = teamPayload(range)
      .filter(person => person.type === 'human')
      .sort((a, b) => b.load_pct - a.load_pct)
    const hot = humans.filter(person => person.load_pct >= 85)
    return {
      answer:
        `${hot.length ? `${hot.length} people are above 85% load.` : 'Nobody is above 85% load.'}\n` +
        humans
          .slice(0, 4)
          .map(person => `• ${person.name} (${person.role}) — ${person.load_pct}% load · ${person.active} active · ${person.blocked} blocked`)
          .join('\n'),
      sources: [{ section: 'team', label: 'Team' }]
    }
  }

  if (/ship|deliver|forecast|when|eta|demo|next week/.test(text)) {
    const forecast = forecastPayload(range)
    const demos = forecast.filter(board => board.demo_date).sort((a, b) => (a.demo_date < b.demo_date ? -1 : 1))
    const risk = forecast.filter(board => board.status !== 'on_track')
    return {
      answer:
        `Next demos:\n${demos
          .map(board => `• ${board.board} — demo ${fmtDate(board.demo_date)} · ${board.done}/${board.committed} done · ${board.status.replace('_', ' ')}`)
          .join('\n') || '• none scheduled'}\n` +
        (risk.length
          ? `${risk.length} board(s) at risk: ${risk.map(board => board.board).join(', ')}.`
          : 'All boards are on track.'),
      sources: [{ section: 'delivery', label: 'Delivery' }]
    }
  }

  if (/overdue|late|behind/.test(text)) {
    const late = attention.filter(task => task.attention_reason === 'overdue')
    if (!late.length) {
      return { answer: 'Nothing is overdue in this window.', sources: [{ section: 'blockers', label: 'Blockers' }] }
    }
    return {
      answer: `${late.length} overdue task(s):\n${late
        .slice(0, 6)
        .map(task => `• ${label(task)} — ${Math.abs(task.days_until_due)}d late`)
        .join('\n')}`,
      sources: [{ section: 'blockers', label: 'Blockers' }]
    }
  }

  if (/done|finish|completed|delivered|this week/.test(text)) {
    const done = tasks.filter(task => task.status === 'done')
    return {
      answer:
        `${done.length} task(s) completed in this window:\n` +
        (done.slice(0, 6).map(task => `• ${label(task)}`).join('\n') || '• nothing yet'),
      sources: [{ section: 'work', label: 'Work' }]
    }
  }

  const metrics = computeMetrics(windowTasks(range, null))
  return {
    answer:
      `State of play for this window:\n` +
      `• ${metrics.active} active, ${metrics.blocked} blocked, ${metrics.overdue} overdue\n` +
      `• ${metrics.done} completed (${metrics.completion}% of everything in scope)\n` +
      `• AI spend ${fmtCoins(usage.total_cxjcoins)}\n\n` +
      `Ask me about blockers, costs, team load, what ships next, or what we finished.`,
    sources: [{ section: 'pulse', label: 'Pulse' }]
  }
}

/* ── Module ───────────────────────────────────────────────────────────────── */

export const managementModule = (API) => ({
  /**
   * Everything the Pulse section draws, in one round trip.
   * @param {{from?: string, to?: string}} query ISO range (default: last 7 days).
   */
  async overview(query = {}) {
    const range = normalizeRange(query)
    const projects = await resolveProjects(API)
    ensureStore(projects)

    return {
      range,
      projects: store.projects,
      dashboard: dashboardPayload(range, null),
      forecast: forecastPayload(range),
      teamLoad: teamPayload(range),
      cost: costPayload(range, null, null)
    }
  },

  /**
   * Paginated, filtered task list across every project (the Work section).
   * @param {Object} body `{ from, to, project_id, board_id, statuses,
   *        priorities, assignees, search, sort, page, page_size }`
   */
  async tasks(body = {}) {
    const range = normalizeRange(body)
    const projects = await resolveProjects(API)
    ensureStore(projects)

    let rows = windowTasks(range, body.project_id ? [body.project_id] : null)

    if (body.board_id) rows = rows.filter(task => task.board_id === body.board_id)
    if (Array.isArray(body.statuses) && body.statuses.length) {
      rows = rows.filter(task => body.statuses.includes(task.status))
    }
    if (Array.isArray(body.priorities) && body.priorities.length) {
      rows = rows.filter(task => body.priorities.includes(task.priority))
    }
    if (Array.isArray(body.assignees) && body.assignees.length) {
      rows = rows.filter(task => task.assignees.some(id => body.assignees.includes(id)))
    }
    if (body.search) {
      const needle = String(body.search).toLowerCase()
      rows = rows.filter(task => `${task.name} ${(task.tags || []).join(' ')}`.toLowerCase().includes(needle))
    }

    const decorated = rows.map(decorate)
    const sort = body.sort || { field: 'priority', dir: 'asc' }
    const priorityWeight = { high: 0, medium: 1, low: 2 }
    const compare = {
      priority: (a, b) => (priorityWeight[a.priority] ?? 2) - (priorityWeight[b.priority] ?? 2),
      due_date: (a, b) => String(a.due_date || '9999').localeCompare(String(b.due_date || '9999')),
      status: (a, b) => String(a.status).localeCompare(String(b.status)),
      name: (a, b) => a.name.localeCompare(b.name),
      project: (a, b) => String(a.project_name).localeCompare(String(b.project_name)),
      updated_at: (a, b) => String(a.updated_at).localeCompare(String(b.updated_at))
    }[sort.field] || (() => 0)

    decorated.sort((a, b) => (sort.dir === 'desc' ? -compare(a, b) : compare(a, b)))

    const pageSize = Math.max(1, Number(body.page_size) || 12)
    const total = decorated.length
    const totalPages = Math.max(1, Math.ceil(total / pageSize))
    const page = Math.min(Math.max(1, Number(body.page) || 1), totalPages)

    return {
      tasks: decorated.slice((page - 1) * pageSize, page * pageSize),
      total,
      page,
      page_size: pageSize,
      total_pages: totalPages,
      has_next: page < totalPages,
      has_prev: page > 1,
      boards: store.boards.map(board => ({
        id: board.id,
        name: board.name,
        project_id: board.project_id,
        type: board.type
      })),
      projects: store.projects,
      people: store.people.map(person => ({ id: person.id, name: person.name, role: person.role, type: person.type })),
      generated_at: new Date().toISOString()
    }
  },

  /** Attention queue (blocked / overdue / due today / unowned / stalled). */
  async blockers(query = {}) {
    const range = normalizeRange(query)
    const projects = await resolveProjects(API)
    ensureStore(projects)
    const dashboard = dashboardPayload(range, query.project_id ? [query.project_id] : null)
    return { range, dashboard, projects: store.projects }
  },

  /** Forecast + burndown of one board (the Delivery section). */
  async delivery(query = {}) {
    const range = normalizeRange(query)
    const projects = await resolveProjects(API)
    ensureStore(projects)
    return {
      range,
      forecast: forecastPayload(range),
      burndown: burndownPayload(query.board_id),
      projects: store.projects
    }
  },

  /** Capacity, workload and cost per team member (humans + AI agents). */
  async team(query = {}) {
    const range = normalizeRange(query)
    const projects = await resolveProjects(API)
    ensureStore(projects)
    return {
      range,
      teamLoad: teamPayload(range),
      tasks: windowTasks(range, null).map(decorate),
      projects: store.projects
    }
  },

  /** Spend, tokens, models and budget (the Cost & AI section). */
  async cost(query = {}) {
    const range = normalizeRange(query)
    const projects = await resolveProjects(API)
    ensureStore(projects)
    return {
      range,
      ...costPayload(range, query.project_id || null, query.model || null),
      projects: store.projects,
      people: store.people.map(person => ({ id: person.id, name: person.name, type: person.type }))
    }
  },

  /**
   * Writes a task change into the mock store and returns the updated task.
   * @param {string} id Task id.
   * @param {{status?: string, priority?: string, due_date?: string|null,
   *          progress?: number, assignees?: string[], blocked?: boolean}} patch
   */
  async updateTask(id, patch = {}) {
    const task = store.tasks.find(row => row.id === id)
    if (!task) {
      throw new Error(`Task ${id} not found`)
    }

    if ('status' in patch) task.status = patch.status
    if ('priority' in patch) task.priority = patch.priority
    if ('due_date' in patch) task.due_date = patch.due_date || null
    if ('progress' in patch) task.progress = Math.max(0, Math.min(100, Number(patch.progress) || 0))
    if ('assignees' in patch) task.assignees = patch.assignees || []
    if ('blocked' in patch) {
      task.blocked = !!patch.blocked
      task.block_reason = patch.blocked ? (patch.block_reason || task.block_reason || 'Blocked') : null
      task.blocked_since = patch.blocked ? new Date().toISOString() : null
    }
    if (task.status === 'done') task.progress = 100
    task.updated_at = new Date().toISOString()

    return decorate(task)
  },

  /**
   * Rule-based answer computed from the SAME mock data the screen renders.
   * @param {{question: string, from?: string, to?: string}} body
   */
  async ask(body = {}) {
    const range = normalizeRange(body)
    const projects = await resolveProjects(API)
    ensureStore(projects)
    return { ...answerFor(body.question, range), range }
  },

  /** Drops the generated mock so the next call rebuilds it. */
  reset() {
    resetManagementMock()
  }
})

export default managementModule

/**
 * ============================================================================
 * Management dashboard — view state, filters and derived aggregations.
 * ----------------------------------------------------------------------------
 * One reactive object (`d`) is shared by the shell and by every section
 * component, so the sections stay presentational and there is a single source
 * of truth for the time range, the filters and the loaded payloads.
 *
 * WHY `reactive({...})` AND NOT `{ ...computedRefs }`
 * ------------------------------------------------
 * `reactive()` unwraps the refs/computeds it contains, so a template can write
 * `d.metrics.blocked` instead of `d.metrics.value.blocked` — and the value stays
 * reactive. Passing one object down also keeps the child props to a single
 * `d`, which is what makes the six sections independent of each other.
 *
 * LOADING MODEL
 * -------------
 * Sections load lazily and independently: opening "Cost" never waits for
 * "Team". Changing the time range invalidates every section EXCEPT the one on
 * screen, so the operator sees the new numbers immediately and the rest reload
 * when they are visited (no stale window ever rendered).
 * ============================================================================
 */
import { computed, reactive } from 'vue'
import { API } from '@/api/api'
import { managementModule } from '@/api/modules/management'

/* ── Constants ────────────────────────────────────────────────────────────── */

/** Time windows of the header. `days` drives every request. */
export const RANGES = [
  { id: 'today', label: 'Today', days: 0 },
  { id: 'week', label: '7d', days: 7 },
  { id: 'month', label: '30d', days: 30 },
  { id: 'quarter', label: '90d', days: 90 }
]

/** Left rail entries: one section = one question management asks. */
export const SECTIONS = [
  { id: 'pulse', label: 'Pulse', icon: 'fa-solid fa-heart-pulse', title: 'Pulse', subtitle: 'What needs you now, across every project' },
  { id: 'work', label: 'Work', icon: 'fa-solid fa-list-check', title: 'Work', subtitle: 'Every task, filtered and drillable' },
  { id: 'blockers', label: 'Blockers', icon: 'fa-solid fa-circle-exclamation', title: 'Blockers', subtitle: 'Stoppers, overdue work and unowned tasks' },
  { id: 'delivery', label: 'Delivery', icon: 'fa-solid fa-rocket', title: 'Delivery', subtitle: 'Forecast, velocity and demo dates' },
  { id: 'team', label: 'Team', icon: 'fa-solid fa-people-group', title: 'Team', subtitle: 'Capacity, workload and AI agents' },
  { id: 'cost', label: 'Cost & AI', icon: 'fa-solid fa-coins', title: 'Cost & AI', subtitle: 'Spend, tokens, models and budget' }
]

export const STATUS_META = {
  todo: { label: 'To Do', badge: 'badge-ghost' },
  doing: { label: 'In Progress', badge: 'badge-info' },
  onhold: { label: 'On Hold', badge: 'badge-warning' },
  done: { label: 'Done', badge: 'badge-success' }
}

export const PRIORITY_META = {
  high: { label: 'High', badge: 'badge-error' },
  medium: { label: 'Medium', badge: 'badge-warning' },
  low: { label: 'Low', badge: 'badge-success' }
}

export const REASON_META = {
  blocked: { label: 'Blocked', badge: 'badge-error' },
  overdue: { label: 'Overdue', badge: 'badge-error' },
  due_today: { label: 'Due today', badge: 'badge-warning' },
  unassigned_high: { label: 'Unassigned', badge: 'badge-warning' },
  stalled: { label: 'Stalled', badge: 'badge-ghost' }
}

/** Default filters of every section (also used by "clear"). */
export function defaultFilters() {
  return {
    work: { project_id: '', board_id: '', status: '', priority: '', assignee: '', search: '', sort: 'priority', dir: 'asc', page: 1, page_size: 12 },
    blockers: { reason: 'all', project_id: '' },
    delivery: { board_id: '' },
    team: { type: 'all', project_id: '', onlyHot: false },
    cost: { project_id: '', model: '', series: { cost: true, tokens: false, calls: true } }
  }
}

const STORE_KEY = 'codx.management.dashboard'

/* ── Date helpers ─────────────────────────────────────────────────────────── */

export function todayISO() {
  return new Date().toISOString().slice(0, 10)
}

export function dayOffset(days) {
  const date = new Date()
  date.setDate(date.getDate() + days)
  return date.toISOString().slice(0, 10)
}

/* ── Module client ────────────────────────────────────────────────────────── */

let client = null

function api() {
  if (!client) client = managementModule(API)
  return client
}

/* ── Small pure helpers used by the templates ─────────────────────────────── */

export function fmtNum(value) {
  const number = Number(value) || 0
  if (Math.abs(number) >= 1000000) return `${(number / 1000000).toFixed(1)}M`
  if (Math.abs(number) >= 1000) return `${(number / 1000).toFixed(1)}K`
  return String(Math.round(number * 10) / 10)
}

export function fmtCoins(value) {
  if (value === null || value === undefined) return '—'
  const number = Number(value) || 0
  if (Math.abs(number) >= 1000000) return `${(number / 1000000).toFixed(2)}M cx`
  if (Math.abs(number) >= 1000) return `${(number / 1000).toFixed(1)}K cx`
  return `${Math.round(number * 10) / 10} cx`
}

export function fmtDate(value) {
  if (!value) return '—'
  const date = new Date(`${String(value).slice(0, 10)}T12:00:00`)
  if (Number.isNaN(date.getTime())) return '—'
  return date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' })
}

export function relTime(value) {
  if (!value) return '—'
  const minutes = Math.round((Date.now() - new Date(value).getTime()) / 60000)
  if (minutes < 2) return 'now'
  if (minutes < 60) return `${minutes}m ago`
  const hours = Math.round(minutes / 60)
  if (hours < 24) return `${hours}h ago`
  const days = Math.round(hours / 24)
  if (days < 30) return `${days}d ago`
  return `${Math.round(days / 30)}mo ago`
}

export function initials(name) {
  return String(name || '?')
    .split(/[\s-]+/)
    .map(word => word.charAt(0))
    .slice(0, 2)
    .join('')
    .toUpperCase()
}

/** Stable colour per person id (avatars without images). */
export function personColor(id) {
  const palette = ['#e2419f', '#38bdf8', '#22c55e', '#f59e0b', '#a855f7', '#14b8a6', '#f05252', '#6366f1']
  let sum = 0
  String(id || '').split('').forEach(char => { sum += char.charCodeAt(0) })
  return palette[sum % palette.length]
}

/** Due date → `{ text, tone }` (`tone` maps to a daisyUI text class). */
export function dueLabel(task) {
  if (!task) return { text: '—', tone: '' }
  const left = task.days_until_due
  if (left === null || left === undefined) return { text: fmtDate(task.due_date), tone: '' }
  if (left < 0) return { text: `${Math.abs(left)}d late`, tone: 'text-error' }
  if (left === 0) return { text: 'due today', tone: 'text-warning' }
  if (left === 1) return { text: 'due tomorrow', tone: 'text-warning' }
  return { text: fmtDate(task.due_date), tone: 'opacity-60' }
}

/**
 * Builds a polyline `d` attribute for an inline SVG chart.
 * Coordinates are computed here (not in the template) so the sections only
 * render strings.
 */
export function seriesPath(values, { width = 720, height = 180, pad = 10, max: forcedMax } = {}) {
  const numbers = (values || []).map(value => Number(value) || 0)
  if (!numbers.length) return ''
  const max = forcedMax || Math.max(1, ...numbers)
  const stepX = numbers.length > 1 ? (width - pad * 2) / (numbers.length - 1) : 0
  return numbers
    .map((value, index) => {
      const x = pad + stepX * index
      const y = pad + (height - pad * 2) * (1 - value / max)
      return `${index === 0 ? 'M' : 'L'}${x.toFixed(1)} ${y.toFixed(1)}`
    })
    .join(' ')
}

/* ── Composable ───────────────────────────────────────────────────────────── */

export function useManagementDashboard() {
  const stored = readStoredPreferences()

  const state = reactive({
    section: stored.section || 'pulse',
    range: stored.range || 'week',
    railOpen: false,
    loading: {},
    error: {},
    lastUpdated: null,
    filters: Object.assign(defaultFilters(), stored.filters || {}),
    selectedTaskId: null,
    selectedMemberId: null,
    assistant: { open: false, thinking: false, messages: [] }
  })

  const data = reactive({
    projects: [],
    people: [],
    boards: [],
    dashboard: null,
    tasks: null,
    forecast: [],
    teamLoad: [],
    teamTasks: [],
    cost: null,
    burndown: null
  })

  /* ── Range / filters ─────────────────────────────────────────────────── */

  const bounds = computed(() => {
    const range = RANGES.find(entry => entry.id === state.range) || RANGES[1]
    return { from: dayOffset(-range.days), to: todayISO() }
  })

  const rangeLabel = computed(() => {
    const range = RANGES.find(entry => entry.id === state.range) || RANGES[1]
    return range.id === 'today' ? 'today' : `last ${range.days} days`
  })

  function setRange(id) {
    if (!RANGES.some(entry => entry.id === id) || state.range === id) return
    state.range = id
    // The window changed: every other section is stale. They reload on visit.
    Object.keys(data).forEach((key) => {
      if (key === 'projects' || key === 'people' || key === 'boards') return
      if (key !== sectionDataKey(state.section)) data[key] = Array.isArray(data[key]) ? [] : null
    })
    persist()
    load(state.section)
  }

  function setSection(id) {
    if (!SECTIONS.some(section => section.id === id)) return
    state.section = id
    state.railOpen = false
    persist()
    load(id)
  }

  /** Patch one section filter; resets its pagination (Work) when relevant. */
  function setFilter(scope, patch) {
    const target = state.filters[scope]
    if (!target) return
    Object.assign(target, patch)
    if ('page' in target && !('page' in patch)) target.page = 1
    persist()
  }

  function clearFilters(scope) {
    state.filters[scope] = defaultFilters()[scope]
    persist()
    load(state.section)
  }

  function sectionDataKey(section) {
    return {
      pulse: 'dashboard',
      work: 'tasks',
      blockers: 'dashboard',
      delivery: 'forecast',
      team: 'teamLoad',
      cost: 'cost'
    }[section] || 'dashboard'
  }

  /* ── Loading ─────────────────────────────────────────────────────────── */

  const requestKey = { current: 0 }

  async function load(section = state.section) {
    const loader = LOADERS[section]
    if (!loader) return
    const token = ++requestKey.current
    state.loading[section] = true
    state.error[section] = null

    try {
      await loader()
      if (token !== requestKey.current) return
      state.lastUpdated = new Date()
    } catch (error) {
      if (token !== requestKey.current) return
      state.error[section] = error?.message || String(error)
    } finally {
      if (token === requestKey.current) state.loading[section] = false
    }
  }

  const LOADERS = {
    async pulse() {
      const payload = await api().overview(bounds.value)
      data.projects = payload.projects
      data.dashboard = payload.dashboard
      data.forecast = payload.forecast
      data.teamLoad = payload.teamLoad
      data.cost = payload.cost
      data.boards = payload.dashboard.board_progress
    },
    async work() {
      const filters = state.filters.work
      const payload = await api().tasks({
        ...bounds.value,
        project_id: filters.project_id || undefined,
        board_id: filters.board_id || undefined,
        statuses: filters.status ? [filters.status] : [],
        priorities: filters.priority ? [filters.priority] : [],
        assignees: filters.assignee ? [filters.assignee] : [],
        search: filters.search || undefined,
        sort: { field: filters.sort, dir: filters.dir },
        page: filters.page,
        page_size: filters.page_size
      })
      data.tasks = payload
      data.boards = payload.boards
      data.projects = payload.projects
      data.people = payload.people
    },
    async blockers() {
      const payload = await api().blockers({
        ...bounds.value,
        project_id: state.filters.blockers.project_id || undefined
      })
      data.dashboard = payload.dashboard
      data.projects = payload.projects
      if (!state.filters.delivery.board_id) {
        data.boards = payload.dashboard.board_progress
      }
    },
    async delivery() {
      const payload = await api().delivery({
        ...bounds.value,
        board_id: state.filters.delivery.board_id || undefined
      })
      data.forecast = payload.forecast
      data.burndown = payload.burndown
      data.projects = payload.projects
      if (!state.filters.delivery.board_id && payload.burndown) {
        state.filters.delivery.board_id = payload.burndown.board_id
      }
    },
    async team() {
      const payload = await api().team(bounds.value)
      data.teamLoad = payload.teamLoad
      data.teamTasks = payload.tasks
      data.projects = payload.projects
    },
    async cost() {
      const payload = await api().cost({
        ...bounds.value,
        project_id: state.filters.cost.project_id || undefined,
        model: state.filters.cost.model || undefined
      })
      data.cost = payload
      data.projects = payload.projects
      data.people = payload.people
    }
  }

  function refresh() {
    return load(state.section)
  }

  /** People list for the "reassign" dialog (loaded on demand). */
  async function ensurePeople() {
    if (data.people.length) return data.people
    try {
      const payload = await api().tasks({ ...bounds.value, page_size: 1 })
      data.people = payload.people
      data.projects = data.projects.length ? data.projects : payload.projects
    } catch (error) {
      data.people = []
    }
    return data.people
  }

  /* ── Mutations ───────────────────────────────────────────────────────── */

  async function patchTask(id, patch, message) {
    try {
      const updated = await api().updateTask(id, patch)
      // Re-read the section so every aggregate that depends on the task (KPIs,
      // attention queue, forecast) is consistent with the write.
      await load(state.section)
      if (message) notify(message)
      return updated
    } catch (error) {
      notify(`Update failed: ${error?.message || error}`, 'error')
      return null
    }
  }

  const notices = reactive({ items: [] })

  function notify(text, tone = 'success') {
    const id = `${Date.now()}-${Math.random().toString(16).slice(2)}`
    notices.items.push({ id, text, tone })
    setTimeout(() => {
      const index = notices.items.findIndex(item => item.id === id)
      if (index >= 0) notices.items.splice(index, 1)
    }, 3000)
  }

  function openTask(id) {
    state.selectedTaskId = id
  }

  function closeOverlays() {
    state.selectedTaskId = null
    state.selectedMemberId = null
  }

  function openMember(id) {
    state.selectedMemberId = id
  }

  async function resetMock() {
    api().reset()
    Object.keys(data).forEach((key) => { data[key] = Array.isArray(data[key]) ? [] : null })
    await load(state.section)
    notify('Mock data regenerated')
  }

  /* ── Assistant ───────────────────────────────────────────────────────── */

  const SUGGESTIONS = [
    'What is blocking the delivery?',
    'Where did the AI budget go?',
    'Who is overloaded?',
    'What ships next week?',
    'What did we finish this week?'
  ]

  function toggleAssistant(open) {
    state.assistant.open = open === undefined ? !state.assistant.open : !!open
  }

  async function ask(question) {
    const text = String(question || '').trim()
    if (!text) return
    state.assistant.open = true
    state.assistant.thinking = true
    state.assistant.messages.push({ role: 'user', text })

    try {
      const answer = await api().ask({ question: text, ...bounds.value })
      state.assistant.messages.push({ role: 'bot', text: answer.answer, sources: answer.sources || [] })
    } catch (error) {
      state.assistant.messages.push({ role: 'bot', text: `I could not answer: ${error?.message || error}` })
    } finally {
      state.assistant.thinking = false
      state.assistant.messages = state.assistant.messages.slice(-20)
    }
  }

  /* ── Derived: shared ─────────────────────────────────────────────────── */

  const metrics = computed(() => data.dashboard?.metrics || {
    total: 0, done: 0, active: 0, on_hold: 0, overdue: 0, due_today: 0,
    unassigned: 0, blocked: 0, completion: 0, by_status: {}, by_priority: {}
  })

  const attention = computed(() => data.dashboard?.attention || [])

  const activity = computed(() => data.dashboard?.activity || [])

  const boardProgress = computed(() => data.dashboard?.board_progress || [])

  const forecast = computed(() => data.forecast || [])

  const nextDemo = computed(() => {
    return forecast.value
      .filter(board => board.demo_date)
      .sort((a, b) => (a.demo_date < b.demo_date ? -1 : 1))[0] || null
  })

  const atRiskBoards = computed(() => forecast.value.filter(board => board.status !== 'on_track'))

  const attentionByProject = computed(() => {
    const map = new Map()
    attention.value.forEach((item) => {
      const key = item.task.project_name
      map.set(key, (map.get(key) || 0) + 1)
    })
    return [...map.entries()].map(([name, total]) => ({ name, total })).sort((a, b) => b.total - a.total)
  })

  const oldestBlocker = computed(() => {
    const blocked = attention.value.filter(item => item.reason === 'blocked')
    if (!blocked.length) return 0
    return Math.max(...blocked.map(item => (
      Math.abs(Math.round((Date.now() - new Date(item.task.blocked_since || item.task.updated_at).getTime()) / 86400000))
    )))
  })

  /* ── Derived: blockers ───────────────────────────────────────────────── */

  const filteredAttention = computed(() => {
    const filters = state.filters.blockers
    return attention.value.filter((item) => {
      if (filters.reason !== 'all' && item.reason !== filters.reason) return false
      if (filters.project_id && item.task.project_id !== filters.project_id) return false
      return true
    })
  })

  const attentionCounts = computed(() => {
    const counts = {}
    attention.value.forEach((item) => { counts[item.reason] = (counts[item.reason] || 0) + 1 })
    return counts
  })

  /* ── Derived: delivery ───────────────────────────────────────────────── */

  const burndownChart = computed(() => {
    const points = data.burndown?.points || []
    const width = 720
    const height = 170
    const max = Math.max(1, ...points.map(point => Math.max(point.ideal, point.actual)))
    return {
      width,
      height,
      ideal: seriesPath(points.map(point => point.ideal), { width, height, max }),
      actual: seriesPath(points.map(point => point.actual), { width, height, max }),
      labels: points.filter((_, index) => index % 3 === 0 || index === points.length - 1),
      points
    }
  })

  const milestones = computed(() => {
    return forecast.value
      .filter(board => board.demo_date)
      .sort((a, b) => (a.demo_date < b.demo_date ? -1 : 1))
  })

  /* ── Derived: team ───────────────────────────────────────────────────── */

  const teamMembers = computed(() => {
    const filters = state.filters.team
    return (data.teamLoad || [])
      .filter((person) => {
        if (filters.type !== 'all' && person.type !== filters.type) return false
        if (filters.project_id && !person.project_ids.includes(filters.project_id)) return false
        if (filters.onlyHot && person.load_pct < 85) return false
        return true
      })
      .slice()
      .sort((a, b) => b.load_pct - a.load_pct)
  })

  const teamSummary = computed(() => {
    const all = data.teamLoad || []
    const humans = all.filter(person => person.type === 'human')
    return {
      humans: humans.length,
      agents: all.filter(person => person.type === 'agent').length,
      averageLoad: humans.length
        ? Math.round(humans.reduce((sum, person) => sum + person.load_pct, 0) / humans.length)
        : 0,
      overloaded: humans.filter(person => person.load_pct >= 85).length,
      cost: all.reduce((sum, person) => sum + person.cost_cxjcoins, 0)
    }
  })

  const selectedMember = computed(() => {
    if (!state.selectedMemberId) return null
    return (data.teamLoad || []).find(person => person.id === state.selectedMemberId) || null
  })

  const selectedMemberTasks = computed(() => {
    if (!selectedMember.value) return []
    const pool = data.teamTasks.length ? data.teamTasks : (data.tasks?.tasks || [])
    return pool.filter(task => task.assignees.includes(selectedMember.value.id))
  })

  /* ── Derived: cost ───────────────────────────────────────────────────── */

  const costChart = computed(() => {
    const cost = data.cost
    const width = 720
    const height = 200
    if (!cost?.daily?.length) return { width, height, series: [], labels: [] }

    const series = []
    const filters = state.filters.cost.series
    if (filters.cost) {
      series.push({
        id: 'cost',
        color: '#e2419f',
        values: cost.daily.map(entry => entry.total_cxjcoins),
        path: ''
      })
    }
    if (filters.tokens) {
      series.push({
        id: 'tokens',
        color: '#38bdf8',
        values: cost.daily.map(entry => entry.total_tokens),
        path: ''
      })
    }
    if (filters.calls) {
      series.push({
        id: 'calls',
        color: '#22c55e',
        values: cost.daily.map(entry => entry.calls),
        path: ''
      })
    }

    // One shared scale: the series are read against their own maximum so a
    // heavy one never flattens the others into the axis.
    series.forEach((entry) => {
      entry.path = seriesPath(entry.values, { width, height })
    })

    return {
      width,
      height,
      series,
      labels: cost.daily.filter((_, index) => index % Math.max(1, Math.ceil(cost.daily.length / 6)) === 0)
    }
  })

  const costByProject = computed(() => {
    const groups = data.cost?.by_project || {}
    return Object.entries(groups)
      .map(([name, metricsValue]) => ({
        name,
        color: data.projects.find(project => project.name === name)?.color || 'var(--p, #e2419f)',
        ...metricsValue
      }))
      .sort((a, b) => b.total_cxjcoins - a.total_cxjcoins)
  })

  const costByModel = computed(() => {
    const groups = data.cost?.by_model || {}
    return Object.entries(groups)
      .map(([name, metricsValue]) => ({ name, ...metricsValue }))
      .sort((a, b) => b.total_cxjcoins - a.total_cxjcoins)
  })

  const costByPerson = computed(() => {
    const groups = data.cost?.by_user || {}
    return Object.entries(groups)
      .map(([name, metricsValue]) => ({ name, ...metricsValue }))
      .sort((a, b) => b.total_cxjcoins - a.total_cxjcoins)
  })

  /* ── Derived: work ───────────────────────────────────────────────────── */

  const workTasks = computed(() => data.tasks?.tasks || [])

  const workPager = computed(() => {
    const payload = data.tasks || { total: 0, page: 1, page_size: 12, total_pages: 1 }
    const start = payload.total ? (payload.page - 1) * payload.page_size + 1 : 0
    const end = Math.min(payload.total, payload.page * payload.page_size)
    const pages = []
    for (let page = 1; page <= payload.total_pages; page += 1) {
      const far = payload.total_pages > 7 && page > 2 && page < payload.total_pages - 1 && Math.abs(page - payload.page) > 1
      if (far && pages[pages.length - 1] !== '…') {
        pages.push('…')
        continue
      }
      if (!far) pages.push(page)
    }
    return { start, end, pages, total: payload.total, page: payload.page, hasPrev: payload.has_prev, hasNext: payload.has_next }
  })

  const selectedTask = computed(() => {
    if (!state.selectedTaskId) return null
    const pools = [
      workTasks.value,
      attention.value.map(item => item.task),
      (data.teamTasks || [])
    ]
    for (const pool of pools) {
      const found = pool.find(task => task.id === state.selectedTaskId)
      if (found) return found
    }
    return null
  })

  /* ── Persistence (best effort: a strict browser may block storage) ───── */

  function persist() {
    try {
      window.localStorage.setItem(STORE_KEY, JSON.stringify({
        section: state.section,
        range: state.range,
        filters: state.filters
      }))
    } catch (error) {
      /* storage disabled: preferences live only for this session */
    }
  }

  function readStoredPreferences() {
    try {
      const raw = window.localStorage.getItem(STORE_KEY)
      if (!raw) return {}
      const parsed = JSON.parse(raw)
      const filters = defaultFilters()
      Object.keys(filters).forEach((scope) => {
        if (parsed.filters?.[scope]) filters[scope] = Object.assign(filters[scope], parsed.filters[scope])
      })
      return { section: parsed.section, range: parsed.range, filters }
    } catch (error) {
      return {}
    }
  }

  /* ── Public object (one reactive bag for every section) ──────────────── */

  return reactive({
    // configuration
    RANGES,
    SECTIONS,
    STATUS_META,
    PRIORITY_META,
    REASON_META,
    SUGGESTIONS,
    // state
    state,
    data,
    notices,
    bounds,
    rangeLabel,
    // derived — shared
    metrics,
    attention,
    activity,
    boardProgress,
    forecast,
    nextDemo,
    atRiskBoards,
    attentionByProject,
    oldestBlocker,
    // derived — blockers
    filteredAttention,
    attentionCounts,
    // derived — delivery
    burndownChart,
    milestones,
    // derived — team
    teamMembers,
    teamSummary,
    selectedMember,
    selectedMemberTasks,
    // derived — cost
    costChart,
    costByProject,
    costByModel,
    costByPerson,
    // derived — work
    workTasks,
    workPager,
    selectedTask,
    // navigation / filters
    setRange,
    setSection,
    setFilter,
    clearFilters,
    // loading
    load,
    refresh,
    ensurePeople,
    // mutation
    patchTask,
    notify,
    resetMock,
    // overlays
    openTask,
    openMember,
    closeOverlays,
    // assistant
    toggleAssistant,
    ask,
    // helpers for templates
    fmtNum,
    fmtCoins,
    fmtDate,
    relTime,
    initials,
    personColor,
    dueLabel
  })
}

