    // the task is opened in its own window / panel.
    onOpenTaskWindow(task) {
      if (!task) return
      this.selectedTaskId = task.id
      this.$chats.setActiveChat(task)
    },
    closeSideTask() {
      this.sideTaskId = null
    },
    onUpdateSearch(query) {
      this.searchQuery = query
    },
