<template>
  <!--
    Identity of the assistant that answers: the avatar of the profile that
    assists managers (ProjectManager). Falls back to a role icon when the
    profile has no image, so the element never collapses to an empty box.

    `showName` renders the assistant name right next to the avatar — that is how
    the panel header shows "who is answering" (avatar + name, one control).
  -->
  <span class="inline-flex items-center gap-1.5 min-w-0 align-middle">
    <span
      class="rounded-full grid place-items-center overflow-hidden shrink-0 bg-base-300 border border-base-content/10"
      :class="sizeClass"
      :title="name"
    >
      <img v-if="avatarUrl" :src="avatarUrl" :alt="name" class="w-full h-full object-cover" />
      <i v-else class="fa-solid fa-user-tie text-primary" :class="iconClass"></i>
    </span>
    <span v-if="showName" class="text-xs font-semibold truncate" :title="name">{{ name }}</span>
  </span>
</template>

<script>
import {
  assistantAvatarUrl,
  findAssistantProfile,
  loadProjectProfiles,
  projectIdOf
} from '@/views/management/useAssistantProfile'

export default {
  name: 'AssistantAvatar',
  props: {
    // Project the assistant belongs to (live store project or `{ id }` row)
    project: { type: Object, default: null },
    // Profile that assists managers — its avatar is the assistant identity
    profileName: { type: String, default: 'ProjectManager' },
    // xs | sm | md | lg
    size: { type: String, default: 'sm' },
    // Render the assistant name next to the avatar
    showName: { type: Boolean, default: false }
  },
  data() {
    return { profile: null }
  },
  watch: {
    // Another project brings another ProjectManager profile
    project: {
      handler() { this.load() },
      immediate: true
    },
    profileName() { this.load() }
  },
  computed: {
    avatarUrl() {
      return assistantAvatarUrl(this.profile)
    },
    name() {
      return this.profile?.name || this.profileName
    },
    sizeClass() {
      return {
        xs: 'w-5 h-5',
        sm: 'w-7 h-7',
        md: 'w-9 h-9',
        lg: 'w-12 h-12'
      }[this.size] || 'w-7 h-7'
    },
    iconClass() {
      return {
        xs: 'text-[9px]',
        sm: 'text-[11px]',
        md: 'text-sm',
        lg: 'text-lg'
      }[this.size] || 'text-[11px]'
    }
  },
  methods: {
    async load() {
      const id = projectIdOf(this.project)
      if (!id) {
        this.profile = null
        return
      }
      const list = await loadProjectProfiles(this.project)
      // A slower response for a previous project must not overwrite the current
      if (projectIdOf(this.project) !== id) return
      this.profile = findAssistantProfile(list, this.profileName)
    }
  }
}
</script>
