                      </span>
                    </span>
                  </span>
                  <span class="badge badge-xs" :class="d.REASON_META[item.reason]?.badge">{{ reasonLabel(item.reason) }}</span>
                  <i class="fa-solid fa-chevron-right text-[10px] opacity-40"></i>
                </button>
              </div>
