    />

    <section v-if="d.state.assistant.open"
             class="fixed z-50 flex flex-col bg-base-100 border border-base-300 shadow-2xl"
             :class="compact ? 'inset-x-0 bottom-0 h-[80vh] rounded-t-box' : 'right-4 bottom-4 w-96 h-[34rem] rounded-box'"
             aria-label="Assistant chat">
      <!-- Who answers: the ProjectManager avatar with its name next to it -->
